//   倍しただけの仮置きで、moveto の duration(0.833333) にだけ倍率がかからず
//   「降下 lifeTime 0.664327 < 降下 duration 0.833333」＝ 降下の途中でボスが消えて
//   本体が着地点へ瞬間移動する、という破綻が残っていた。曲とも合っていない。
