const GATHER_SPIN = 4.0;                 // 飛んでいるあいだの自転（rad/s）


// マーカー 22〜26 の相対間隔。27 の 2 巡目と 29/31 の「again」はこれを写して作る。
const METEOR_TIMES_1 = [MK22_METEOR1, MK23_METEOR2, MK24_METEOR3, MK25_METEOR4, MK26_METEOR5];
const METEOR_OFFSETS = METEOR_TIMES_1.map((t) => t - MK22_METEOR1);
// v27 (10): 手打ち 73.356「こっから新弾幕。右列にタイルを予告後表示し、1 拍後に左向きの
//   重力で動かす。画面外まで行ったら消す。一回に 4 個程度のタイル」＋
//   74.118 / 75.138 / 75.972 の 3 点。隕石の 2 巡目（旧 METEOR_TIMES_2）を丸ごと差し替える。
//   頭は現行の採用時刻 MK27_METEOR_REP（73.3228・手打ちの -33 ms）、以降は 2 拍グリッド
//   （74.1561 / 74.9895 / 75.8228 ＝ 手打ちの +38 / -148 / -149 ms）。
const V27_SLIDE_TIMES_D = [0, 2, 4, 6].map(function (k) { return MK27_METEOR_REP + beats(k); });
// マーカー 28: 拍に合わせて等間隔 8 回（1 拍 = 0.41667s → 8 回で 2.917s。29 の 80.010s 手前に収まる）
const METEOR_TIMES_8 = Array.from({ length: 8 }, (_, i) => MK28_METEOR8 + i * BEAT);
// マーカー 18〜21 の相対間隔。29/31 の「again」はこれを写す。
const SLIDE_TIMES_A = [MK18_SLIDE1, MK19_SLIDE2, MK20_SLIDE3, MK21_SLIDE4];
const SLIDE_OFFSETS = SLIDE_TIMES_A.map((t) => t - MK18_SLIDE1);
const SLIDE_TIMES_B = SLIDE_OFFSETS.map((d) => MK29_SLIDE_AGAIN + d);    // 80.010〜82.417s
const SLIDE_TIMES_C = SLIDE_OFFSETS.map((d) => MK31_SLIDE_AGAIN2 + d);   // 86.875〜89.282s
// マーカー 30: 2 拍間隔で 5 回（83.229〜86.563s。31 の 86.875s 手前に収まる）
const TILE5_TIMES = Array.from({ length: 5 }, (_, i) => MK30_TILE5 + i * 2 * BEAT);
// マーカー 32: 1 拍間隔で 6 回（90.012〜92.096s）
const TILE6_TIMES = Array.from({ length: 6 }, (_, i) => MK32_TILE_SHOW + i * BEAT);
// マーカー 33〜36: 1 回 2 枚の爆破を 4 回
const BLAST2_TIMES = [MK33_BLAST1, MK34_BLAST2, MK35_BLAST3, MK36_BLAST4];
// マーカー 30/32 で積んだ帯タイルを消す時刻。マーカー 38 の横の鎖が最後の段まで
// 通り過ぎた直後（99.0625 + 34 × 0.0357 = 100.28s）に置く。鎖で掃かれなかった
// 取りこぼしがここで消えて、「38 で全部消えた状態」が成立する。
const V21_BAND_END = 100.60;

const S10_BEAT = 88;               // 小節23-24 36.667s タイル爆破③（アクセントに乗せる）
// v19: 小節25〜32（40.000〜53.333s）の仮区間⑪⑫⑬⑭は指示書のマーカー 9〜17 に
//   置き換えたので、拍番号の定数も削除した（時刻は MK9_WARN1 以降を参照）。
const S15_BEAT = 128;              // 小節33-34 53.333s 休符（横断シャベルの往復・行ずらし）
const S16_BEAT = 136;              // 小節35-36 56.667s 落下シャベル④＋放射弾増量（頂点）
const EXT_END_BEAT = 144;          // 60.000s 次のセクションの頭＝残タイル消去

// --- 画面グリッド（正方セル）------------------------------------------------
// playArea 32x18 を 16列 x 9行に割ると 1マス 2x2 の正方形になる。
const COLS = 16;
const ROWS = 9;
const CELL = 2;              // 正方セル（幅=高さ）
const TILE = CELL * 0.92;    // タイル本体（目地ぶん少し小さい正方形）

function cellCenter(col, row) {
  return [CELL * (col + 0.5), CELL * (row + 0.5)];
}
function key(col, row) {
  return col + ',' + row;
}

// v10: 縁の帯（上下左右すべて BAND セルぶん）＝ここに出たタイルは拍末で消さず溜める。
// v11: BAND 3 → 2。16x9・BAND=2 なら 帯 = 列 0-1 / 14-15 と 行 0-1 / 7-8 の 84 セル、
// 内側（中央）= 列 2-13 x 行 2-6 の 12x5 = 60 セル。中央のタイルは拍末で必ず消す。
const BAND = 2;
function isBandCell(col, row) {
  return col < BAND || col >= COLS - BAND || row < BAND || row >= ROWS - BAND;
}

const BAND_CELLS = [];
const CENTER_CELLS = [];
for (let row = 0; row < ROWS; row++) {
  for (let col = 0; col < COLS; col++) {
    (isBandCell(col, row) ? BAND_CELLS : CENTER_CELLS).push([col, row]);
  }
}

// v13 (B): 延長区間で使う「帯」の変奏。区間⑨は上下だけ、区間⑬は左右だけに溜める。
//   セルの総数は 上下 = 16列 x 4行 = 64 / 左右 = 4列 x 9行 = 36。
//   帯の埋まり率の目標（BAND_TARGET）は同じなので、新規タイルの枚数はセル数に比例して減る。
// v22: マーカー 43 の「端っこも中央も残す」タイル表示で使う全セル（144 枚）。
const ALL_CELLS = [];

const BAND_CELLS_TB = [];   // 上下だけ（行 0-1 と 7-8 の全列）
const BAND_CELLS_LR = [];   // 左右だけ（列 0-1 と 14-15 の全行）
for (let row = 0; row < ROWS; row++) {
  for (let col = 0; col < COLS; col++) {
    if (row < BAND || row >= ROWS - BAND) BAND_CELLS_TB.push([col, row]);
    if (col < BAND || col >= COLS - BAND) BAND_CELLS_LR.push([col, row]);
  }
}

// v10: 自機が通れることを保証するための連結判定。
// タイルは 1 セル（2x2）のほぼ全体（TILE=1.84）を占めるので、斜め隣は通れない。
// 「空きセルが 4 近傍で 1 つに繋がっている」を保てば、画面のどこからでもどこへでも
// 移動できる＝閉じ込めが起きない。タイルを 1 枚置くたびにこれを検査して、
// 崩す置き方は捨てる（帯が 6〜7 割埋まっても迷路状の通路が必ず残る）。
for (let c = 0; c < COLS; c++) for (let r = 0; r < ROWS; r++) ALL_CELLS.push([c, r]);

const NEIGHBOR_DC = [1, -1, 0, 0];
const NEIGHBOR_DR = [0, 0, 1, -1];
function emptyIsConnected(blocked) {
  const total = COLS * ROWS - blocked.size;
  if (total <= 0) return false;
  let start = null;
  for (let row = 0; row < ROWS && start === null; row++) {
    for (let col = 0; col < COLS; col++) {
      if (!blocked.has(key(col, row))) { start = [col, row]; break; }
    }
  }
  const seen = new Set([key(start[0], start[1])]);
  const stack = [start];
  while (stack.length > 0) {
    const cur = stack.pop();
    for (let d = 0; d < 4; d++) {
      const nc = cur[0] + NEIGHBOR_DC[d];
      const nr = cur[1] + NEIGHBOR_DR[d];
      if (nc < 0 || nc >= COLS || nr < 0 || nr >= ROWS) continue;
      const k = key(nc, nr);
      if (blocked.has(k) || seen.has(k)) continue;
      seen.add(k);
      stack.push([nc, nr]);
    }
  }
  return seen.size === total;
}

// v10: 帯タイルを 4 辺のどれに属するとみなすか（爆破対象を左右上下へ散らすために使う）。
function sideOf(col, row) {
  const dl = col;
  const dr = COLS - 1 - col;
  const db = row;
  const dt = ROWS - 1 - row;
  if (Math.min(dl, dr) <= Math.min(db, dt)) return dl <= dr ? 'left' : 'right';
  return db <= dt ? 'bottom' : 'top';
}
const SIDE_ORDER = ['left', 'top', 'right', 'bottom'];

// --- 色（v18: タイルテクスチャの色相に統一。v11 の値を色相だけ寄せたもの）------------
//
// ★v18: タイルのスプライトがユーザー生成のドット絵テクスチャ（.tmp_tex/5d98ed95….png を
//   64 ドットへ縮小したもの。Tools/gen_stone3_pixel.py）に置き換わった。抽出した 4 色は
//     面 (77,67,93) / 縁明 (116,102,134) / 縁暗 (55,48,67) / 欠片 (40,34,48)
//   で、色相は HSV H≈263〜266 度（平均 264 度）の青紫。v11 の予告色は H=240 度の
//   無彩色寄りだったので、**明度（HSV の V）と彩度は据え置いたまま色相だけ H=264 度へ寄せた**。
//   予告の明暗の段（強ハイライト→ハイライト→影→最暗）は v17 とまったく同じ順序・同じ V なので、
//   予告の読みやすさと拍の見え方は変わらず、色味だけがタイルと揃う。
//   例外は STONE_TILE_END（ポップの収束先）で、これはタイルの面色そのものに合わせる必要が
//   あるため (104,104,140) → (77,67,93) と暗くした。ここがずれると収束の瞬間に色が飛ぶ。
//
// 基準色 = stone_block.png（タイルのスプライト）。無彩色の石テクスチャで、不透明部の平均 sRGB は
// (171,171,171)・分布 70〜245。既存の石工ステージも stone_block を color.w=0 で 467 発使っている。
//
// ★色空間: BulletBuffer の color は **linear 値**で、画面に出るのは sRGB へ変換された色。
//   下の各定数はまず「出したい sRGB」を決め、sRGB→linear で変換した値を書いてある
//   （コメントの (r,g,b) が実際に見える sRGB）。
//
// ★alpha（w）の意味: BulletIndirectURP.shader:283-291 で color.w は「着色するかどうか」の
//   フラグでしかなく（w>0 なら RGB を完全適用・描画アルファは 1）、値の大小は見た目に出ない。
//   w=0 だけが特別で「スプライトのテクスチャそのまま」を意味する（hummer/cutter/warn_box の規約）。
//   予告が暗く見えるのは色ではなく appearDuration の予告窓（α 0.2〜0.5 の拍同期）による。
const SPRITE_AS_IS = [1, 1, 1, 0];                  // 無着色＝スプライトのテクスチャそのまま
const STONE_BRIGHT = [0.8070, 0.7305, 0.9387, 0.92];// (232,222,248) 強ハイライト: 爆破対象の点滅
const STONE_MID = [0.3813, 0.3050, 0.5149, 0.40];   // (166,150,190) ハイライト: 爆破予告・リング予告
const STONE_WARN = [0.0908, 0.0648, 0.1384, 0.40];  // ( 85, 72,104) 影: タイル出現の予告
const STONE_PATH = [0.0395, 0.0273, 0.0648, 0.25];  // ( 56, 46, 72) 最暗: 落下シャベルの縦帯
// ポップの収束先。v18 でタイルの面色 sRGB(77,67,93) に相当する linear 値へ更新（旧 104,104,140）。
// 補間の終端で w が 0 になった瞬間に「実体タイルのテクスチャそのまま」へ入れ替わる（tilePop 参照）。
const STONE_TILE_END = [0.0742, 0.0561, 0.1095, 0];

// --- 決定論的乱数（mulberry32）--------------------------------------------
function makeRng(seed) {
  let a = seed >>> 0;
  return function next() {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// 配列をシャッフルした新しい配列を返す（rng は呼び出し側の mulberry32）。
function shuffled(arr, rng) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    const t = a[i];
    a[i] = a[j];
    a[j] = t;
  }
  return a;
}

// --- タイル群 --------------------------------------------------------------
// 1フレーム継ぎ目対策（OPUS-DEV-KNOWLEDGE §2）: 予告→実体の切替で1フレーム欠けないよう、
// 退場する側（予告）の life に微小余白を足して実体側と重ねる。予告は無害なので重なってよい。
const SEAM_MARGIN = 0.034;
// 爆破対象タイルは放射開始と同時かわずかに前に消す（v2 で爆破中心にタイルが残るフレームがあった）。
const BLAST_LEAD_OUT = 0.02;

const NEUTRAL_SPAWNER = () => ({
  pos: { x: 0, y: 0 },
  originVlc: { x: 0, y: 0 },
  angle: 0,
  angleInterval: 0,
  color: { x: 1, y: 1, z: 1, w: 1 },
  count: 1,
  interval: 0,
});

// tileField(): cells に一括でタイルを置く（1バッファ = 1クリップ）。
function tileField(cells, opts) {
  const { type, color, appearTime = 0, appearDuration = 0, life, kind } = opts;
  const bullets = cells.map(function (cell) {
    const center = cellCenter(cell[0], cell[1]);
    return bulletDefaults({
      originPos: { x: center[0], y: center[1] },
      typeName: type,
      scale: { x: TILE, y: TILE },
      color: { x: color[0], y: color[1], z: color[2], w: color[3] },
      appearTime,
      appearDuration,
      life,
      unCounterable: true,
    });
  });
  return {
    parts: [{ offsetSec: 0, kind, buffer: { bullets, homing: false, isLaser: false }, spawner: NEUTRAL_SPAWNER() }],
  };
}

// spinBurst(): 自転する弾の全周放射バースト。
// ring() は spawner.count/angleInterval で複製するぶん自転パラメータを持てないので、
// spiral() と同じく弾を1発ずつ Cartesian で組み、cutter()/spiral() の視覚回転トリック
// （useVelocityAngle:false + polarForm + thetaVlc）を各弾に付ける。
// startPos/polynomial/speed が既定値の弾では polarForm は位置に影響しないため、
// 移動は originVlc による等速直線（無重力）のまま、描画角だけが spin(rad/s) で回り続ける。
function spinBurst(opts) {
  const {
    pos, count, speed, spin,
    type = 'box', life = 0, scale = [1, 1], color = [1, 1, 1, 1],
    angleOffset = 0, unCounterable = true, kind = 'spinburst',
  } = opts;
  const bullets = [];
  for (let i = 0; i < count; i++) {
    const angle = angleOffset + (i * 2 * Math.PI) / count;
    const dx = normalizeNegativeZero(Math.cos(angle));
    const dy = normalizeNegativeZero(Math.sin(angle));
    bullets.push(
      bulletDefaults({
        originPos: { x: pos[0], y: pos[1] },
        originVlc: { x: dx * speed, y: dy * speed },
        typeName: type,
        scale: { x: scale[0], y: scale[1] },
        color: { x: color[0], y: color[1], z: color[2], w: color[3] },
        life,
        unCounterable,
        useVelocityAngle: false,
        polarForm: { x: 1, y: normalizeNegativeZero(angle) },
        thetaVlc: spin,
      })
    );
  }
  return {
    parts: [{ offsetSec: 0, kind, buffer: { bullets, homing: false, isLaser: false }, spawner: NEUTRAL_SPAWNER() }],
  };
}

// --- v5: 予告表示（当たり判定なし）の共通クリップ ---------------------------
// warnClip(): warn_box の予告を1クリップにまとめる。
//   items = [{ pos:[x,y], scale:[w,h], color:[r,g,b,a], appearTime, appearDuration, life }]
//   時刻は全てクリップ発火時刻からの相対秒。
//   appearDuration>0 … その区間は「予告点滅」表示（BulletRenderSystem.cs:270 の fadeIn 分岐）
//   appearDuration=0 … appearTime までは完全に非表示（同 :286）。この性質を使うと
//     1クリップの中に時間差の点滅を全部詰め込めるので、点滅のためにクリップを量産せずに済む。
//   life は必ず正の値にする（life<=0 は「寿命なし」扱いで消えなくなる）。
//   v7: it.type で弾のタイプを選べるようにした（既定は従来どおり warn_box）。爆破タイルの
//   点滅だけは stone_flash（renderPriority 4）を使い、タイルより手前に重ねる必要がある。
//   v9: it.scaleEnd / it.colorEnd / it.animDuration を渡すと、ランタイムの出現アニメ
//   （BulletRenderSystem の線形補間）に乗る。指定した弾だけがこのキーを持つ。
function warnClip(items, kind) {
  const bullets = items.map(function (it) {
    const spec = {
      originPos: { x: it.pos[0], y: it.pos[1] },
      typeName: it.type || 'warn_box',
      scale: { x: it.scale[0], y: it.scale[1] },
      color: { x: it.color[0], y: it.color[1], z: it.color[2], w: it.color[3] },
      appearTime: it.appearTime || 0,
      appearDuration: it.appearDuration || 0,
      life: it.life,
      unCounterable: true,
    };
    if (it.animDuration > 0) {
      spec.scaleEnd = { x: it.scaleEnd[0], y: it.scaleEnd[1] };
      spec.colorEnd = { x: it.colorEnd[0], y: it.colorEnd[1], z: it.colorEnd[2], w: it.colorEnd[3] };
      spec.animDuration = it.animDuration;
    }
    return bulletDefaults(spec);
  });
  return {
    parts: [{ offsetSec: 0, kind, buffer: { bullets, homing: false, isLaser: false }, spawner: NEUTRAL_SPAWNER() }],
  };
}

// --- パラメータ ------------------------------------------------------------
// v11: タイル出現の予告リードを半拍 → 1 拍に延ばした（見えている時間が倍。サイズ・色は据え置き）。
// 前の拍の中央タイルと次の拍の予告が同じセルで重なる時間帯ができるが、予告は warn_box
// （renderPriority 0）＝ stone_block（同 1）より必ず奥に描かれるので実体を汚さない。
const WARN_BEATS = 1.0;    // タイル出現の予告リード（拍）
const BLAST_PER_BEAT = 2;  // 1拍あたりの爆破数
const GAPS_PER_BEAT = 2;   // 毎拍必ず空ける 3x3 の逃げ場の数
// v10: 爆破対象は「置かれてから BLAST_MIN_AGE 拍以上たったタイル」から選ぶ。
// 出現ポップと爆破予告の点滅（1拍前から）が同じ拍に重なるのを避けるため。
const BLAST_MIN_AGE = 2;
const SPIN_RATE = 5.0;     // 放射弾の自転速度(rad/s)
const BULLET_SCALE = 0.3;  // v4: v3 の 0.6 の半分。verts も scale 倍されるので当たり判定も半分

// v5: 予告のパラメータ
const BLINK_LEAD = beats(1);       // 点滅を始める時刻（爆破の1拍前）

// v7 (1): 爆破タイルの点滅（山型の明滅）。
// 重ねる弾は stone_flash（renderPriority 4 > stone_block の 1・verts 空＝当たり判定なし）。
// baseSprite/maskSprite が stone_block と同じなので、同じ scale・同じ座標に置くとタイルの
// 面にぴったり重なる（角丸の形まで一致する）。拡大しないので v6 のような「枠」にならない。
const BLINK_TYPE = 'stone3_flash';   // v12: stone_flash の複製（スプライトが stone3_tile）
// v26 (B): 拍頭のポップ（flashPop）専用の弾種。絵は stone3_tile.png と完全に同一で、
//   差し替えたのは **着色マスクだけ**（Tools/gen_stone3_pixel.py の build_pop_mask /
//   POP_CORNER_CUT=7）。
//   BulletIndirectURP.shader の通常弾パスは着色時に
//     tintStrength = mask * hasTint;  baseCol.a = max(baseCol.a, tintStrength) * appear;
//   とし、mask は **マスク画像の R チャンネル**を読む。従来の to_mask() は背景を
//   (255,255,255,0) で塗っていた＝アルファ 0 でも R は 255 で、インポート設定が
//   alphaIsTransparency のため透明部の色が保たれ、シェーダから見ると mask は全面 1 だった。
//   その結果、着色されたポップは絵の輪郭（角を 5 ドット落とした八角形）と無関係に
//   「128x128 の塗り潰し正方形」として描かれていた（実測: Captures/stone_v26_frames）。
//   stone3_pop のマスクは背景を不透明な黒にし、白い範囲を「絵が不透明なドット全部から
//   4 隅を 7 ドット落としたもの」にしてある。縁まで白いのでポップは今までどおり
//   一枚の閃光のままで、変わるのは角だけ。
//   タイル本体・予告・点滅・tilePop は stone3_flash / stone3_tile のまま（tilePop は
//   収束後に実体タイルと寸分違わず重なる前提なので形を変えない）。
const POP_TYPE = 'stone3_pop';
const FADE_OUT_SEC = 0.1;     // BulletRenderSystem.cs:13 disappearDuration（life 末尾の減衰時間）
const BLINK_SUB = 1 / 60;     // 山を作るコマの間隔（1ゲームフレーム相当）
const BLINK_STEPS = 6;        // 1山あたりのコマ数（hold=0 に解けたコマは出さない）
const BLINK_PEAK = 0.92;      // 山の頂点で狙う合成アルファ
const BLINK_PULSES = 4;       // 1拍あたりの山の数
const BLINK_ACCEL = 0.7;      // 山の間隔の縮み率（爆破へ向けて詰まる＝JSaB の加速する明滅）

// v7 (2): シャベルの経路予告の太さ。中心線ではなく「掃かれる幅」を予告する。
// stone3_shovel.png の刃の最大幅は実測 68px / 128px ＝ scale の 0.531 倍で、
// SHOVEL_SCALE 2.6 では 1.38（タイル 1.84 の 0.75 倍）。ただし実際に壊れるのはタイル1枚ぶん
// なので、帯は刃の実測幅を丸めてタイルと同じ幅にする（v5 の 0.6 から約3倍）。
const PATH_WIDTH = TILE;
// v23 (B)1: 爆破半拍前の小点 8 個のリング予告 ringWarn()（RING_LEAD/RING_COUNT/RING_RADIUS/
// RING_DOT）は削除した。点滅予告（blinkWarn）は残す。放射弾（spinBurst）はタイル消滅と
// 同時刻のまま（元々 BLAST_LEAD_OUT ぶん後ろにずらす設計ではなかったので、ここは無変更）。
const SWEEP_LEAD = beats(1);       // 横断シャベルの経路予告のリード（発射の1拍前）
// MARK_SIZE / MARK_INSET / MARK_HOLD（横断シャベルの方向マーク）は v8 で予告ごと削除した。

// v9: タイル実体化ポップのパラメータ（JSaB "Milky Ways" の実測 + ランタイムの出現アニメ）。
//
// ── 実測（参考動画 https://www.youtube.com/watch?v=UVpbc1aCJjU・60fps・1276x720）──
//   t=91.067s と t=90.367s の 2 枚のタイルで同一の値を確認した（実測画像は
//   Captures/ref_milkyways_pop_strip.png と ref_milkyways_pop_{f0,f2,settled}.png）。
//   1 枚のタイルは 119x119px（等倍）で、拍頭から 6 フレーム＝ちょうど 0.100 秒で収束する。
//   中心は動かず、同じ中心のまま縮む。
//     コマ | 経過      | 実測サイズ | 倍率  | 実測RGB
//     -----+-----------+-----------+-------+----------------
//      f0  | +0/60     | 204px     | 1.714 | (255,255,255) ＝ 完全な白（半透明ではない）
//      f1  | +1/60     | 177px     | 1.487 | (255,214,255)
//      f2  | +2/60     | 157px     | 1.319 | (255,159,224)
//      f3  | +3/60     | 142px     | 1.193 | (255,116,176)
//      f4  | +4/60     | 129px     | 1.084 | (255, 83,140)
//      f5  | +5/60     | 122px     | 1.025 | (255, 63,118)
//      --  | +6/60     | 119px     | 1.000 | (255, 58,111) ＝ 実体色（以後静止）
//   予告は同サイズ・枠なしで、実体と同じ色相の暗いタイル（v11 では STONE_WARN）。
//
// ── v8 の作り方と、その問題 ──
//   v8 は「静止した 6 枚のコマを 1/60 秒ずつずらして重ねる」方式だった。各コマは自分の
//   1 フレームぶんは α=1（不透明）だったが、そのあと life 末尾の 0.1 秒減衰に入るため、
//   一回り小さい次のコマからはみ出した部分が白〜灰色の輪郭として 0.06〜0.10 秒残った
//   （Captures/stone3_v8_pop_compare.png）。動画には無い見え方で、ユーザー評価も「雑」。
//
// ── v9 の作り方 ──
//   ランタイムに出現アニメ（scaleEnd / colorEnd / animDuration・既定 0 で従来動作）を足し、
//   1 タイルにつき stone_flash 1 発だけで拍頭〜収束までを表現する。
//     ・appearTime=0（＝拍頭）に scale 1.714 倍・純白で出る
//     ・animDuration=0.100 秒かけて scale 1.0 倍・実体色（v11 は STONE_TILE_END）へ線形補間される
//     ・補間が終わった時点で実体タイル（stone_block）と完全に同じ大きさ・同じ色になる
//     ・life = 0.100 + FADE_OUT_SEC(0.1)。減衰する 0.1 秒の間、この弾は実体タイルと
//       寸分違わず重なっているので、消えていく過程は画面上まったく見えない（継ぎ目なし）
//   重なるコマが 1 枚も無いので、v8 の白い輪郭は原理的に発生しない。
//   弾数も 1 タイル 6 発 → 1 発になり、tilepop の JSON は 17MB → 約 3MB に減る。
const POP_SCALE_START = 1.714;                      // 拍頭の倍率（実測 204/119）
const POP_COLOR_START = [0.8879, 0.8388, 0.9734, 1.0]; // 拍頭の色 sRGB(242,236,252)。v12 で純白から色相を持つ明色へ／v18 で H=264 度へ
const POP_DURATION = 0.100;                         // 収束までの秒数（実測どおり）

// v12: 2.6 → 3.68。スプライトのドット間隔をタイル（0.02875 ユニット）に揃えるため
// 1 ドット = 1 テクスチャ px にした結果（3.68/128 = 0.02875）。スプライト内の
// シャベル本体を 128 ドット中 76 ドットに縮めてあるので、画面上の大きさは v11 と同じ。
// v23 (B)2: 3.68 → 5.52（約 1.5 倍。3.68 の整数倍なので 1 ドット = 1.5 テクスチャ px の
// まま整数比を保つ）。本体の刃幅は 24 ドット × (5.52/128) ≈ 1.04 ユニットで、経路予告の帯幅
// PATH_WIDTH(= TILE = 1.84) より狭いままなのではみ出さない → 帯幅は無変更。
const SHOVEL_SCALE = 5.52;
const SHOVEL_SPAWN_Y = 26;     // 画面上端(18)より上・カリング境界(36)より内側
const SHOVEL_FALL_SPEED = 24;  // 落下速度（一定）。飛来時間はタイルの高さで変わる
// v13 (A4): 横断シャベルの速度を 26 → 15.6（6 割）へ下げた。
//   画面幅 35 ユニット（-1.5 → 33.5）を渡る時間は 1.346s → 2.244s に伸びるので、毎拍
//   （0.417s）発射だと前の拍の 2 本がまだ画面に残っている状態で次の 2 本が出る。
//   ユーザー了承済み（「次の拍の発射と重なってよい（別の行なので）」）。行が本当に別に
//   なるよう、shovelSweepPhase では直前の拍で使った 2 行を候補から外している。予告は無しのまま。
const SHOVEL_SIDE_SPEED = 15.6;  // 横断速度
const SHOVEL_LEFT_X = -1.5;    // カリング境界 x>=-2 の内側から出す
const SHOVEL_RIGHT_X = 33.5;

// shovel(): 等速直線で飛ぶシャベル1本（無重力・当たり判定なしの演出物）。
// v6: BulletType を stone3_shovel（JSaB 風ホットピンクの新スプライト・128x128・verts 空）へ差し替えた。
//     既存の stone_shovel（青いドット絵）は他ステージが使うので触っていない。
// 描画角は useVelocityAngle:false + initialAngle(rad) で明示指定する。
// stone3_shovel.png は「刃を下に向けた」向きで描かれている＝回転0で下向きなので、
// useVelocityAngle:true にすると落下時（速度角 -90°）に横倒しになってしまう。
// initialAngle は GetRotationAngle()（BulletData.cs:366）でしか使われず、軌道には影響しない。
const SHOVEL_ANGLE_DOWN = 0;                  // 下向き（スプライトそのままの向き）
const SHOVEL_ANGLE_RIGHT = Math.PI / 2;       // 右向き
const SHOVEL_ANGLE_LEFT = -Math.PI / 2;       // 左向き
function shovel(opts) {
  const { pos, vel, angle = SHOVEL_ANGLE_DOWN, life = 0, scale = SHOVEL_SCALE, kind = 'shovel' } = opts;
  return {
    parts: [{
      offsetSec: 0,
      kind,
      buffer: {
        bullets: [bulletDefaults({
          originPos: { x: pos[0], y: pos[1] },
          originVlc: { x: vel[0], y: vel[1] },
          typeName: 'stone3_shovel',
          scale: { x: scale, y: scale },
          color: { x: SPRITE_AS_IS[0], y: SPRITE_AS_IS[1], z: SPRITE_AS_IS[2], w: SPRITE_AS_IS[3] },
          life,
          unCounterable: true,
          useVelocityAngle: false,
          initialAngle: normalizeNegativeZero(angle),
        })],
        homing: false,
        isLaser: false,
      },
      spawner: NEUTRAL_SPAWNER(),
    }],
  };
}

// --- v27 (C): シャベルの多段モーション -------------------------------------------
//   区間ごとに 1 発ずつ弾を分ける v1 レーンの handoff（gravitySeq の非 v2 分岐と同じ
//   originPos/originVlc/gravity の閉形式）。gravitySeq をそのまま使わないのは、
//   シャベルは useVelocityAngle:false + initialAngle で向きを固定する必要があるため
//   （既定の useVelocityAngle:true だと落下中に横倒しになる）。
//   segs = [{ dur, ax, ay }]（ax/ay はワールドの等加速度成分。0 なら等速）
function shovelPath(pos0, vel0, segs, angle, kind) {
  let px = pos0[0], py = pos0[1], vx = vel0[0], vy = vel0[1], t = 0;
  const parts = [];
  segs.forEach(function (sg, i) {
    if (sg.vx !== undefined) vx = sg.vx;   // 区間の入り口で速度を差し替える（バウンド・発射）
    if (sg.vy !== undefined) vy = sg.vy;
    const mag = Math.sqrt(sg.ax * sg.ax + sg.ay * sg.ay);
    const dir = mag > 1e-9 ? Math.atan2(sg.ay, sg.ax) : 0;
    const last = i === segs.length - 1;
    parts.push({
      offsetSec: t,
      kind: kind,
      buffer: {
        bullets: [bulletDefaults({
          originPos: { x: normalizeNegativeZero(px), y: normalizeNegativeZero(py) },
          originVlc: { x: normalizeNegativeZero(vx), y: normalizeNegativeZero(vy) },
          gravity: { x: mag, y: normalizeNegativeZero(dir) },
          typeName: 'stone3_shovel',
          scale: { x: SHOVEL_SCALE, y: SHOVEL_SCALE },
          color: { x: SPRITE_AS_IS[0], y: SPRITE_AS_IS[1], z: SPRITE_AS_IS[2], w: SPRITE_AS_IS[3] },
          life: last ? sg.dur : sg.dur + METEOR_LIFE_MARGIN,
          unCounterable: true,
          useVelocityAngle: false,
          initialAngle: normalizeNegativeZero(angle),
        })],
        homing: false,
        isLaser: false,
      },
      spawner: NEUTRAL_SPAWNER(),
    });
    px += vx * sg.dur + 0.5 * sg.ax * sg.dur * sg.dur;
    py += vy * sg.dur + 0.5 * sg.ay * sg.dur * sg.dur;
    vx += sg.ax * sg.dur;
    vy += sg.ay * sg.dur;
    t += sg.dur;
  });
  return { parts: parts };
}

// --- v5: 予告ビルダー（3種。いずれも warnClip＝当たり判定なし）----------------

// (2) 爆破されるタイルの点滅（v7 で作り直し）。
//     クリップ発火 = 爆破の BLINK_LEAD（1拍）前。タイルと同じ大きさ・同じ位置の stone_flash を
//     重ね、タイルの面そのものが 明→暗→明 と脈打って見えるようにする。
//
//     アルファを直接指定する手段は無い（BulletIndirectURP.shader:283-291。color.w は
//     「着色するか否か」のフラグで、w>0 なら描画アルファは 1）。作者が動かせる透明度は
//       ・appearDuration>0 の予告窓 … α = 0.2〜0.5 の拍同期の明滅（値は選べない）
//       ・life の最後の FADE_OUT_SEC(0.1) 秒 … α が 1→0 へ直線減衰
//     の 2 つだけなので、後者を使って山を作る。1 コマは
//       「t0 に出て hold 秒後に消える」＝ 出た瞬間 α = hold/0.1 → hold 秒で 0 へ直線減衰
//     という三角波になる。これを BLINK_SUB(1/60) 秒ずつずらして重ね、合成 α（重ね塗りなので
//     1 - Π(1-α_i)）が sin² の山を通るように各コマの hold を前から順に逆算する。
function solveBlinkPulse() {
  const holds = [];
  function alphaAt(hold, start, t) {
    if (t < start) return 0;
    return Math.max(0, Math.min(1, (hold - (t - start)) / FADE_OUT_SEC));
  }
  for (let j = 0; j < BLINK_STEPS; j++) {
    // 山の目標形（sin² の 1 山。両端は 0 に近く、中央で BLINK_PEAK）
    const target = BLINK_PEAK * Math.pow(Math.sin((Math.PI * (j + 1)) / (BLINK_STEPS + 1)), 2);
    const now = j * BLINK_SUB;
    let rest = 1;
    for (let m = 0; m < j; m++) rest *= 1 - alphaAt(holds[m], m * BLINK_SUB, now);
    // 既に残っているぶん rest の上に target を作るのに必要な自分のアルファ
    const need = rest > 1e-9 ? 1 - (1 - target) / rest : 0;
    holds.push(Math.max(0, Math.min(1, need)) * FADE_OUT_SEC);
  }
  return holds;
}
const BLINK_HOLDS = solveBlinkPulse();
// 1 山が完全に消えるまでの長さ（＝最後まで残るコマの終了時刻）
const BLINK_PULSE_DUR = BLINK_HOLDS.reduce(function (acc, hold, i) {
  return hold > 0 ? Math.max(acc, i * BLINK_SUB + hold) : acc;
}, 0);
// 山の開始時刻。間隔は BLINK_ACCEL 倍ずつ詰まり、最後の山が爆破の瞬間ちょうどに消え終わる。
const BLINK_PULSE_STARTS = (function () {
  const span = BLINK_LEAD - BLINK_PULSE_DUR;
  const weights = [];
  for (let i = 0; i < BLINK_PULSES - 1; i++) weights.push(Math.pow(BLINK_ACCEL, i));
  const total = weights.reduce(function (a, b) { return a + b; }, 0);
  const out = [0];
  weights.forEach(function (w) { out.push(out[out.length - 1] + (span * w) / total); });
  return out;
})();

function blinkWarn(cells, kind) {
  const items = [];
  cells.forEach(function (cell) {
    const c = cellCenter(cell[0], cell[1]);
    BLINK_PULSE_STARTS.forEach(function (pulse) {
      BLINK_HOLDS.forEach(function (hold, i) {
        if (hold <= 0) return;
        const t0 = pulse + i * BLINK_SUB;
        items.push({
          type: BLINK_TYPE,
          pos: c,
          scale: [TILE, TILE],      // タイルと同じ大きさ（拡大しない＝枠にならない）
          color: STONE_BRIGHT,
          appearTime: t0,           // ここまで非表示（appearDuration=0）
          appearDuration: 0,
          life: t0 + hold,
        });
      });
    });
  });
  return warnClip(items, kind);
}

// --- v9: タイル実体化ポップ（1 タイル 1 発。ランタイムの出現アニメを使う）------------
// 拍頭に純白・POP_SCALE_START 倍で出し、POP_DURATION 秒で実体タイルと同じ大きさ・同じ色へ
// 線形に収束させる。収束後は実体タイルと完全に一致するので、life 末尾の減衰は見えない。
// 描画は BLINK_TYPE（stone_flash・renderPriority 4）＝ stone_block(1) より手前。
function tilePop(cells, kind) {
  const items = [];
  cells.forEach(function (cell) {
    const c = cellCenter(cell[0], cell[1]);
    const big = TILE * POP_SCALE_START;
    items.push({
      type: BLINK_TYPE,
      pos: c,                       // 中心はタイルと同じ（拡大・縮小は中心対称）
      scale: [big, big],
      color: POP_COLOR_START,
      scaleEnd: [TILE, TILE],       // 収束後は実体タイルと同寸
      colorEnd: STONE_TILE_END,     // 収束後は無着色（w=0）＝実体タイルのテクスチャそのまま
      animDuration: POP_DURATION,
      appearTime: 0,                // 拍頭ちょうどに出る
      appearDuration: 0,
      // 収束後の 0.1 秒は実体タイルと完全に重なったまま減衰するので、消え際は見えない
      life: POP_DURATION + FADE_OUT_SEC,
    });
  });
  return warnClip(items, kind);
}

// --- v24: 白いフラッシュ 1 発（正方形が大きく光って縮みながら消える）-------------
//   集合爆破のブルーム（マーカー 48）と、隕石の出現／着弾／タイル破壊で共用する。
//   BLINK_TYPE（stone3_flash）は renderPriority 4 ＝ タイルや隕石本体より手前。
//   verts 空なので当たり判定は無い。delay を入れるとその秒数だけ待ってから光る。
function flashPop(pos, delay, s0, s1, dur, kind) {
  return warnClip([{
    type: POP_TYPE,      // v26 (B): 角を落としたマスクの弾種
    pos: [pos[0], pos[1]],
    scale: [s0, s0],
    color: POP_COLOR_START,
    scaleEnd: [s1, s1],
    colorEnd: STONE_MID,
    animDuration: dur,
    appearTime: delay,
    appearDuration: 0,
    life: delay + dur + FADE_OUT_SEC,
  }], kind);
}

// (3) 落下シャベルの経路予告。通る列に、刃の幅ぶん（＝タイル1枚幅）の縦帯を出す。
//     v7: 帯の下端を対象タイルの中心から「タイルの下端」まで下げ、シャベルが掃く範囲を
//     まるごと覆うようにした（対象タイル自体の位置は blinkWarn の点滅でも示している）。
//     クリップ発火 = シャベル発射の1拍前、life = dur でシャベル到達と同時に消える。
function dropPathWarn(center, dur, kind) {
  const top = ROWS * CELL;             // 画面上端 y=18
  const bottom = center[1] - TILE / 2; // 対象タイルの下端
  const h = top - bottom;
  return warnClip(
    [{
      pos: [center[0], bottom + h / 2],
      scale: [PATH_WIDTH, h],
      color: STONE_PATH,
      appearTime: dur,
      appearDuration: dur,
      life: dur,
    }],
    kind
  );
}

// ── v15 の鎖（下から上へ這う蛇）─────────────────────────────────────────────
//
// 参考: Just Shapes & Beats "Tokyo Skies" 0:13.33〜0:14.87（曲 33.33〜34.87s に対応。
//   動画時刻 + 20.000s = stone3.mp3 の時刻。計測ログは Captures/ref_tokyoskies_014_frames.md）。
//   v14 は「画面幅いっぱいのサイン波前線を上から下へ 2 本」だったが、これは誤読だった。
//   実際は **1 タイル幅の鎖が 1 本、画面の下端から上端へ這い上がる** 攻撃で、
//   鎖の各タイルは自分の段（高さ）を変えずに **横方向へサインで往復** している。
//
//   実測値（1920x1080・タイル 75px・段の間隔 82.5px）:
//     ・先頭は 0.100s に 1 段ずつ上へ進む（10 段/秒）
//     ・横揺れは 中心 x=510 / 振幅 75px（= 0.83 セル）/ 周期 0.400s
//     ・隣の段との位相差は 60 度（＝波長 6 段）。模様自体は上から下へ流れる
//     ・同時に見えているのは 7〜8 段ぶん（全 11 段中）。先頭が伸び、末尾が消える
//     ・新しく生えたタイルはその 1〜2 コマだけ淡く光る（＝出現フラッシュ。白い頭ではない）
//     ・鎖は壁タイルを壊さず、最上段の 1 つ下で消える
//
//   本ステージへの移し替え（v17 で改訂）: 画面は 16 列 x 9 行（32x18 ユニット）。
//   v16 までは段の間隔をグリッドの 1 行（CELL = 2 ユニット）にしていたので、
//   1.15 ユニットの鎖のあいだに 0.85 ユニットの隙間が空き、参考の
//   「段どうしが隙間なく接した 1 本の蛇」に見えていなかった。
//   v17 では **段の間隔 = 鎖の 1 辺（SNAKE_TILE = 1.15 ユニット）** にして接するようにし、
//   そのぶん段数を 9 → 16 に増やして画面の高さ（18 ユニット）を覆う。
//   速度は参考の比率に合わせる: 参考は 0.1s/段 × 11 段 ≒ 1.1s で画面を縦断（末尾を
//   含めて約 1.5s）なので、こちらも **16 段 × 0.09375s = 1.500s** で縦断させる。
//   横揺れは鎖のサイズ基準に読み替え（振幅 = 0.83 段 = 0.83 × 1.15）、周期と
//   1 段あたりの位相差（60 度）は参考のまま。全長も参考の 7〜8 枚に合わせる。
//   1 本では 16 列の画面に対して薄いので **本数だけ 3 本**（v15 から不変）。
const SNAKE_ROW_STEP = 0.09375;          // 1 段ぶん進む時間（16 段で 1.500s = 画面高を縦断）
const SNAKE_LEN = 7;                     // 同時に見えるタイル数（参考の全長 7〜8 枚）
const SNAKE_PERIOD = beats(1);           // 0.41667s: 横揺れの周期（実測 0.400s ≒ 1 拍）
const SNAKE_ROW_PHASE = Math.PI / 3;     // 1 段あたりの位相差 60 度（＝波長 6 段）
const SNAKE_SEGMENTS = 16;               // moveTo の折れ線でサインを近似する分割数（1 周期あたり約 10.7 点）
// 3 本の中心列と位相。位相を 120 度ずつずらすと、3 本が同時に同じ向きへ寄らない。
// v29 (4): 指示 33.871 / 40.664 / 48.723「鎖攻撃は 2 個にして」。1〜3 回目の鎖を
//   3 本から 2 本へ減らす（4 回目 54.5833s は指示に無いので 3 本のまま）。
//   16 列を 3 等分する位置（col 4 と 11）を基準に、回ごとに 2 列ずつずらして
//   「同じ場所を 3 回掃かない」規則を保つ。位相は 2 本が同時に同じ向きへ寄らないよう 180 度差。
const SNAKE_LANES = [
  { col: 4, phase: 0 },
  { col: 11, phase: Math.PI },
];
const SNAKE_LANES2 = [
  { col: 6, phase: Math.PI / 3 },
  { col: 13, phase: (4 * Math.PI) / 3 },
];
const SNAKE_LANES3 = [
  { col: 2, phase: (2 * Math.PI) / 3 },
  { col: 9, phase: (5 * Math.PI) / 3 },
];
// v27 (8): 鎖 4 回目（54.5833s）。1〜3 回目のどれとも中心列が重ならない 3 / 8 / 13。
const SNAKE_LANES4 = [
  { col: 3, phase: Math.PI },
  { col: 8, phase: (5 * Math.PI) / 3 },
  { col: 13, phase: Math.PI / 3 },
];
// v16: 鎖を専用スプライト stone3_chain（タイルより小さい正方形・一段明るい面）にした。
// v17 でも見た目（スプライト・サイズ 1.15 ユニット）は v16 のまま。
const SNAKE_TILE_SCALE = 0.625;
const SNAKE_TILE = Math.round(TILE * SNAKE_TILE_SCALE * 1e6) / 1e6;   // 1.15 ユニット（スプライトは 40 ドット）
// v17: 段の間隔 = 鎖の 1 辺。段どうしが隙間なく接する。
const SNAKE_STEP_Y = SNAKE_TILE;                           // 1.15 ユニット
// 画面（ROWS * CELL = 18 ユニット）は 1.15 で割り切れない（15.65 段）ので、16 段の梯子を
// 上下対称に置く。中心は 0.375 → 17.625、上下の端が 0.2 ユニットだけ画面外へはみ出す
// （鎖が画面外から生えて画面外へ抜ける形になる）。
const SNAKE_STEPS = 16;
const SNAKE_Y0 = (ROWS * CELL - (SNAKE_STEPS - 1) * SNAKE_STEP_Y) / 2;   // 0.375
const SNAKE_AMP = 0.83 * SNAKE_TILE;                       // 0.9545: 横揺れの振幅（参考の 0.83 段ぶん）
// 鎖 1 本が掃く幅の半分（振幅 + 鎖の半分）。予告の帯の幅に使う。
const SNAKE_HALF_W = SNAKE_AMP + SNAKE_TILE / 2;           // 1.53 ユニット
const SNAKE_BREAK_R = CELL * 0.9;                          // 残留タイルを砕く距離（x 方向・中心間）
const SNAKE_BREAK_DY = (CELL + SNAKE_TILE) / 2;            // 同（y 方向）。段がグリッド行と揃わなくなったので明示
const SNAKE_BURSTS = 8;                                    // 砕けたタイルのうち放射弾を出す枚数の上限
const SNAKE_POP_DURATION = 0.05;                           // 出現フラッシュ（実測 1〜2 コマ）
const SNAKE_POP_SCALE = 1.15;

// 段 k の中心 y。
function snakeY(k) {
  return SNAKE_Y0 + k * SNAKE_STEP_Y;
}

// 段 k・鎖 lane のタイルの、時刻 t における x 座標。
// t は曲の絶対時刻。全部の段・全部の本数が同じ時計を見るので、位相が揃う。
function snakeX(t, k, lane) {
  return (
    CELL * (lane.col + 0.5) +
    SNAKE_AMP * Math.sin((2 * Math.PI * t) / SNAKE_PERIOD + k * SNAKE_ROW_PHASE + lane.phase)
  );
}

// 段 k のタイルが画面に居る時間帯 [生える, 消える]（t0 = 攻撃の発火時刻）。
// 先頭は 1 段につき SNAKE_ROW_STEP で上がり、SNAKE_LEN 段ぶん後ろで末尾が消える。
function snakeRowWindow(t0, k) {
  const a = t0 + k * SNAKE_ROW_STEP;
  return [a, a + SNAKE_LEN * SNAKE_ROW_STEP];
}

// 鎖のタイル 1 枚。段（y）は動かさず、moveTo の折れ線だけで横に往復させる。
// v2 レーン（{v2:true}）なので 1 枚 = 弾 1 発。
function snakeTile(t0, k, lane) {
  const y = snakeY(k);
  const win = snakeRowWindow(t0, k);
  const dur = win[1] - win[0];
  const segs = [];
  for (let i = 1; i <= SNAKE_SEGMENTS; i++) {
    const rel = (dur * i) / SNAKE_SEGMENTS;
    segs.push({ until: rel, moveTo: [snakeX(win[0] + rel, k, lane), y] });
  }
  return gravitySeq(
    {
      pos: [snakeX(win[0], k, lane), y],
      vel: [0, 0],
      type: 'stone3_chain',
      scale: [SNAKE_TILE, SNAKE_TILE],
      color: SPRITE_AS_IS,
      unCounterable: true,
    },
    segs,
    'snake',
    { v2: true }
  );
}

// 出現フラッシュ。参考では新しいタイルが生えたコマだけ淡く光り、次のコマには通常色に戻る。
function snakePop(t0, k, lane) {
  const y = snakeY(k);
  const a = snakeRowWindow(t0, k)[0];
  const big = SNAKE_TILE * SNAKE_POP_SCALE;
  return warnClip(
    [{
      type: BLINK_TYPE,
      pos: [snakeX(a, k, lane), y],
      scale: [big, big],
      color: POP_COLOR_START,
      scaleEnd: [SNAKE_TILE, SNAKE_TILE],
      colorEnd: STONE_TILE_END,
      animDuration: SNAKE_POP_DURATION,
      appearTime: 0,
      appearDuration: 0,
      life: SNAKE_POP_DURATION + FADE_OUT_SEC,
    }],
    'snakepop'
  );
}

// 予告。参考では「鎖が掃く幅ぶんの縦帯が画面の上から下まで通しで出て、
// 約 1.8 秒かけて連続に濃くなり、攻撃の瞬間に閃光になって消える」。
// こちらは拍に乗せる都合で、32.083s（薄い）→ 32.917s（濃い）の 2 段階で濃くする。
function snakeWarn(lanes, color, dur, kind) {
  const items = lanes.map(function (lane) {
    return {
      pos: [CELL * (lane.col + 0.5), (ROWS * CELL) / 2],
      scale: [SNAKE_HALF_W * 2, ROWS * CELL],
      color: color,
      appearTime: dur,
      appearDuration: dur,   // 予告点滅の窓に入れっぱなし（実体化しない）
      life: dur,
    };
  });
  return warnClip(items, kind);
}

// セル(col,row) に残っているタイルを鎖が砕く時刻。どの鎖も通らなければ null。
// v17: 段がグリッド行と揃わなくなったので、そのセルと y が重なる段だけを見る。
// 各段が画面に居る間を 1/120 秒刻みで走査し、x が SNAKE_BREAK_R 以内に来た最初の時刻。
function snakeBreakTime(col, row, t0, lanes) {
  const center = cellCenter(col, row);
  const cx = center[0];
  const cy = center[1];
  const STEP = 1 / 120;
  let best = null;
  for (let k = 0; k < SNAKE_STEPS; k++) {
    if (Math.abs(snakeY(k) - cy) > SNAKE_BREAK_DY) continue;
    const win = snakeRowWindow(t0, k);
    lanes.forEach(function (lane) {
      for (let t = win[0]; t <= win[1]; t += STEP) {
        if (Math.abs(snakeX(t, k, lane) - cx) <= SNAKE_BREAK_R) {
          if (best === null || t < best) best = t;
          return;
        }
      }
    });
  }
  return best;
}


// ── v21: 右列タイルの左流し（マーカー 18〜21 / 29 / 31）────────────────────────
//   右端の列（列 15）に 4 枚のタイルを予告 → 実体化し、1 拍のあいだ静止させてから
//   左向きの一定加速度で流す。画面外（カリング境界 x < -2）で自然に消える。
//   v2 レーンの gravitySeq（区間 2 つ: moveTo で静止 → accel で加速）なので 1 枚 = 弾 1 発。
const SLIDE_COL = COLS - 1;                 // 列 15（右端）
const SLIDE_HOLD = beats(1);                // 実体化から動き出すまで（1 拍）
const SLIDE_ACCEL = 34;                     // 左向き加速度（ユニット/s^2）
const SLIDE_END_X = -3.2;                   // カリング境界(-2)の外まで飛ばす
const SLIDE_WARN_LEAD = beats(0.75);        // 出現予告のリード
const SLIDE_TILES_PER_WAVE = 4;             // 1 回に出す枚数

// ── v21: 隕石（マーカー 22〜28 / 40〜42）──────────────────────────────────────
//
//   参考: Bossfight "Commando Steve"（https://www.youtube.com/watch?v=wZ8qdagsnbo）の
//   1:35 前後。実測フレームは Captures/ref_commandosteve_135_a.png（動画 95.00s）と
//   ref_commandosteve_135_b.png（同 95.55s・1280x714）。読み取った特徴:
//     ・画面右端で白く光る頭が生まれ、そこから大きなトゲ玉が斜め左下へ飛ぶ
//     ・玉の直径は約 92px ＝ 画面高 714px の 12.9%（この画面なら 18 × 0.129 = 2.3 ユニット）
//     ・玉の後ろに丸い点の尾が 10〜14 個。頭に近いほど大きく白く、遠いほど小さく淡い桃色
//     ・尾の全長は約 400px ＝ 画面高の 0.56 倍。玉は同時に 5〜6 個が別々の高さを飛ぶ
//   本ステージへの移し替え: 見た目はタイル（stone3_tile）を拡大したもの、軌道は指示書
//   どおり「右から左へ直線」（参考の斜めは採らない）。大きさは参考の 2.3 ユニットより
//   やや大きい 3.2 ユニット（タイル 1.84 の 1.74 倍）で、タイルとの区別を付けている。
//   尾は当たり判定のない stone3_flash を通過点に置き、縮みながら消えるようにした。
const METEOR_SCALE = 3.2;                   // 隕石の一辺（タイル 1.84 の 1.74 倍）
const METEOR_START_X = 34.5;                // 画面右外（カリング境界 36 の内側）
const METEOR_END_X = -4.0;                  // 画面左外（同 -2 の外＝ここへ着く前に消える）
// v27 (9): 手打ち 70.558「隕石速すぎる。あと、軌跡もまだ違和感ある。ランダムに飛ばす
//   感じが欲しい」→ 飛行時間を 1.05 → 1.60s（速度 65.6%・指示の目安 60〜70%）にし、
//   発射角と自転にごく小さい乱数を入れる（種固定・makeRng(20260904) の専用ストリーム
//   なので、他の弾の配置には影響しない）。
const METEOR_FLIGHT = 1.60;                 // 端から端まで 38.5 ユニット ≒ 24.1 ユニット/s
const METEOR_JITTER_ANGLE = 0.05;           // 発射角の乱数（rad・±）。全行程で y が ±1.93 ユニット振れる
const METEOR_JITTER_SPIN = 0.55;            // 自転速度の乱数（±の割合）
const meteorRng = makeRng(20260904);        // 隕石専用の乱数（本編の rng とは別ストリーム）
// 1 発ぶんの乱数と、そこから決まる直線の運動。行の中心 y は飛行のちょうど中間で通る。
function meteorJit() {
  const ang = (meteorRng() * 2 - 1) * METEOR_JITTER_ANGLE;
  const spin = METEOR_SPIN * (1 + (meteorRng() * 2 - 1) * METEOR_JITTER_SPIN)
    * (meteorRng() < 0.5 ? -1 : 1);
  return { ang: ang, spin: spin };
}
function meteorMotion(y, jit) {
  const vx = (METEOR_END_X - METEOR_START_X) / METEOR_FLIGHT;   // 負（左向き）
  const vy = -vx * Math.tan(jit.ang);
  return { x0: METEOR_START_X, y0: y - (vy * METEOR_FLIGHT) / 2, vx: vx, vy: vy };
}
// ── v24 (B): 尾を「点線」から「連続した尾」へ ────────────────────────────
//   参考 https://www.youtube.com/watch?v=wZ8qdagsnbo 1:33〜1:40 を 1/30 秒刻みで実測した
//   （640x360 換算・20px = 1 ユニット。97.50s の 1 コマを軸方向に走査した値）:
//     ・本体は直径 40px（2.0 ユニット）のトゲ玉。飛行中の伸縮（脈動）は**無い**＝自転だけ
//     ・尾は本体の真後ろに続く円の列。本体に接する側が直径 38px（本体の 0.95 倍）で純白
//       (255,252,255)、そこから 32 → 22 → 14 → 10px と細り、色も白 → 淡桃 (254,216,255)
//       → 中桃 (255,101,183) へ変わって消える
//     ・尾の全長は 74px ＝ 本体 1.85 個ぶん。円どうしが大きく重なって切れ目が無い
//     ・尾は本体より**奥**に描かれている（本体が白く塗り潰されない）
//   移し替え: 本体 3.2 ユニットに対して 尾の頭 3.04 / 末端 0.80、見えている長さ 7.3 ユニット
//   （本体 2.3 個ぶん）。v23 までは全行程に 16 点をばらまいて 1 点ずつ 0.34 秒かけて縮めて
//   いたので、点の間隔 2.4 ユニット > 点の直径 1.55 ユニットとなり「点線」に見えていた。
//   v24 は 0.03 秒ごと＝ 1.1 ユニット間隔に置き、1 点の寿命を 0.20 秒に縮める。
//   弾のタイプも stone3_flash（renderPriority 4・本体より手前）から
//   warn_box（同 0・verts 空＝当たり判定なし）へ変えて、本体の奥へ回した。
// v25: v24 の尾は 0.025s 間隔・3.04→0.80 で「太く明るい白いくさび状」に見えてしまった
// （Captures/stone_v24_f2_meteor_trail_t70.30.png）。参考
// https://www.youtube.com/watch?v=wZ8qdagsnbo 1:35 は本体の後ろに丸い点が 10〜14 個、
// 頭に近いほど大きく白く、遠いほど小さく淡い「点列」で、本体を塗り潰さない薄さだった。
// また BulletIndirectURP.shader の通常弾パスは color.a を「透明度」ではなく
// 「着色するかどうか」の 0/1 スイッチとして使う（a>0 ならマスク形状を不透明フルカラーで
// 塗る）ため、v24 のように colorEnd の alpha だけ下げても薄くはならない。淡さは
// **RGB の明度そのもの**で作る。
// v29b（指示 101.985「尾のエフェクトも全然違う」）: 本家 Commando Steve の実測
//   （Captures/ref_steve_096.14.png ほか。1105px 幅で観察）
//     ・頭のすぐ後ろは本体色より明るい大きな丸が 5〜6 個重なって「連続した帯」になり、
//       そこから後ろは本体色の小さな点が長く（本体径の約 10 倍）続いて先端ほど小さく暗い
//     ・尾は本体と同じ色相（ピンク）。白っぽいのは頭の直後だけ
//     ・本家の隕石は画面を横切って外へ抜け、画面内では破裂しない
//   v25 の尾は「淡いグレーの点列・寿命 0.16s（本体径 1.2 倍の長さ）」で、色相も長さも
//   本家と違っていた。v29b では
//     ・色を本体（タイル）の色相に揃え、頭側は本体より一段明るい紫、末端は背景に沈む紫
//     ・点の間隔 0.03s（直径 1.7 に対し 0.5〜1.1 ユニット）で重ね、途切れない帯にする
//     ・寿命 0.42s で長さを 2.6 倍（本体径の 3〜5 倍）にし、縮みで先端ほど細くする
//     ・各点を進行方向へ回して置く（斜めの経路でも帯の縁がぎざぎざにならない）
const METEOR_TRAIL_STEP = 0.03;             // 尾の点を置く時間間隔（36.7 ユニット/s で 1.47 ユニット）
                                             // v24 の 0.025s は間隔 0.92 ユニット < 点の直径で
                                             // 「連続した帯」に見えていた。0.04s へ広げて点どうしの
                                             // 隙間を作り、点列に見せる。
const METEOR_TRAIL_LIFE = 0.42;             // 1 点の寿命（縮むアニメの長さ）は据え置き
const METEOR_TRAIL_S0 = 1.7;                // 本体に接する点の一辺（本体 3.2 の 0.47 倍。v24 は 0.95 倍で本体並みに太かった）
const METEOR_TRAIL_S1 = 0.2;                // 末端の一辺（本体の 0.09 倍）
const METEOR_TRAIL_TYPE = 'warn_box';       // 本体（stone3_tile・renderPriority 1）より奥
// v25: 開始色は本体（無着色のテクスチャそのまま）より淡いグレー、終端はさらに暗く
// 背景へ溶け込む色。v24 は開始 POP_COLOR_START（sRGB 242,236,252 の明るい白）→
// 終端 STONE_MID（166,150,190）で、どちらも面が不透明に塗り潰されるため「太く明るい」
// 印象が強すぎた。明度を大きく落とす。
const METEOR_TRAIL_COLOR_START = [0.21, 0.16, 0.31, 1.0];  // sRGB 約(180,175,192) の淡いグレー
const METEOR_TRAIL_COLOR_END = STONE_PATH;                  // (56,46,72) 相当・ほぼ背景に沈む暗さ
// 出現フラッシュ / 着弾フラッシュ / 着地の潰れ（v24 (B) の追加演出。いずれも当たり判定なし）。
//   参考の隕石は画面外から入ってくるので出現の瞬間は写っていない。ここはユーザー指示に従い
//   「画面端で白く弾けてから本体が飛び出す」形を、タイルのポップ（tilePop）と同じ
//   scaleEnd/colorEnd の縮小アニメで作る。
const METEOR_FLASH_S0 = METEOR_SCALE * 1.9;   // 出現フラッシュの初期辺
const METEOR_FLASH_S1 = METEOR_SCALE * 0.5;   // 同・収束辺
const METEOR_FLASH_DUR = 0.12;                // 同・縮む秒数
const METEOR_HIT_S0 = METEOR_SCALE * 2.4;     // 着弾フラッシュの初期辺（出現より大きい）
const METEOR_HIT_S1 = METEOR_SCALE * 0.7;
const METEOR_HIT_DUR = 0.09;                  // ほぼ 1 コマで弾けて消える
const METEOR_SQUASH_DUR = 0.10;               // 落下隕石が着地でつぶれる秒数
const METEOR_SQUASH_X = 1.3;                  // つぶれた時の横倍率
const METEOR_SQUASH_Y = 0.6;                  // 同・縦倍率
const METEOR_BREAK_S0 = TILE * 1.9;           // 通過中に残留タイルを砕いた時の小フラッシュ
const METEOR_BREAK_S1 = TILE * 0.5;
const METEOR_BREAK_DUR = 0.10;
const METEOR_WARN_LEAD = beats(1);          // 通る行の予告のリード
const METEOR_ROWS = [1, 2, 3, 4, 5, 6, 7];  // 隕石が通れる行（0/8 は玉が画面からはみ出す）
const METEOR_BREAK_DY = (CELL + METEOR_SCALE) / 2;  // 残留タイルを砕く y 方向の距離
// 落下隕石（マーカー 40〜42）。横断シャベルと同じく「着弾時刻」を先に決め、飛来時間ぶん
// 手前で発射する。加速度 150 なら 25 ユニット落ちるのに 0.577s。
const METEOR_DROP_SPAWN_Y = 26;             // 画面上端(18)より上・カリング境界(36)の内側
// v27 (14): 手打ち 100.281「ここの隕石速すぎるのと、予告が欲しい」
//   150 → 64（飛来 0.5774 → 0.8839s ＝ 速度 65.3%）。出現位置の予告は下の区間で足す。
const METEOR_DROP_ACCEL = 64;               // 落下加速度（ユニット/s^2）
const METEOR_DROP_Y = CELL * 0.5;           // 着弾点＝最下段の中心（y = 1）

// ── v27 (15)(19): 円形の爆破エフェクト ─────────────────────────────────────
//   手打ち 103.157「爆破時のエフェクトが気になる。丸の方がいいかも」/
//   手打ち 109.730「壁への隕石の爆破をリッチに（-zhZYYl8USk 1:09 参照）」。
//   参考動画 1:10（右壁への着弾）をコマ送りで実測した結果:
//     着弾 +0.00s … 壁の点に半径 30px ほどの同心円の弧が密に詰まった塊
//     着弾 +0.08s … 半径 65px。濃淡が交互になった弧が 5 本ぶん見える（壁で切れた半円）
//     着弾 +0.20s … 半径 120px。先頭の弧が太く、その内側に小さい白い破片が散る
//     着弾 +0.37s … 先頭の弧が個々の菱形に分かれ、それぞれの後ろに白い破片の尾が残る
//   こちらのスプライトは正方形しか無いので、「小さいポップを円周上に等間隔で並べた
//   リングを、半径を変えて時間差で出す」ことで円形の衝撃波にする（＝正方形 1 枚の
//   大きなフラッシュをやめる）。flashPop のスプライト・マスクは v26 のまま。
const ROUND_BLAST_DUR = 0.10;
// [半径, 個数, 開始辺, 終了辺, 遅れ]
const METEOR_RING_SPEC = [
  [0, 1, METEOR_SCALE * 1.45, METEOR_SCALE * 0.45, 0.000],
  [METEOR_SCALE * 0.95, 10, METEOR_SCALE * 0.72, METEOR_SCALE * 0.20, 0.030],
  [METEOR_SCALE * 1.85, 16, METEOR_SCALE * 0.55, METEOR_SCALE * 0.14, 0.075],
];
const WALL_RING_SPEC = [
  [0, 1, METEOR_SCALE * 1.70, METEOR_SCALE * 0.50, 0.000],
  [METEOR_SCALE * 0.90, 12, METEOR_SCALE * 0.80, METEOR_SCALE * 0.22, 0.028],
  [METEOR_SCALE * 1.75, 18, METEOR_SCALE * 0.62, METEOR_SCALE * 0.16, 0.070],
  [METEOR_SCALE * 2.70, 24, METEOR_SCALE * 0.46, METEOR_SCALE * 0.12, 0.115],
];
// v28: 最後の大爆破のリング（WALL_RING_SPEC をさらに 1 枚増やして半径を広げた一番派手なもの）。
// v29 (10): 指示 141.507「最後のエフェクト大きすぎて、隕石が見えない」。
//   中心の閃光が隕石（METEOR_SCALE）の 2.10 倍あって本体を完全に覆っていたので、
//   中心を 1.05 倍（＝隕石と同じ大きさ）まで落とし、外側のリングも半径 0.77 倍・
//   粒の大きさ 0.7 倍に縮めた。リングの枚数と数は変えていない。
const FINAL_RING_SPEC = [
  [0, 1, METEOR_SCALE * 1.05, METEOR_SCALE * 0.42, 0.000],
  [METEOR_SCALE * 0.70, 12, METEOR_SCALE * 0.63, METEOR_SCALE * 0.17, 0.025],
  [METEOR_SCALE * 1.39, 20, METEOR_SCALE * 0.50, METEOR_SCALE * 0.13, 0.062],
  [METEOR_SCALE * 2.20, 28, METEOR_SCALE * 0.39, METEOR_SCALE * 0.10, 0.105],
  [METEOR_SCALE * 3.12, 36, METEOR_SCALE * 0.29, METEOR_SCALE * 0.07, 0.155],
];
function roundBlastFx(pos, spec, kind) {
  const items = [];
  spec.forEach(function (r, ri) {
    const radius = r[0], n = r[1], s0 = r[2], s1 = r[3], delay = r[4];
    for (let i = 0; i < n; i++) {
      const a = (i * 2 * Math.PI) / n + ri * 0.19;   // リングごとに少し回して市松に見せる
      items.push({
        type: POP_TYPE,
        pos: [normalizeNegativeZero(pos[0] + Math.cos(a) * radius),
              normalizeNegativeZero(pos[1] + Math.sin(a) * radius)],
        scale: [s0, s0],
        color: POP_COLOR_START,
        scaleEnd: [s1, s1],
        colorEnd: STONE_MID,
        animDuration: ROUND_BLAST_DUR,
        appearTime: delay,
        appearDuration: 0,
        life: delay + ROUND_BLAST_DUR + FADE_OUT_SEC,
      });
    }
  });
  return warnClip(items, kind);
}
// 参考の「先頭の弧が個々の菱形に分かれ、後ろに白い破片の尾を引く」ぶん。
// POP_TYPE は verts 空＝当たり判定なしなので、見た目だけの破片として使える。
function debrisRing(pos, count, speed, life, size, spin, angleOffset) {
  return spinBurst({
    pos: pos,
    count: count,
    speed: speed,
    type: POP_TYPE,
    life: life,
    scale: [size, size],
    color: SPRITE_AS_IS,
    angleOffset: angleOffset,
    spin: spin,
    kind: 'debris',
    unCounterable: true,
  });
}

// v29b（指示 101.985「破裂のエフェクトが破裂弾と見間違う」）: 隕石の破裂を
//   「輪郭だけの閃光リング＋本体の欠片」に作り直す。
//   従来（v27 (15)(19)）は小さい正方形（stone3_pop）を円周に並べた同心リング 3〜4 枚と
//   小さい四角の破片（debrisRing）で、放射する破裂弾（stone3_bullet・一辺 0.3 の四角）と
//   形が同じだった。v29b では
//     ・中心の閃光 1 枚（従来の中心ポップと同じ）
//     ・塗り潰しの無い円環（stone3_ring）1 枚を、拡大しながら明 → 暗へ薄れさせる
//     ・本体の欠片 6 枚（本体の絵そのもの・一辺 1.34 ＝ 弾の 4.5 倍）を、回転しながら
//       減速して止まり、縮んで消える。小さい四角の破片は使わない
//   放射弾（burst）の数・軌道は触らない。mag は壁隕石だけ 1.2（従来の WALL_RING_SPEC が
//   落下用より一回り大きかったのを引き継ぐ）。最後の大爆破（FINAL_RING_SPEC）は v29 (10) で
//   調整済みなので触っていない。
const METEOR_RING_TYPE = 'stone3_ring';               // 円環（verts 空・renderPriority 4）
const METEOR_BURST_FLASH_S0 = METEOR_SCALE * 1.45;    // 中心の閃光（従来の中心ポップと同じ値）
const METEOR_BURST_FLASH_S1 = METEOR_SCALE * 0.45;
const METEOR_BURST_FLASH_DUR = 0.10;
const METEOR_BURST_RING_S0 = METEOR_SCALE * 0.8;      // 円環の初期径（本体より少し小さい）
const METEOR_BURST_RING_S1 = METEOR_SCALE * 3.4;      // 同・終端径（従来の外側リング半径 1.85 の直径相当）
const METEOR_BURST_RING_DUR = 0.22;                   // 拡大しきるまで。その後 FADE_OUT_SEC で消える
const METEOR_BURST_CHUNK_N = 6;
const METEOR_BURST_CHUNK_S0 = METEOR_SCALE * 0.42;    // 欠片の一辺 1.34（本体の 0.42 倍）
const METEOR_BURST_CHUNK_S1 = METEOR_SCALE * 0.18;    // 消える直前の一辺
const METEOR_BURST_CHUNK_LIFE = 0.55;                 // 減速して止まるまで（＝寿命）
const METEOR_BURST_CHUNK_SPEEDS = [8.0, 5.5];         // 交互に速い / 遅い（ユニット/s）
const METEOR_BURST_CHUNK_SPIN = 5.0;                  // 自転（rad/s・交互に逆回転）
function meteorBurstFx(pos, mag, kind) {
  const flash = warnClip([{
    type: POP_TYPE,
    pos: [pos[0], pos[1]],
    scale: [METEOR_BURST_FLASH_S0 * mag, METEOR_BURST_FLASH_S0 * mag],
    color: POP_COLOR_START,
    scaleEnd: [METEOR_BURST_FLASH_S1, METEOR_BURST_FLASH_S1],
    colorEnd: STONE_MID,
    animDuration: METEOR_BURST_FLASH_DUR,
    appearTime: 0,
    appearDuration: 0,
    life: METEOR_BURST_FLASH_DUR + FADE_OUT_SEC,
  }], kind);
  const ring = warnClip([{
    type: METEOR_RING_TYPE,
    pos: [pos[0], pos[1]],
    scale: [METEOR_BURST_RING_S0, METEOR_BURST_RING_S0],
    color: POP_COLOR_START,
    scaleEnd: [METEOR_BURST_RING_S1 * mag, METEOR_BURST_RING_S1 * mag],
    colorEnd: STONE_PATH,
    animDuration: METEOR_BURST_RING_DUR,
    appearTime: 0,
    appearDuration: 0,
    life: METEOR_BURST_RING_DUR + FADE_OUT_SEC,
  }], kind);
  const chunks = [];
  for (let i = 0; i < METEOR_BURST_CHUNK_N; i++) {
    const a = (i * 2 * Math.PI) / METEOR_BURST_CHUNK_N + (i % 2) * 0.35 + 0.4;
    const speed = METEOR_BURST_CHUNK_SPEEDS[i % 2] * mag;
    const decel = speed / METEOR_BURST_CHUNK_LIFE;      // 寿命ちょうどで速度 0
    chunks.push(bulletDefaults({
      originPos: { x: pos[0], y: pos[1] },
      originVlc: { x: normalizeNegativeZero(Math.cos(a) * speed), y: normalizeNegativeZero(Math.sin(a) * speed) },
      gravity: { x: decel, y: normalizeNegativeZero(a + Math.PI) },
      typeName: POP_TYPE,                              // 本体と同じ絵・verts 空＝当たり判定なし
      scale: { x: METEOR_BURST_CHUNK_S0 * mag, y: METEOR_BURST_CHUNK_S0 * mag },
      color: { x: SPRITE_AS_IS[0], y: SPRITE_AS_IS[1], z: SPRITE_AS_IS[2], w: SPRITE_AS_IS[3] },
      scaleEnd: { x: METEOR_BURST_CHUNK_S1, y: METEOR_BURST_CHUNK_S1 },
      colorEnd: { x: SPRITE_AS_IS[0], y: SPRITE_AS_IS[1], z: SPRITE_AS_IS[2], w: SPRITE_AS_IS[3] },
      animDuration: METEOR_BURST_CHUNK_LIFE,
      life: METEOR_BURST_CHUNK_LIFE,
      unCounterable: true,
      useVelocityAngle: false,
      polarForm: { x: 1, y: normalizeNegativeZero(a) },
      thetaVlc: (i % 2 === 0 ? 1 : -1) * METEOR_BURST_CHUNK_SPIN,
    }));
  }
  return {
    parts: [
      flash.parts[0],
      ring.parts[0],
      { offsetSec: 0, kind: 'meteorchunk', buffer: { bullets: chunks, homing: false, isLaser: false }, spawner: NEUTRAL_SPAWNER() },
    ],
  };
}

// v23 (B)3: 隕石が飛行中に自転する。v2（区間モーション）は BulletV2UpdateJob が
// polarForm.y を更新しないため回転が付かない。よって v1 レーン（gravitySeq の非 v2 分岐と
// 同じ originVlc/gravity による直線・放物運動）へ戻し、spinBurst/gatherTile と同じ
// 視覚回転トリック（useVelocityAngle:false + polarForm.x=1 + thetaVlc）を重ねる。
// speed が既定の 0 のままなので disVector は常に 0 ＝ polarForm は位置に影響せず、
// 描画角だけが METEOR_SPIN(rad/s) で回り続ける。尾（meteorTrail/meteorLineTrail）は
// このトリックを付けていないので回らない。
const METEOR_SPIN = 2 * Math.PI;            // 自転速度（約 1 回転/秒）
const METEOR_LIFE_MARGIN = 1 / 60;          // v2 handoff と同じ 1 フレーム分のマージン

// 隕石 1 発（右→左の直線）。当たり判定のあるタイルを拡大したもの。
function meteor(y, jit) {
  const m = meteorMotion(y, jit);
  const bullet = bulletDefaults({
    originPos: { x: m.x0, y: normalizeNegativeZero(m.y0) },
    originVlc: { x: normalizeNegativeZero(m.vx), y: normalizeNegativeZero(m.vy) },
    typeName: 'stone3_tile',
    scale: { x: METEOR_SCALE, y: METEOR_SCALE },
    color: { x: SPRITE_AS_IS[0], y: SPRITE_AS_IS[1], z: SPRITE_AS_IS[2], w: SPRITE_AS_IS[3] },
    life: METEOR_FLIGHT + METEOR_LIFE_MARGIN,
    unCounterable: true,
    useVelocityAngle: false,
    polarForm: { x: 1, y: 0 },
    thetaVlc: normalizeNegativeZero(jit.spin),
  });
  return {
    parts: [{ offsetSec: 0, kind: 'meteor', buffer: { bullets: [bullet], homing: false, isLaser: false }, spawner: NEUTRAL_SPAWNER() }],
  };
}

// v24 (B): 尾の共通ビルダ。posAt(rel) が「発射から rel 秒後の本体の位置」を返す。
//   本体が通った瞬間その場に点を置き、METEOR_TRAIL_LIFE で縮めながら白 → 中間色へ寄せ、
//   さらに FADE_OUT_SEC(0.1) で消す。間隔が直径よりずっと狭いので途切れない 1 本の尾に見える。
function meteorTrailPath(posAt, flight, kind) {
  const bullets = [];
  const n = Math.max(2, Math.round(flight / METEOR_TRAIL_STEP));
  for (let i = 1; i <= n; i++) {
    const rel = (flight * i) / n;
    const p = posAt(rel);
    // v29b: 進行方向（直前の位置との差）へ向きを揃える。静止区間は 0 度のまま。
    const q = posAt(Math.max(0, rel - 0.01));
    const dx = p[0] - q[0], dy = p[1] - q[1];
    const ang = (dx * dx + dy * dy) > 1e-12 ? Math.atan2(dy, dx) : 0;
    bullets.push(bulletDefaults({
      originPos: { x: normalizeNegativeZero(p[0]), y: normalizeNegativeZero(p[1]) },
      typeName: METEOR_TRAIL_TYPE,
      scale: { x: METEOR_TRAIL_S0, y: METEOR_TRAIL_S0 },
      color: { x: METEOR_TRAIL_COLOR_START[0], y: METEOR_TRAIL_COLOR_START[1], z: METEOR_TRAIL_COLOR_START[2], w: METEOR_TRAIL_COLOR_START[3] },
      scaleEnd: { x: METEOR_TRAIL_S1, y: METEOR_TRAIL_S1 },
      colorEnd: { x: METEOR_TRAIL_COLOR_END[0], y: METEOR_TRAIL_COLOR_END[1], z: METEOR_TRAIL_COLOR_END[2], w: METEOR_TRAIL_COLOR_END[3] },
      animDuration: METEOR_TRAIL_LIFE,
      appearTime: rel,          // 隕石が通り過ぎた瞬間に出る
      appearDuration: 0,
      life: rel + METEOR_TRAIL_LIFE,
      unCounterable: true,
      useVelocityAngle: false,
      polarForm: { x: 0, y: normalizeNegativeZero(ang) },
    }));
  }
  return {
    parts: [{ offsetSec: 0, kind, buffer: { bullets, homing: false, isLaser: false }, spawner: NEUTRAL_SPAWNER() }],
  };
}

// 隕石の尾（右→左の直線）。
function meteorTrail(y, jit) {
  const m = meteorMotion(y, jit);
  return meteorTrailPath(function (rel) {
    return [m.x0 + m.vx * rel, m.y0 + m.vy * rel];
  }, METEOR_FLIGHT, 'meteortrail');
}

// 隕石が通る行の予告（横一杯の薄い帯・当たり判定なし）。
function meteorRowWarn(y, dur, extraH) {
  return warnClip(
    [{
      pos: [(COLS * CELL) / 2, y],
      scale: [COLS * CELL, METEOR_SCALE + (extraH || 0)],
      color: STONE_PATH,
      appearTime: dur,
      appearDuration: dur,
      life: dur,
    }],
    'meteorwarn'
  );
}

// 落下隕石の経路予告（通る列の縦帯・隕石の幅）。
function meteorDropWarn(x, dur) {
  const top = ROWS * CELL;
  const bottom = METEOR_DROP_Y - METEOR_SCALE / 2;
  const h = top - bottom;
  return warnClip(
    [{
      pos: [x, bottom + h / 2],
      scale: [METEOR_SCALE, h],
      color: STONE_PATH,
      appearTime: dur,
      appearDuration: dur,
      life: dur,
    }],
    'meteordropwarn'
  );
}

// 落下隕石 1 発（上から下へ等加速）。着弾時刻の flight 秒前に発射する。
// v23 (B)3: meteor() と同じ理由で v1 レーン（gravity フィールドによる放物運動）へ戻し、
// 自転（thetaVlc）を付けた。
function meteorDrop(x, flight) {
  const bullet = bulletDefaults({
    originPos: { x, y: METEOR_DROP_SPAWN_Y },
    originVlc: { x: 0, y: 0 },
    gravity: { x: METEOR_DROP_ACCEL, y: -Math.PI / 2 },
    typeName: 'stone3_tile',
    scale: { x: METEOR_SCALE, y: METEOR_SCALE },
    color: { x: SPRITE_AS_IS[0], y: SPRITE_AS_IS[1], z: SPRITE_AS_IS[2], w: SPRITE_AS_IS[3] },
    life: flight + METEOR_LIFE_MARGIN,
    unCounterable: true,
    useVelocityAngle: false,
    polarForm: { x: 1, y: 0 },
    thetaVlc: METEOR_SPIN,
  });
  return {
    parts: [{ offsetSec: 0, kind: 'meteordrop', buffer: { bullets: [bullet], homing: false, isLaser: false }, spawner: NEUTRAL_SPAWNER() }],
  };
}

// v24 (B): 落下隕石の尾（v23 まで落下隕石には尾が無かった）。落下は等加速なので
//   位置は y = SPAWN_Y - a t^2 / 2。画面上端(18)より上の点はカリングで見えない。
function meteorDropTrail(x, flight) {
  return meteorTrailPath(function (rel) {
    return [x, METEOR_DROP_SPAWN_Y - (METEOR_DROP_ACCEL * rel * rel) / 2];
  }, flight, 'meteordroptrail');
}

// v24 (B): 落下隕石の着地でつぶれる 1 コマ（縦 0.6 / 横 1.3 へ 0.10 秒）。
//   色は w=0（無着色）のままなので、本体（stone3_tile）と同じテクスチャに見える。
function meteorSquash(pos) {
  return warnClip([{
    type: BLINK_TYPE,
    pos: [pos[0], pos[1]],
    scale: [METEOR_SCALE, METEOR_SCALE],
    color: STONE_TILE_END,
    scaleEnd: [METEOR_SCALE * METEOR_SQUASH_X, METEOR_SCALE * METEOR_SQUASH_Y],
    colorEnd: STONE_TILE_END,
    animDuration: METEOR_SQUASH_DUR,
    appearTime: 0,
    appearDuration: 0,
    life: METEOR_SQUASH_DUR + FADE_OUT_SEC,
  }], 'meteorsquash');
}

// ── v28: 隕石の多段モーション（shovelPath の隕石版）───────────────────────────
//   指示書 v28 の末尾（111.9〜141.7s）は「上向き初速＋下向き重力で減速して静止」
//   「落ちてきて下で止まる」「イージングで寄って少し戻してから落ちる」など、
//   1 発の隕石が途中で加速度を変える動きばかりになる。既存の meteor()/meteorDrop()/
//   meteorLine() はどれも 1 区間・固定の加速度なので使えない。
//   shovelPath と同じ作り（v1 レーンの originPos/originVlc/gravity を区間ごとに
//   置き直す handoff）を stone3_tile ＋ 自転つきで用意する。
//   segs = [{ dur, ax, ay, vx?, vy? }]（ax/ay はワールドの等加速度成分。vx/vy を
//   指定するとその区間の入り口で速度を差し替える）。
//   既存の meteor()/meteorDrop()/meteorLine() には手を入れていない。
function meteorPath(pos0, vel0, segs, kind, spin) {
  let px = pos0[0], py = pos0[1], vx = vel0[0], vy = vel0[1], t = 0;
  const parts = [];
  segs.forEach(function (sg, i) {
    if (sg.vx !== undefined) vx = sg.vx;
    if (sg.vy !== undefined) vy = sg.vy;
    const mag = Math.sqrt(sg.ax * sg.ax + sg.ay * sg.ay);
    const dir = mag > 1e-9 ? Math.atan2(sg.ay, sg.ax) : 0;
    const last = i === segs.length - 1;
    parts.push({
      offsetSec: t,
      kind: kind,
      buffer: {
        bullets: [bulletDefaults({
          originPos: { x: normalizeNegativeZero(px), y: normalizeNegativeZero(py) },
          originVlc: { x: normalizeNegativeZero(vx), y: normalizeNegativeZero(vy) },
          gravity: { x: mag, y: normalizeNegativeZero(dir) },
          typeName: 'stone3_tile',
          scale: { x: METEOR_SCALE, y: METEOR_SCALE },
          color: { x: SPRITE_AS_IS[0], y: SPRITE_AS_IS[1], z: SPRITE_AS_IS[2], w: SPRITE_AS_IS[3] },
          life: last ? sg.dur : sg.dur + METEOR_LIFE_MARGIN,
          unCounterable: true,
          useVelocityAngle: false,
          polarForm: { x: 1, y: 0 },
          thetaVlc: normalizeNegativeZero(spin === undefined ? METEOR_SPIN : spin),
        })],
        homing: false,
        isLaser: false,
      },
      spawner: NEUTRAL_SPAWNER(),
    });
    px += vx * sg.dur + 0.5 * sg.ax * sg.dur * sg.dur;
    py += vy * sg.dur + 0.5 * sg.ay * sg.dur * sg.dur;
    vx += sg.ax * sg.dur;
    vy += sg.ay * sg.dur;
    t += sg.dur;
  });
  return { parts: parts };
}

// 上の経路の「発射から rel 秒後の位置」を返す関数を作る（尾を置くのに使う）。
function meteorPathPos(pos0, vel0, segs) {
  const marks = [];
  let px = pos0[0], py = pos0[1], vx = vel0[0], vy = vel0[1], t = 0;
  segs.forEach(function (sg) {
    if (sg.vx !== undefined) vx = sg.vx;
    if (sg.vy !== undefined) vy = sg.vy;
    marks.push({ t0: t, dur: sg.dur, px: px, py: py, vx: vx, vy: vy, ax: sg.ax, ay: sg.ay });
    px += vx * sg.dur + 0.5 * sg.ax * sg.dur * sg.dur;
    py += vy * sg.dur + 0.5 * sg.ay * sg.dur * sg.dur;
    vx += sg.ax * sg.dur;
    vy += sg.ay * sg.dur;
    t += sg.dur;
  });
  return function (rel) {
    let m = marks[0];
    for (let i = 0; i < marks.length; i++) {
      if (rel >= marks[i].t0) m = marks[i];
    }
    const u = rel - m.t0;
    return [m.px + m.vx * u + 0.5 * m.ax * u * u, m.py + m.vy * u + 0.5 * m.ay * u * u];
  };
}

// その尾。静止している区間に点が積み上がると光の塊に見えるので、尾を引く長さ
// （trailDur 秒）を呼び出し側で指定する。
function meteorPathTrail(pos0, vel0, segs, trailDur, kind) {
  return meteorTrailPath(meteorPathPos(pos0, vel0, segs), trailDur, kind);
}

// ── v22: 壁に当てる隕石（マーカー 49〜51）と、回転しながら集まるタイル（マーカー 48）──
//   参考: https://www.youtube.com/watch?v=-zhZYYl8USk 1:09 付近の「壁に隕石を当てて爆破」。
//   v21 の隕石（右→左・尾付き）を、始点/終点/飛行時間を選べる形に一般化しただけで、
//   見た目（大きさ・尾の数・尾の縮み方）は v21 と同一。既存の meteor()/meteorTrail() は触っていない。
const WALL_M_HALF = METEOR_SCALE / 2;        // 隕石の半径ぶん。壁に接した時の中心 x はこのぶん内側
const WALL_LEFT_X = -2.0;                    // 発射位置（画面左外・カリング境界のきわ）
const WALL_RIGHT_X = 34.5;                   // 発射位置（画面右外。v21 の METEOR_START_X と同じ）
const WALL_HIT_RIGHT = COLS * CELL - WALL_M_HALF;  // 右壁に接した時の中心 x（30.4）
const WALL_HIT_LEFT = WALL_M_HALF;                 // 左壁に接した時の中心 x（1.6）

// 隕石 1 発（始点 x0 → 終点 x1・高さ y 固定・flight 秒の等速直線）。
// v23 (B)3: meteor() と同じ理由で v1 レーンへ戻し、自転（thetaVlc）を付けた。
function meteorLine(x0, x1, y, flight) {
  const vx = (x1 - x0) / flight;
  const bullet = bulletDefaults({
    originPos: { x: x0, y },
    originVlc: { x: vx, y: 0 },
    typeName: 'stone3_tile',
    scale: { x: METEOR_SCALE, y: METEOR_SCALE },
    color: { x: SPRITE_AS_IS[0], y: SPRITE_AS_IS[1], z: SPRITE_AS_IS[2], w: SPRITE_AS_IS[3] },
    life: flight + METEOR_LIFE_MARGIN,
    unCounterable: true,
    useVelocityAngle: false,
    polarForm: { x: 1, y: 0 },
    thetaVlc: METEOR_SPIN,
  });
  return {
    parts: [{ offsetSec: 0, kind: 'meteorline', buffer: { bullets: [bullet], homing: false, isLaser: false }, spawner: NEUTRAL_SPAWNER() }],
  };
}

// その尾（経路だけ差し替えたもの）。
function meteorLineTrail(x0, x1, y, flight) {
  return meteorTrailPath(function (rel) {
    return [x0 + ((x1 - x0) * rel) / flight, y];
  }, flight, 'meteorlinetrail');
}

// マーカー 48 の「回転しながら 1 点へ集まるタイル」1 枚。
//   spinBurst と同じ視覚回転トリック（useVelocityAngle:false + polarForm + thetaVlc）を
//   重ねてあるので、飛行中も描画角だけが回り続ける（polarForm は r=1・speed 既定なので
//   位置には効かない）。
//
//   v24 (A): 等速直線をやめ、**静止 → 等加速で 1 点へ吸い込まれる**動きにした。
//   参考（Lightspeed 1:02）の実測は等加速度そのもので、初速 861 px/s・加速度 2274 px/s^2・
//   到達速度 1468 px/s（＝初速の 1.70 倍）だった。こちらのタイルは 108.33s まで静止して
//   いるので、同じ等加速度の法則を初速 0 で当てる。すなわち移動量は s(u) = u^2。
//   到達時刻はどのタイルも flight ちょうどで、距離が違っても加速度を距離に比例させる
//   （a = 2d / flight^2）ことで**同時刻に 1 点へ着く**。
//
//   実装は v2 セグメントの折れ線ではなく v1 レーンの gravity フィールドを使う。理由は 2 つ:
//     ・BulletDataUpdateJob.cs:132 が h = gravity.x * t^2 / 2 を足す＝u^2 の厳密解で、
//       12 分割の折れ線近似より正確（継ぎ目のフェードも出ない）。
//     ・v2（BulletV2UpdateJob）は polarForm.y を更新しないので自転が消える（v23 で確認済み）。
//       自転を残すという条件と両立できるのは v1 レーンだけ。
function gatherTile(from, to, flight, spin) {
  const dx = to[0] - from[0];
  const dy = to[1] - from[1];
  const dist = Math.sqrt(dx * dx + dy * dy);
  const accel = (2 * dist) / (flight * flight);   // s(flight) = a*flight^2/2 = dist
  const bullet = bulletDefaults({
    originPos: { x: from[0], y: from[1] },
    originVlc: { x: 0, y: 0 },
    gravity: { x: accel, y: normalizeNegativeZero(Math.atan2(dy, dx)) },
    typeName: 'stone3_tile',
    scale: { x: TILE, y: TILE },
    color: { x: SPRITE_AS_IS[0], y: SPRITE_AS_IS[1], z: SPRITE_AS_IS[2], w: SPRITE_AS_IS[3] },
    life: flight,
    unCounterable: true,
    useVelocityAngle: false,
    polarForm: { x: 1, y: 0 },
    thetaVlc: spin,
  });
  return {
    parts: [{ offsetSec: 0, kind: 'gather', buffer: { bullets: [bullet], homing: false, isLaser: false }, spawner: NEUTRAL_SPAWNER() }],
  };
}

// ── v27 (17)(18): 集合タイルの 3 段モーション ────────────────────────────────
//   区間ごとに 1 発ずつ弾を分ける v1 レーンの handoff（gravitySeq の非 v2 分岐と同じ
//   originPos/originVlc/gravity の閉形式）。v2 セグメントにしないのは、BulletV2UpdateJob が
//   polarForm.y を更新せず自転が消えるため（v23 で確認済み）。
//     (1) 進入   画面外の点から初速つきで入り、GATHER_SETTLE で速度 0 になる一定減速（ease out）
//     (2) 反動   集合点と逆向きに初速 0 の等加速で GATHER_RECOIL_DIST だけ引く（ため）
//     (3) 突入   反動の速度を残したまま集合点向きに等加速。GATHER_IMPACT ちょうどで到達（ease in）
//   (3) は初速が集合点と逆向きなので、いったん止まってから加速する「ため → 発射」に見える。
function gatherSeg(pos, vel, accelMag, accelDir, dur, spin, last) {
  const bullet = bulletDefaults({
    originPos: { x: normalizeNegativeZero(pos[0]), y: normalizeNegativeZero(pos[1]) },
    originVlc: { x: normalizeNegativeZero(vel[0]), y: normalizeNegativeZero(vel[1]) },
    gravity: { x: accelMag, y: normalizeNegativeZero(accelDir) },
    typeName: 'stone3_tile',
    scale: { x: TILE, y: TILE },
    color: { x: SPRITE_AS_IS[0], y: SPRITE_AS_IS[1], z: SPRITE_AS_IS[2], w: SPRITE_AS_IS[3] },
    life: last ? dur : dur + METEOR_LIFE_MARGIN,
    unCounterable: true,
    useVelocityAngle: false,
    polarForm: { x: 1, y: 0 },
    thetaVlc: spin,
  });
  return {
    parts: [{ offsetSec: 0, kind: 'gather', buffer: { bullets: [bullet], homing: false, isLaser: false }, spawner: NEUTRAL_SPAWNER() }],
  };
}

function gatherFly(from, seat, to, spin) {
  const out = [];
  // (1) 進入（ease out）: 距離 d を dA で、終端速度 0 の等減速で詰める → v0 = 2d/dA
  const dA = GATHER_SETTLE - GATHER_ENTER;
  const v0x = (2 * (seat[0] - from[0])) / dA;
  const v0y = (2 * (seat[1] - from[1])) / dA;
  const v0 = Math.sqrt(v0x * v0x + v0y * v0y);
  out.push([GATHER_ENTER, gatherSeg(from, [v0x, v0y], v0 / dA, Math.atan2(-v0y, -v0x), dA, spin, false)]);

  // 集合点へ向かう単位ベクトル
  const ux = to[0] - seat[0];
  const uy = to[1] - seat[1];
  const uL = Math.sqrt(ux * ux + uy * uy);
  const ex = ux / uL;
  const ey = uy / uL;

  // (2) 反動: 逆向きに初速 0 の等加速で GATHER_RECOIL_DIST 進む
  const dB = GATHER_RECOIL_END - GATHER_SETTLE;
  const aB = (2 * GATHER_RECOIL_DIST) / (dB * dB);
  const vB = aB * dB;                                   // 引き終わりの速さ（逆向き）
  out.push([GATHER_SETTLE, gatherSeg(seat, [0, 0], aB, Math.atan2(-ey, -ex), dB, spin, false)]);

  // (3) 突入（ease in）: 逆向きの速度 vB を残したまま集合点向きに等加速。
  //     P(dC) = seatB + (-e*vB)*dC + (1/2)a*e*dC^2 = to より a = 2(D + vB*dC)/dC^2。
  const seatB = [seat[0] - ex * GATHER_RECOIL_DIST, seat[1] - ey * GATHER_RECOIL_DIST];
  const dC = GATHER_IMPACT - GATHER_RECOIL_END;
  const dist = uL + GATHER_RECOIL_DIST;
  const aC = (2 * (dist + vB * dC)) / (dC * dC);
  out.push([GATHER_RECOIL_END, gatherSeg(seatB, [-ex * vB, -ey * vB], aC, Math.atan2(ey, ex), dC, spin, true)]);
  return out;
}

// 画面外の飛び込み開始点。参考（bePI-wq_lNk 1:02）は上端と左右の角から入ってくるので、
//   セルの列で近い辺を選ぶ。x は カリング境界（-2 〜 36）の内側・画面（0〜32）の外。
function gatherEntry(cell) {
  const p = cellCenter(cell[0], cell[1]);
  if (cell[0] <= 2) return [-1.9, p[1] + 4];
  if (cell[0] >= COLS - 3) return [34.0, p[1] + 4];
  return [p[0], ROWS * CELL + 6];
}

// ── v21: 鎖の向きの一般化（マーカー 37〜39）─────────────────────────────────
//   v15〜v19 の鎖は「下から上へ這う縦の鎖」だけだった。マーカー 38 は横方向、
//   39 は上から下なので、進む向きと揺れる向きを設定で選べる版を足す。
//   既存の snakeTile/snakePop/snakeWarn/snakeBreakTime は一切触っていない
//   （マーカー 1〜17 の弾を v20 と 1 バイトも変えないため）。こちらは v21 専用。
//
//   cfg.axis 'V' … 段が y 方向に積み上がり、揺れは x（lane.col が中心列）
//   cfg.axis 'H' … 段が x 方向に並び、揺れは y（lane.row が中心行）
//   cfg.reverse   … true で進行方向を反転（V なら上→下、H なら右→左）
//
//   マーカー 37/39 の縦の鎖は 1 段 0.0625s（16 段 = 1.000s）と v19 までの 0.09375s より
//   速い。38 の横の鎖は幅 32 ユニットを 28 段で覆い 1 段 0.0357s（28 段 = 1.000s）。
//   速いぶん揺れの周期も詰めてあり、どちらも「1 段が画面に居るあいだ（7 段ぶん）」が
//   揺れの 1 周期より長い＝帯のどのセルも必ず 1 度は鎖の破壊半径に入る。
const SNAKE_H_STEPS = 28;                                   // 28 × 1.15 = 32.2 ユニット（画面幅 32 を覆う）
const SNAKE_H_X0 = (COLS * CELL - (SNAKE_H_STEPS - 1) * SNAKE_STEP_Y) / 2;   // 0.475
const CHAIN_V_FAST = { axis: 'V', steps: SNAKE_STEPS, base: SNAKE_Y0, rowStep: 0.0625, period: beats(0.75), reverse: false };
const CHAIN_V_FAST_DOWN = { axis: 'V', steps: SNAKE_STEPS, base: SNAKE_Y0, rowStep: 0.0625, period: beats(0.75), reverse: true };
const CHAIN_H = { axis: 'H', steps: SNAKE_H_STEPS, base: SNAKE_H_X0, rowStep: 0.0357, period: beats(0.375), reverse: false };

// 段 k の「進む向き」の座標（V なら y・H なら x）。
function chainAdvance(cfg, k) {
  const idx = cfg.reverse ? cfg.steps - 1 - k : k;
  return cfg.base + idx * SNAKE_STEP_Y;
}
// 段 k の「揺れる向き」の座標（V なら x・H なら y）。
function chainSwing(cfg, t, k, lane) {
  const c = CELL * ((cfg.axis === 'V' ? lane.col : lane.row) + 0.5);
  return c + SNAKE_AMP * Math.sin((2 * Math.PI * t) / cfg.period + k * SNAKE_ROW_PHASE + lane.phase);
}
function chainPos(cfg, t, k, lane) {
  const a = chainAdvance(cfg, k);
  const w = chainSwing(cfg, t, k, lane);
  return cfg.axis === 'V' ? [w, a] : [a, w];
}
// 段 k が画面に居る時間帯 [生える, 消える]。
function chainWindow(cfg, t0, k) {
  const a = t0 + k * cfg.rowStep;
  return [a, a + SNAKE_LEN * cfg.rowStep];
}
// 鎖のタイル 1 枚（v2 レーンの折れ線。段は動かず、直交方向へサインで往復）。
function chainTile(cfg, t0, k, lane) {
  const win = chainWindow(cfg, t0, k);
  const dur = win[1] - win[0];
  const segs = [];
  for (let i = 1; i <= SNAKE_SEGMENTS; i++) {
    const rel = (dur * i) / SNAKE_SEGMENTS;
    segs.push({ until: rel, moveTo: chainPos(cfg, win[0] + rel, k, lane) });
  }
  return gravitySeq(
    {
      pos: chainPos(cfg, win[0], k, lane),
      vel: [0, 0],
      type: 'stone3_chain',
      scale: [SNAKE_TILE, SNAKE_TILE],
      color: SPRITE_AS_IS,
      unCounterable: true,
    },
    segs,
    'snake',
    { v2: true }
  );
}
// 出現フラッシュ。
function chainPop(cfg, t0, k, lane) {
  const p = chainPos(cfg, chainWindow(cfg, t0, k)[0], k, lane);
  const big = SNAKE_TILE * SNAKE_POP_SCALE;
  return warnClip(
    [{
      type: BLINK_TYPE,
      pos: p,
      scale: [big, big],
      color: POP_COLOR_START,
      scaleEnd: [SNAKE_TILE, SNAKE_TILE],
      colorEnd: STONE_TILE_END,
      animDuration: SNAKE_POP_DURATION,
      appearTime: 0,
      appearDuration: 0,
      life: SNAKE_POP_DURATION + FADE_OUT_SEC,
    }],
    'snakepop'
  );
}
// 予告（鎖が掃く幅の帯を、進む向きへ画面いっぱいに通しで）。
function chainWarn(cfg, lanes, color, dur, kind) {
  const items = lanes.map(function (lane) {
    const c = CELL * ((cfg.axis === 'V' ? lane.col : lane.row) + 0.5);
    return cfg.axis === 'V'
      ? { pos: [c, (ROWS * CELL) / 2], scale: [SNAKE_HALF_W * 2, ROWS * CELL], color: color, appearTime: dur, appearDuration: dur, life: dur }
      : { pos: [(COLS * CELL) / 2, c], scale: [COLS * CELL, SNAKE_HALF_W * 2], color: color, appearTime: dur, appearDuration: dur, life: dur };
  });
  return warnClip(items, kind);
}
// セル(col,row) の残留タイルを鎖が砕く時刻。どの鎖も通らなければ null。
function chainBreakTime(cfg, col, row, t0, lanes) {
  const center = cellCenter(col, row);
  const STEP = 1 / 120;
  let best = null;
  for (let k = 0; k < cfg.steps; k++) {
    const a = chainAdvance(cfg, k);
    // 進む向きの座標がセルと重ならない段は見ない
    if (Math.abs(a - (cfg.axis === 'V' ? center[1] : center[0])) > SNAKE_BREAK_DY) continue;
    const win = chainWindow(cfg, t0, k);
    lanes.forEach(function (lane) {
      for (let t = win[0]; t <= win[1]; t += STEP) {
        const w = chainSwing(cfg, t, k, lane);
        if (Math.abs(w - (cfg.axis === 'V' ? center[0] : center[1])) <= SNAKE_BREAK_R) {
          if (best === null || t < best) best = t;
          return;
        }
      }
    });
  }
  return best;
}

// 自機の初期位置(16,2.4) が入るセル。最初の拍だけは必ずここを逃げ場にする（初見の詰み防止）。
const START_GAP = [Math.floor(16 / CELL), Math.floor(2.4 / CELL)];

const MARKERS = {
  1: B(S1_BEAT),
  2: B(S2_BEAT),
  3: B(S3_BEAT),
  4: B(S4_BEAT),
  5: B(S5_BEAT),
  6: B(S6_BEAT),
  7: B(S7_BEAT),
  8: B(S8_BEAT),
  // 延長のジャンプ先（ラボのシークバー用。弾データには影響しない）。
  // v19: 仮区間⑪〜⑭を削除したので、9 以降は指示書のマーカーそのものへ貼り替えた。
  9: MK1_WARN1,       // 鎖攻撃 1 回目の予告①（33.396s）
  10: MK4_TILEWARN,   // タイル①〜④の予告開始（35.938s）
  11: MK9_WARN1,      // 鎖攻撃 2 回目の予告①（40.008s）
  12: MK11_CHAIN,     // 鎖攻撃 2 回目（41.262s）
  13: MK12_TILEWARN,  // タイル①②の予告開始（42.510s）
  14: MK15_BLAST4,    // タイル爆破 x4（45.006s）
  15: MK16_WARN1,     // 鎖攻撃 3 回目の予告①（47.299s）
  16: MK17_TILEWARN,  // タイル攻撃 2 回目の予告開始（49.375s）
  17: B(S15_BEAT),    // 仮区間⑮（53.333s）
  18: B(S16_BEAT),    // 仮区間⑯（56.667s）
  // v21: 指示書のマーカー 18〜42。
  19: MK18_SLIDE1,        // 右列タイルの左流し①（66.771s）
  20: MK22_METEOR1,       // 隕石 5 連の 1 発目（70.104s）
  21: MK27_METEOR_REP,    // 隕石 5 連の 2 巡目（73.346s）
  22: MK28_METEOR8,       // 隕石 8 連（76.771s）
  23: MK29_SLIDE_AGAIN,   // 右列タイル again（80.010s）
  24: MK30_TILE5,         // タイル攻撃 5 回（83.229s）
  25: MK31_SLIDE_AGAIN2,  // 右列タイル again 2 回目（86.875s）
  26: MK32_TILE_SHOW,     // タイル表示 again（90.012s）
  27: MK33_BLAST1,        // タイル爆破（93.438s）
  28: MK37_CHAIN_LR,      // 左右の列を鎖で消す（98.342s）
  29: MK38_CHAIN_TB,      // 上下の列を鎖で消す（99.063s）
  30: MK40_DROP_MID,      // 落下隕石①（100.014s）
  // v22: 指示書のマーカー 43〜51。
  31: MK43_TILE6,         // タイル表示 x6（105.104s）
  32: MK45_NEXTWARN,      // 次の攻撃の予告＋タイル（107.508s）
  33: MK48_GATHER,        // 下に集めて爆破（108.344s）
  34: MK49_WALL1,         // 壁隕石 1 発目（109.271s）
};

export default stage(
  {
    name: 'stone3',
    music: 'Assets/StageData/stone3/stone3.mp3',
    bpm: BPM,
    offset: 0,
    markers: MARKERS,
    playArea: [32, 18],
    difficulties: ['easy', 'normal', 'lunatic'],
    // v22: 最後の演出はマーカー 51（110.938s）の壁隕石の爆破と放射弾。放射弾は速度 7〜11 で
    //   寿命なしなので、画面を抜けるのに数秒かかる。v21 と同じ「最後の爆破 + 2.7s」の規則で
    //   110.938 + 2.7 ≒ 113.6s を末尾にした（曲のアウトロは 113.33s から）。
    // v28: 指示書の末尾（141.6533 の大爆破）まで演出が伸びたので 142.5 へ延長した。
    //   曲は 143.3s から急速にフェードして 150.02s で終わる。旧「石工」の endTime と同じ値。
    //   install_stone3.py --bundle 142.5 で stage.json 側にも同じ値を書く。
    // v29 (10): 指示 141.507「最後のゲーム自体のフェードアウトが早すぎる」。
    //   GManager は SReader.HasReachedEndTime になった瞬間に PixelTransition の白覆いへ
    //   入るので、endTime ＝ 画面が白くなる時刻。142.5（最後の大爆破 141.6533 の 0.85 秒後）
    //   では爆破の破片が消えきる前に暗転していた。**このステージの endTime だけ** 1.75 秒
    //   伸ばして 144.25 にし、破片が散り切って曲のフェード（143.3〜）に乗る余韻を作る。
    //   他ステージの endTime には触っていない。
    endTime: 144.25,
  },
  (s) => {
    // v27: 前半（33.6〜56s）の内容を変えたぶん乱数の消費数が変わる。後半（66.8s〜）へ
    //   入る前に乱数の位置を v26 と同じところへ戻せるよう、差し替えられる形にしておく。
    let rngState = makeRng(20260902);
    const rng = function () { return rngState(); };
    function reseedRng(seed) { rngState = makeRng(seed); }
    const lead = beats(WARN_BEATS);
    // v11: 中央（12x5 = 60 セル）に毎拍出す一時タイルの密度。
    //   v10 は 10x3 = 30 セルに D(0.125, 0.165, 0.20)＝毎拍 4/5/6 枚。セル数が倍になったので
    //   まず 1/2 にして枚数を据え置き、さらに帯の縮小と同じ比 84/114 = 0.7368 を掛けている。
    //   ＝ v10 の 0.3684 倍。毎拍の中央の枚数は easy 3 / normal 4 / lunatic 4 枚前後。
    const CENTER_RATE = D(0.0461, 0.0608, 0.0737);
    // v10: 表示区間の終わりに縁の帯が埋まっている割合の目安（連結判定で弾かれるぶん実測は少し下がる）。
    // v11 でも目標値は据え置き。帯が 114→84 セルに減るので、同じ割合なら新規枚数も比例して減る。
    const BAND_TARGET = D(0.50, 0.64, 0.72);

    // burst(): 爆破の放射弾。区間②④⑤⑦で共通に使う（弾数・速度の難易度比は v3 のまま）。
    // v13 (B): countMul で放射弾の数を増減できるようにした（曲の盛り上がりに合わせる）。
    //   既定 1.0＝区間①〜⑧と同じ。区間⑯（2 周目の頂点）だけ 1.3 にしている。
    function burst(center, index, countMul = 1) {
      return spinBurst({
        pos: [center[0], center[1]],
        count: Math.round(D(10, 12, 14) * countMul),
        speed: D(7, 9, 11),
        type: 'stone3_bullet',
        life: 0,                          // 寿命なし＝画面外へ出て cull されるまで飛ぶ
        scale: [BULLET_SCALE, BULLET_SCALE],
        color: SPRITE_AS_IS,   // v12: 弾スプライト自体が石色のドット絵なので無着色
        angleOffset: rng() * 2 * Math.PI, // 爆破ごとに別オフセット角（rad）
        spin: SPIN_RATE * (index % 2 === 0 ? 1 : -1),
        kind: 'blast',
        unCounterable: true,
      });
    }

    // ======================================================================
    // タイル表示区間（区間①③）— v10 で配置ルールを作り直した
    //   各拍頭で
    //     ・逃げ場 3x3 を GAPS_PER_BEAT 箇所ぶん確保（ここには絶対にタイルを置かない）
    //     ・縁の帯（v11: BAND=2 セルの外周・84 セル）へ新しいタイルを積む。**拍末で消さずに残る**
    //     ・中央（v11: 12x5 = 60 セル）へ一時タイルを置く。**拍末（次の拍頭）で必ず消える**
    //     ・タイルを 1 枚置くごとに「空きセルが 4 近傍で 1 つに繋がっている」ことを検査し、
    //       崩す置き方は捨てる（＝自機が閉じ込められない。emptyIsConnected 参照）
    //   帯の追加率は「len 拍かけて bandTarget まで埋める」等比の刻みにしてある。
    //   最初の拍がいちばん多く（帯の空きが多いので）、後半になるほど新規枚数は減る。
    //   戻り値 = 帯に積んだタイルの一覧 [{col,row,strike,end,lead}]。
    //   end（消える時刻）は爆破区間・シャベル区間で上書きしてから emitBandTiles() で出す。
    // ======================================================================
    //
    //   v13 (B): cfg.bandCells / cfg.centerCells で溜める場所の変奏を選べるようにした
    //   （区間⑨は上下だけ・区間⑬は左右だけ）。cfg.preBlocked には「この区間の前から
    //   画面に残っているタイル」のセルキーの集合を渡す。連結判定（emptyIsConnected）の
    //   初期状態に入れて候補からも外すので、前の区間の帯と合わせて自機が閉じ込められない。
    function tilePhase(cfg) {
      const bandCells = cfg.bandCells || BAND_CELLS;
      const centerCells = cfg.centerCells || CENTER_CELLS;
      const preBlocked = cfg.preBlocked || new Set();
      let bandOccupied = new Set(preBlocked);   // 既に埋まっている扱い（再抽選しない）
      const bandTiles = [];
      // v17: 拍等間隔（firstBeat + len）のほかに、任意の時刻列 cfg.times を渡せるようにした。
      //   指示書のマーカーは等間隔ではないので、補充（区間⑨' の (e)）はこちらを使う。
      //   cfg.leads を渡すと予告のリードも 1 回ずつ変えられる（前のタイルの実体化から
      //   次のタイルの実体化まで予告を出しっぱなしにするため）。
      const strikes =
        cfg.times ||
        Array.from({ length: cfg.len }, function (_, i) { return B(cfg.firstBeat + i); });
      const bandRate = 1 - Math.pow(1 - cfg.bandTarget, 1 / strikes.length);

      for (let i = 0; i < strikes.length; i++) {
        const strike = strikes[i];
        const myLead = cfg.leads ? cfg.leads[i] : lead;
        // v29 (3): cfg.clearEachStrike を渡すと、帯へ積んだタイルも「次の表示が出るまで」で
        //   消える（＝積み上がらない）。指示 85.42「このタイルは残さず、出すごとに消してほしい
        //   （次の攻撃の視認性が死ぬので）」。最後の 1 回は cfg.finalEnd で消す。
        //   消えるタイルは claimed 済みにして、あとの爆破区間・鎖が対象に取らないようにする
        //   （blastPhase / chainAttackG は claimed を飛ばし、end を書き換えないため）。
        const myBandEnd = cfg.clearEachStrike
          ? (i + 1 < strikes.length ? strikes[i + 1]
             : (cfg.finalEnd !== undefined ? cfg.finalEnd : cfg.bandEnd))
          : cfg.bandEnd;
        const myClaimed = !!cfg.clearEachStrike;
        if (cfg.clearEachStrike) bandOccupied = new Set(preBlocked);   // 毎回まっさらから選び直す
        // 中央の一時タイルは「次のタイルが出るまで」に消す。等間隔（cfg.times 無し）の
        // 呼び出しでは従来どおり厳密に 1 拍にする（引き算で丸め誤差を出さないため）。
        const centerLife =
          (cfg.times && i + 1 < strikes.length ? strikes[i + 1] - strike : beats(1)) + SEAM_MARGIN;

        // (a) 逃げ場: 3x3 の空きセル領域。区間①の1拍目の1箇所目は自機の初期位置に固定。
        const gapCells = new Set();
        for (let gi = 0; gi < GAPS_PER_BEAT; gi++) {
          const anchor =
            cfg.pinStartGap && i === 0 && gi === 0
              ? START_GAP
              : [1 + Math.floor(rng() * (COLS - 2)), 1 + Math.floor(rng() * (ROWS - 2))];
          for (let dc = -1; dc <= 1; dc++) {
            for (let dr = -1; dr <= 1; dr++) {
              const c = anchor[0] + dc;
              const r = anchor[1] + dr;
              if (c < 0 || c >= COLS || r < 0 || r >= ROWS) continue;
              gapCells.add(key(c, r));
            }
          }
        }

        // この拍に画面へ出ているタイル（帯の既存ぶん＋これから置くぶん）を溜める集合。
        const blocked = new Set(bandOccupied);

        // (b) 帯へ積むタイル（残留）。連結を壊す候補は飛ばす。
        const free = bandCells.filter((c) => !bandOccupied.has(key(c[0], c[1])));
        const bandWant = Math.round(free.length * bandRate);
        const bandPicks = [];
        let bandCand = shuffled(free.filter((c) => !gapCells.has(key(c[0], c[1]))), rng);
        // v14: cfg.priority（セルキーの集合）を渡すと、その候補を先に試す。
        //   波で砕かれたセルとその 4 近傍を優先して積み直すために使う（補充）。
        if (cfg.priority) {
          const pri = cfg.priority;
          bandCand = bandCand
            .filter((c) => pri.has(key(c[0], c[1])))
            .concat(bandCand.filter((c) => !pri.has(key(c[0], c[1]))));
        }
        for (let n = 0; n < bandCand.length && bandPicks.length < bandWant; n++) {
          const cell = bandCand[n];
          const k = key(cell[0], cell[1]);
          blocked.add(k);
          if (!emptyIsConnected(blocked)) {
            blocked.delete(k);
            continue;
          }
          bandPicks.push(cell);
          bandOccupied.add(k);
          bandTiles.push({ col: cell[0], row: cell[1], strike, end: myBandEnd, lead: 0, claimed: myClaimed });
        }

        // (c) 中央のタイル（拍末で消える一時タイル）。こちらも連結を壊さない範囲で置く。
        const centerPicks = [];
        const centerWant = Math.round(centerCells.length * cfg.centerRate);
        const centerCand = shuffled(
          centerCells.filter((c) => !gapCells.has(key(c[0], c[1])) && !preBlocked.has(key(c[0], c[1]))),
          rng
        );
        for (let n = 0; n < centerCand.length && centerPicks.length < centerWant; n++) {
          const cell = centerCand[n];
          const k = key(cell[0], cell[1]);
          blocked.add(k);
          if (!emptyIsConnected(blocked)) {
            blocked.delete(k);
            continue;
          }
          centerPicks.push(cell);
        }

        const appearing = centerPicks.concat(bandPicks);
        if (appearing.length === 0) continue;

        // (d) 予告（暗いピンク・無害）: この拍に出る全タイルぶんを1クリップにまとめる
        s.at(
          strike - myLead,
          tileField(appearing, {
            type: 'warn_box',
            color: STONE_WARN,
            appearTime: myLead,
            appearDuration: myLead,
            life: myLead + SEAM_MARGIN,
            kind: 'tilewarn',
          })
        );

        // (d2) 実体化の瞬間のポップ（v9 の出現アニメのまま）
        s.at(strike, tilePop(appearing, 'tilepop'));

        // (e) 中央の一時タイルの実体。次の拍頭で消える。
        if (centerPicks.length > 0) {
          s.at(
            strike,
            tileField(centerPicks, {
              type: 'stone3_tile',
              color: SPRITE_AS_IS,   // v11: 無着色＝石テクスチャそのまま
              life: centerLife,
              kind: 'tile',
            })
          );
        }

        // (f) 帯のタイルの実体は、消える時刻が確定してから emitBandTiles() でまとめて出す。
      }
      return bandTiles;
    }

    // v10: 帯タイルの実体クリップ。出た拍と消える時刻が同じものを 1 クリップにまとめる。
    //   lead>0（爆破される）のタイルは BLAST_LEAD_OUT ぶん手前で消す（爆破中心にタイルを残さない）。
    function emitBandTiles(tiles) {
      const groups = new Map();
      tiles.forEach(function (t) {
        const gk = t.strike + '|' + t.end + '|' + t.lead;
        if (!groups.has(gk)) groups.set(gk, { strike: t.strike, end: t.end, lead: t.lead, cells: [] });
        groups.get(gk).cells.push([t.col, t.row]);
      });
      groups.forEach(function (g) {
        if (g.cells.length === 0) return;
        s.at(
          g.strike,
          tileField(g.cells, {
            type: 'stone3_tile',
            color: SPRITE_AS_IS,   // v11: 無着色＝石テクスチャそのまま
            life: g.end - g.strike - g.lead,
            kind: 'tileband',
          })
        );
      });
    }

    // ======================================================================
    // タイル爆破区間（区間②④）— v10 で対象の選び方を変えた
    //   残留タイルが縁の帯になったので、帯の 4 辺（左・上・右・下）を順番に回りながら
    //   その辺のタイルを 1 枚ずつ選ぶ。1 拍 2 枚なので、隣り合う 2 枚は必ず別の辺になり、
    //   区間を通して左右上下へ均等に散る。
    //   ・爆破の1拍前から対象タイルが点滅、半拍前に薄い予告とリング予告
    //   ・爆破時刻ちょうどでタイルの life が尽き、同時に spinBurst（放射弾）が出る
    //
    //   v13 (A3): 頻度を半分にした。v12 は「毎拍 2 枚」だったが、
    //   **各小節の 1 拍目と 3 拍目だけ・1 回 2 枚**（= 2 拍に 1 回）にする。
    //   拍番号 n の小節内位置は n % 4（0 = 1 拍目 / 2 = 3 拍目）。BPM144・offset 0 で
    //   小節線は拍番号 4 の倍数に来るので、この判定がそのまま楽譜上の 1・3 拍目になる。
    //   点滅予告は従来どおり爆破の 1 拍前（BLINK_LEAD）から。
    //   残留タイルを使い切れなくなるが、余りは区間末の bandEnd で消える（cfg.bandEnd）。
    //     区間② 拍 23〜31 … 発火は 24 / 26 / 28 / 30 の 4 回（v12 は 9 回）
    //     区間④ 拍 40〜47 … 発火は 40 / 42 / 44 / 46 の 4 回（v12 は 8 回）
    //   cfg.beatPhase を渡すと 1・3 拍目の代わりに任意の拍位置集合を使える（区間⑩⑭で使用）。
    // ======================================================================
    function blastPhase(cfg) {
      const pools = {};
      SIDE_ORDER.forEach(function (nm) { pools[nm] = []; });
      shuffled(cfg.tiles, rng).forEach(function (t) { pools[sideOf(t.col, t.row)].push(t); });

      // v13 (A3): 発火する拍位置（小節内 0 起点）。既定は 1 拍目と 3 拍目＝2 拍に 1 回。
      const beatPhase = cfg.beatPhase || [0, 2];

      // v13 (B): cfg.shots を渡すと拍グリッドではなく明示した拍番号（8 分＝小数可）で撃つ。
      //   [{ beat, n }] の配列。n は 1 回に爆破する枚数（省略時 BLAST_PER_BEAT）。
      //   区間⑩で「曲のアクセントに乗せる」ために使う。
      //   v19: beat の代わりに time（秒）を渡せるようにした。指示書のマーカーは拍グリッドに
      //   乗らないので、マーカー 15（45.0061s）の同時 4 枚爆破はこちらを使う。
      const shots = cfg.shots
        ? cfg.shots.map((sh) => ({ beat: sh.beat, time: sh.time, n: sh.n || BLAST_PER_BEAT }))
        : (function () {
            const out = [];
            for (let i = 0; i < cfg.len; i++) {
              const beatNo = cfg.firstBeat + i;
              if (beatPhase.indexOf(beatNo % 4) < 0) continue;  // v13: 2 拍に 1 回だけ爆破する
              out.push({ beat: beatNo, n: BLAST_PER_BEAT });
            }
            return out;
          })();

      let sideIdx = 0;
      for (let b = 0; b < shots.length; b++) {
        const blastTime = shots[b].time !== undefined ? shots[b].time : B(shots[b].beat);
        const youngest = blastTime - beats(BLAST_MIN_AGE) + 1e-6;
        const group = [];
        for (let n = 0; n < shots[b].n; n++) {
          let picked = null;
          for (let tryIdx = 0; tryIdx < SIDE_ORDER.length && picked === null; tryIdx++) {
            const pool = pools[SIDE_ORDER[(sideIdx + tryIdx) % SIDE_ORDER.length]];
            for (let m = 0; m < pool.length; m++) {
              if (pool[m].claimed || pool[m].strike > youngest) continue;
              picked = pool[m];
              break;
            }
            if (picked !== null) sideIdx = (sideIdx + tryIdx + 1) % SIDE_ORDER.length;
          }
          if (picked === null) break;
          picked.claimed = true;
          picked.end = blastTime;
          picked.lead = BLAST_LEAD_OUT;
          group.push(picked);
        }
        if (group.length === 0) continue;

        const cells = group.map((t) => [t.col, t.row]);
        s.at(
          blastTime - beats(0.5),
          tileField(cells, {
            type: 'warn_box',
            color: STONE_MID,
            appearTime: beats(0.5),
            appearDuration: beats(0.5),
            life: beats(0.5), // 爆破の瞬間ちょうどで消す（爆破中心に何も残さない）
            kind: 'blastwarn',
          })
        );
        s.at(blastTime - BLINK_LEAD, blinkWarn(cells, 'blastblink'));

        const centers = cells.map((c) => cellCenter(c[0], c[1]));
        centers.forEach(function (center) {
          s.at(blastTime, burst(center, b, cfg.burstMul || 1));
        });
      }
    }

    // ======================================================================
    // v10: 落下シャベルの対象タイルの選び方（区間⑤⑦）
    //   対象は「下側の帯（行 0..BAND-1。v11 では行 0〜1）にあるタイルのうち、その列でいちばん上にあるもの」。
    //   シャベルは画面上端から落ちるが、上側の帯のタイルは（衝突判定が無いので）貫通して
    //   通り過ぎ、この対象に当たった瞬間だけ爆破する。縦帯の予告は上端から対象タイルまで。
    //   4 回とも別の列にするため、16 列を 2 列ずつ 8 ゾーンに割って 1 ゾーン 1 列だけ選び、
    //   偶数ゾーンを区間⑤、奇数ゾーンを区間⑦へ振り分ける（どちらも左右に散る）。
    // ======================================================================
    function pickShovelTargets(tiles) {
      const topByCol = new Map();
      tiles.forEach(function (t) {
        if (t.claimed) return;      // 区間④で爆破済みのタイルは対象にしない
        if (t.row >= BAND) return;  // 下側の帯だけが対象
        const cur = topByCol.get(t.col);
        if (!cur || t.row > cur.row) topByCol.set(t.col, t);
      });

      const zones = [];
      for (let z = 0; z < 8; z++) zones.push([]);
      topByCol.forEach(function (t) { zones[Math.floor(t.col / 2)].push(t); });

      const first = [];   // 区間⑤
      const second = [];  // 区間⑦
      const usedCols = new Set();
      zones.forEach(function (pool, z) {
        if (pool.length === 0) return;
        const t = pool[Math.floor(rng() * pool.length)];
        usedCols.add(t.col);
        (z % 2 === 0 ? first : second).push(t);
      });
      // ゾーンが足りなかったときの補充（列は必ず別）
      const spare = shuffled(
        Array.from(topByCol.values()).filter((t) => !usedCols.has(t.col)),
        rng
      );
      [first, second].forEach(function (list) {
        while (list.length < 4 && spare.length > 0) {
          const t = spare.shift();
          usedCols.add(t.col);
          list.push(t);
        }
      });
      return shuffled(first, rng).slice(0, 4).concat(shuffled(second, rng).slice(0, 4));
    }

    // ======================================================================
    // 1. 6.629s → B(16)=6.667s  タイル表示①（7拍）
    // 2. 9.694s → B(23)=9.583s  タイル爆破①（9拍・毎拍2枚＝最大18枚）
    //    帯に残ったタイルは区間③の頭 B(32) で消える（v9 どおり）。
    // ======================================================================
    const bandA = tilePhase({
      firstBeat: S1_BEAT,
      len: S1_LEN,
      centerRate: CENTER_RATE,
      bandTarget: BAND_TARGET,
      bandEnd: B(S3_BEAT),
      pinStartGap: true,
    });
    blastPhase({ firstBeat: S2_BEAT, len: S2_LEN, tiles: bandA });
    emitBandTiles(bandA);

    // ======================================================================
    // 3. 13.380s → B(32)=13.333s  タイル表示②（8拍・rng の続き＝別配置）
    // 4. 16.783s → B(40)=16.667s  タイル爆破②（8拍・毎拍2枚＝最大16枚）
    //    帯に残ったタイルは区間⑧の末 B(80) まで消えず、⑤⑦の爆破対象と
    //    ⑥⑧のシャベル y 座標（行）の供給源になる。
    // ======================================================================

    // ⑤⑦のシャベル到達（＝爆破）時刻。2拍おきに4回。
    const S5_IMPACTS = [0, 2, 4, 6].map((k) => B(S5_BEAT + k));
    const S7_IMPACTS = [0, 2, 4, 6].map((k) => B(S7_BEAT + k));
    const IMPACTS = S5_IMPACTS.concat(S7_IMPACTS);

    const bandB = tilePhase({
      firstBeat: S3_BEAT,
      len: S3_LEN,
      centerRate: CENTER_RATE,
      bandTarget: BAND_TARGET,
      bandEnd: B(END_BEAT),
      pinStartGap: false,
    });
    blastPhase({ firstBeat: S4_BEAT, len: S4_LEN, tiles: bandB });

    // ⑤⑦で爆破する 8 枚（先頭4枚=⑤ / 後半4枚=⑦）を決め、到達時刻で消えるようにする。
    const shovelTiles = pickShovelTargets(bandB);
    shovelTiles.forEach(function (t, k) {
      t.claimed = true;
      t.end = IMPACTS[k];
      t.lead = BLAST_LEAD_OUT;
    });
    const shovelTargets = shovelTiles.map((t) => [t.col, t.row]);

    // 区間⑤〜⑧の間ずっと画面に残るタイル（⑥⑧の横断シャベルの行の供給源）
    // v14: 波の破壊判定より **前** に採る。ここを動かすと⑥⑧の行が変わってしまうため、
    //   v13 と同じ集合（＝爆破・落下シャベルで使われなかった帯タイル）を維持している。
    const heldCells = bandB.filter((t) => !t.claimed).map((t) => [t.col, t.row]);

    // ── v15: 33.333s の鎖が砕く残留タイルを確定させる ──────────────────────
    //   鎖が横に往復しながら通った先に残っているタイルは、鎖が重なった瞬間に life を尽きさせる。
    //   3 本の鎖はそれぞれ 1.53 ユニット幅を掃くので、掃かれない列に残ったタイルは
    //   鎖を生き延び、MK4_TILEWARN（35.9375s）でまとめて崩れる。
    //   emitBandTiles(bandB) より前に end を書き換える必要がある。
    const snakeBroken = [];
    // v27 (2): 手打ち 36.456（= 鎖の最終段が消える 36.4375）で画面のタイルが全部消えて
    //   しまうのをやめる。鎖 1 回目を生き延びたタイルは MK4_TILEWARN で崩さず
    //   **そのまま残し**、次の鎖（2 回目・MK11_CHAIN）が掃いた時に砕けるようにする。
    //   掃かれなかったぶんはマーカー 12（タイル予告開始 2 回目・42.4925s）で崩れる。
    //   emitBandTiles(bandB) はこの直後なので、消える時刻はここで確定させる必要がある。
    const bandBHeld = [];
    bandB.forEach(function (t) {
      if (t.claimed) return;
      const hit = snakeBreakTime(t.col, t.row, MK3_CHAIN, SNAKE_LANES);
      if (hit === null) {
        const hit2 = snakeBreakTime(t.col, t.row, MK11_CHAIN, SNAKE_LANES2);
        t.end = hit2 === null ? MK12_TILEWARN : hit2;
        if (hit2 !== null) t.lead = BLAST_LEAD_OUT;
        bandBHeld.push(t);
        return;
      }
      t.claimed = true;
      t.end = hit;
      t.lead = BLAST_LEAD_OUT;
      snakeBroken.push(t);
    });


    emitBandTiles(bandB);

    // ======================================================================
    // シャベル爆破区間（区間⑤⑦）
    //   画面上からシャベルを1本ずつ落とし、対象タイルの中心に到達した瞬間に
    //   ・シャベルの life が尽きる（＝タイルの位置で消える）
    //   ・タイルの life が尽きる（tiletarget クリップ側で設定済み）
    //   ・spinBurst が出る
    //   DSL/ランタイムに衝突判定は無いため、到達時刻を逆算して3つを同時刻に置いている。
    // ======================================================================
    function shovelBlastPhase(impacts, targets, spinBase, burstMul = 1) {
      impacts.forEach(function (impact, k) {
        const cell = targets[k];
        if (!cell) return;
        const center = cellCenter(cell[0], cell[1]);
        const flight = (SHOVEL_SPAWN_Y - center[1]) / SHOVEL_FALL_SPEED;
        // v5 (3): 発射の1拍前から、シャベルが通る列に縦帯（到達＝爆破で消える）。v7 で刃の幅ぶんに拡幅
        s.at(impact - flight - SWEEP_LEAD, dropPathWarn(center, SWEEP_LEAD + flight, 'droppathwarn'));
        // v5 (2): 爆破の1拍前から対象タイルを点滅させる
        s.at(impact - BLINK_LEAD, blinkWarn([cell], 'blastblink'));
        s.at(
          impact - flight,
          shovel({
            pos: [center[0], SHOVEL_SPAWN_Y],
            vel: [0, -SHOVEL_FALL_SPEED],
            angle: SHOVEL_ANGLE_DOWN,
            life: flight, // 到達＝タイルの位置でちょうど消える
            kind: 'shoveldrop',
          })
        );
        s.at(impact, burst(center, spinBase + k, burstMul));
      });
    }

    // 5. 20.001s → B(48)=20.000s  シャベル爆破①
    shovelBlastPhase(S5_IMPACTS, shovelTargets.slice(0, 4), 0);
    // 7. 26.591s → B(64)=26.667s  シャベル爆破②（残っているタイルから別の4枚）
    shovelBlastPhase(S7_IMPACTS, shovelTargets.slice(4, 8), 1);

    // ======================================================================
    // シャベル飛ばし区間（区間⑥⑧）
    //   先頭4拍、毎拍2本。左端→右 と 右端→左 を1本ずつ。
    //   y は残っているタイルの行の中心に合わせ、左右で必ず別の行にする。
    //   タイルに当たっても何も起こらず、画面を横切って外へ抜ける（life:0＝カリング任せ）。
    // ======================================================================
    const heldRows = Array.from(new Set(heldCells.map((c) => c[1]))).sort((a, b) => a - b);

    // v13 (B): 横断シャベル 1 組（左→右・右→左）を時刻 t に出す。区間⑥⑧⑪⑮で共有する。
    //   予告は v8 で全廃したまま（ユーザー評価「帯が邪魔」）。当たり判定は元から無い。
    function sweepPair(t, leftRow, rightRow) {
      if (leftRow !== null) {
        s.at(
          t,
          shovel({
            pos: [SHOVEL_LEFT_X, cellCenter(0, leftRow)[1]],
            vel: [SHOVEL_SIDE_SPEED, 0],
            angle: SHOVEL_ANGLE_RIGHT,
            life: 0,
            kind: 'shovelsweep',
          })
        );
      }
      if (rightRow !== null) {
        s.at(
          t,
          shovel({
            pos: [SHOVEL_RIGHT_X, cellCenter(0, rightRow)[1]],
            vel: [-SHOVEL_SIDE_SPEED, 0],
            angle: SHOVEL_ANGLE_LEFT,
            life: 0,
            kind: 'shovelsweep',
          })
        );
      }
    }

    function shovelSweepPhase(firstBeat, count = 4) {
      // v13 (A4): 速度を落としたぶん前の拍のシャベルが画面に残るので、直前の拍で使った行は
      //   候補から外す（候補が尽きたときだけ全行に戻す）。同じ行で追いかけっこにならない。
      let prevRows = [];
      for (let i = 0; i < count; i++) {
        const t = B(firstBeat + i);
        if (heldRows.length === 0) continue;
        let pool = heldRows.filter((r) => prevRows.indexOf(r) < 0);
        if (pool.length < 2) pool = heldRows;
        const leftRow = pool[Math.floor(rng() * pool.length)];
        const others = pool.filter((r) => r !== leftRow);
        const rightRow = others.length > 0 ? others[Math.floor(rng() * others.length)] : leftRow;
        prevRows = [leftRow, rightRow];

        // v8 (1): 横断シャベルの経路予告（横帯 + 方向マーク）は削除した。
        //   v5(4)〜v7 では通る行に横一杯の PINK_PATH の帯と、来る側の端に PINK_MARK の
        //   方向マークを出していたが、ユーザー評価で「帯が邪魔」となったため全部外す。
        //   落下シャベル（区間⑤⑦）の縦帯 dropPathWarn と、爆破対象タイルの点滅 blinkWarn は
        //   そのまま残している。シャベル本体（下の2本）の配置・時刻・サイズは v4 のまま不変。
        sweepPair(t, leftRow, rightRow);
      }
    }

    // 6. 23.189s → B(56)=23.333s  シャベル飛ばし①
    shovelSweepPhase(S6_BEAT);
    // 8. 30.161s → B(72)=30.000s  シャベル飛ばし②
    shovelSweepPhase(S8_BEAT);

    // ======================================================================
    // ★ v13 (B) 延長: 区間⑨〜⑯（33.333s → 60.000s・小節 21〜36 の 16 小節）
    //
    //   解析: Instructions/石工/stone3_section_analysis_20260903.md
    //   この範囲は 8 小節周期のループで、周期の内訳は
    //     1〜4 小節目 = 主リフ（低域が毎拍鳴る。4 小節目に 8 分のフィル）
    //     5〜6 小節目 = 休符（低域が抜ける。フラックス最小）
    //     7〜8 小節目 = ビルドアップ（高域が上がり、8 小節目が最も密）
    //   これを 2 周ぶん（小節 21〜28 / 29〜36）そのまま構成に写した。次の本当の
    //   セクション境界は 60.000s（中域が 7.3 → 10.9 に跳ねる）なのでそこで終える。
    //
    //   新要素は入れていない。既存モチーフの変奏だけ:
    //     ・タイルの帯を「上下だけ」（⑨）と「左右だけ」（⑬）に変える
    //     ・爆破を曲のアクセント（8 分位置を含む）に乗せる（⑩⑭）
    //     ・落下シャベルを 2 本同時にする（⑫⑯）
    //     ・横断シャベルを行ずらしで往復させる（⑮）
    //     ・放射弾の数を盛り上がりで増やす（⑯だけ 1.3 倍）
    //     ・休符の小節（⑪⑮）では新規タイルも爆破も出さない
    // ======================================================================

    // v13 (B): 落下シャベルの対象を選ぶ汎用版（区間⑤⑦の pickShovelTargets の一般化）。
    //   区間⑤⑦は「下側の帯にあるタイル」に限っていたが、延長では帯が上下だけ／左右だけに
    //   変わるので下側の在庫が足りない（easy で 1 本しか出せない事象を実測した）。
    //   ここでは行の制限をやめ、**その列で最も上にあるタイル**を対象にする。上から落ちる
    //   シャベルが最初にぶつかる 1 枚なので、貫通が一切起きない点ではむしろ正しい。
    //   16 列を count 個のゾーンに割って 1 ゾーン 1 列だけ選ぶ（左右に散らす・列は必ず別）。
    //   usedCols は呼び出し側で持ち回り、同じ区間の中では同じ列を使わない。
    function pickDropTargets(tiles, count, usedCols) {
      const topByCol = new Map();
      tiles.forEach(function (t) {
        if (t.claimed || usedCols.has(t.col)) return;
        const cur = topByCol.get(t.col);
        if (!cur || t.row > cur.row) topByCol.set(t.col, t);
      });
      // 落下距離が長いほうが見栄えするので、下側の帯（行 0..BAND-1）にある列を先に使い、
      // 足りないぶんだけ上側の列で補う。
      const low = [], high = [];
      topByCol.forEach(function (t) { (t.row < BAND ? low : high).push(t); });
      const out = [];
      [low, high].forEach(function (group) {
        if (out.length >= count) return;
        const zones = [];
        for (let z = 0; z < count; z++) zones.push([]);
        group.forEach(function (t) {
          zones[Math.min(count - 1, Math.floor((t.col * count) / COLS))].push(t);
        });
        zones.forEach(function (pool) {
          if (out.length >= count || pool.length === 0) return;
          const cand = pool.filter((t) => !usedCols.has(t.col));
          if (cand.length === 0) return;
          const t = cand[Math.floor(rng() * cand.length)];
          usedCols.add(t.col);
          out.push(t);
        });
        const spare = shuffled(group.filter((t) => !usedCols.has(t.col)), rng);
        while (out.length < count && spare.length > 0) {
          const t = spare.shift();
          usedCols.add(t.col);
          out.push(t);
        }
      });
      return out.slice(0, count);
    }

    // 落下シャベルの対象タイルに到達時刻を書き込むヘルパ（区間⑤⑦と同じ扱い）。
    function claimDropTargets(tiles, impacts) {
      tiles.forEach(function (t, k) {
        t.claimed = true;
        t.end = impacts[k];
        t.lead = BLAST_LEAD_OUT;
      });
      return tiles.map((t) => [t.col, t.row]);
    }

    // ----------------------------------------------------------------------
    // ★ v17 ⑨' 33.396〜39.172s — 予告2連 → 下から上へ這う鎖 → タイル出現 4 回
    //   （指示書 Instructions/石工/stage-timing-instructions_20260903_chain.md の 8 マーカー。
    //    採用時刻の根拠は MK1_WARN1 付近の表を参照）
    //
    //   v14 の「画面幅のサイン波前線 2 本を上から下へ」は参考動画の読み違いだったので、
    //   ここだけ作り直した。区間①〜⑧（〜33.3s）と区間⑩以降（36.667s〜）は不変。
    //   拍 77/79/80 は区間⑧（拍 72-79）の中に入るが、⑧が弾を出しているのは拍 72-75
    //   （横断シャベル 4 拍ぶん）だけで拍 76-79 は空いているため、区間⑧の内容には
    //   一切触れていない（追加した予告は当たり判定のない warn_box）。
    //
    //   (a) 予告①（33.3961s / マーカー1）… 鎖が掃く幅の縦帯を、画面の下から上まで通しで。
    //       色は最暗の STONE_PATH。予告②まで出しっぱなし。
    //   (b) 予告②（33.6573s / マーカー2）… 同じ帯を STONE_WARN で濃くする。攻撃の瞬間に消える。
    //   (c) 攻撃（34.3750s / マーカー3）… 鎖 3 本が下から生える。
    //       v17: 段の間隔を鎖の 1 辺（1.15 ユニット）にして **段どうしが接する** ようにし、
    //       段数を 9 → 16 に増やした。1 段 0.09375s（16 段 = 1.500s で画面高を縦断）。
    //       同時に見えるのは 7 段（参考の全長 7〜8 枚）。段ごとに 60 度ずれた横揺れ
    //       （周期 1 拍・振幅 0.83 段 = 0.95 ユニット）で蛇行する。
    //       最後の段が消えるのは 34.375 + (15 + 7) × 0.09375 = 36.44s。
    //       鎖が重なった残留タイルはその瞬間に砕け（snakeBroken）、
    //       うち最大 SNAKE_BURSTS 枚から放射弾が出る。
    //   (d) 残タイル崩落（35.9375s / マーカー4）… 鎖に掃かれなかったタイルが崩れる
    //       （bandB の end。上の「鎖の破壊判定」で設定済み）。ここからタイルの予告が出始める。
    //   (e) タイル出現 4 回（36.8750 / 37.5000 / 38.3420 / 39.1721s / マーカー5-8）…
    //       区間①と同じ出現ポップ。予告は各タイルの実体化まで継続的に見せる
    //       （①はマーカー4 から、②〜④は前のタイルの実体化直後から＝REFILL_LEADS）。
    //       帯は v13 の区間⑨と同じ「上下だけ」で、候補の順番だけ「鎖で砕けたセルと
    //       その 4 近傍」を先頭に寄せてある。中央（12x5）にもタイルが出て、次のタイルで消える。
    //       ここで積んだ帯が v13 の bandC の役割をそのまま引き継ぐので、区間⑪以降は不変。
    // ----------------------------------------------------------------------
    // v13 (B): 延長では「上下の帯」と「左右の帯」が同時に画面へ乗る（⑬以降）ので、
    //   1 枚あたりの目標埋まり率を区間①③の 0.62 倍に下げてある。区間①③は外周ぐるり
    //   84 セルを D(0.50,0.64,0.72) まで埋めていたが、延長は 上下 64 + 左右 36（うち角 16 は
    //   重複）で、同じ率だと自機の通路（空きセルの 4 近傍連結）が確保できず
    //   emptyIsConnected が全候補を弾いてしまう（lunatic で区間⑬が 0 枚になる不具合を実測）。
    const EXT_BAND_TARGET = D(0.31, 0.40, 0.45);

    // (a)(b) v27 (1): 予告を 2 組に分け、8 分ずらして出す（外側 2 本 → 中央 1 本）。
    //   攻撃（鎖の出現）は 34.3750 に揃えたまま＝「予告① → 予告② → まとめて攻撃」。
    emitSplitWarn(SNAKE_LANES, V27_C1_WARN_A, V27_C1_WARN_B, MK3_CHAIN);

    // (c) 鎖 3 本。1 段 = 弾 1 発（v2 レーンの折れ線）＋出現フラッシュ 1 発。
    //     v17: 段の間隔 1.15 ユニット（隙間なく接する）× 16 段 × 0.09375s = 1.500s で縦断。
    const SNAKE_T0 = MK3_CHAIN;
    SNAKE_LANES.forEach(function (lane) {
      for (let k = 0; k < SNAKE_STEPS; k++) {
        const at = snakeRowWindow(SNAKE_T0, k)[0];
        s.at(at, snakeTile(SNAKE_T0, k, lane));
        s.at(at, snakePop(SNAKE_T0, k, lane));
      }
    });

    // (c) 砕けたタイルからの放射弾。全部に付けると弾が溢れるので、列でばらけるように
    //     等間隔で間引いて最大 SNAKE_BURSTS 枚だけにする。弾数は通常の爆破の半分。
    const brokenSorted = snakeBroken.slice().sort(function (a, b) {
      return a.col - b.col || a.row - b.row;
    });
    if (brokenSorted.length > 0) {
      const step = Math.max(1, Math.ceil(brokenSorted.length / SNAKE_BURSTS));
      for (let i = 0, k = 0; i < brokenSorted.length; i += step, k++) {
        const t = brokenSorted[i];
        const center = cellCenter(t.col, t.row);
        s.at(t.end, burst(center, k, 0.5));
      }
    }


    // (e) 補充（4 拍）。鎖で砕けたセルとその 4 近傍を優先して積み直す。
    const refillPriority = new Set();
    snakeBroken.forEach(function (t) {
      refillPriority.add(key(t.col, t.row));
      for (let d = 0; d < 4; d++) {
        const nc = t.col + NEIGHBOR_DC[d];
        const nr = t.row + NEIGHBOR_DR[d];
        if (nc < 0 || nc >= COLS || nr < 0 || nr >= ROWS) continue;
        refillPriority.add(key(nc, nr));
      }
    });

    // v27 (2): 鎖 1 を生き延びて画面に残っているタイルのセル。補充（bandC）は
    //   ここを避けて積む（重ね置きの防止と、自機の通路を残す連結判定のため）。
    const heldKeys = new Set(bandBHeld.map(function (t) { return key(t.col, t.row); }));
    const bandC = tilePhase({
      preBlocked: heldKeys,
      times: REFILL_TIMES,
      leads: REFILL_LEADS,
      centerRate: CENTER_RATE,
      bandTarget: EXT_BAND_TARGET,
      bandCells: BAND_CELLS_TB,
      bandEnd: B(EXT_END_BEAT),
      priority: refillPriority,
      pinStartGap: false,
    });

    // ----------------------------------------------------------------------
    // ⑩ 小節23-24 / 36.667s / 拍 88-95 — タイル爆破③（曲のアクセントに乗せる）
    //   小節23 の強拍は 1 拍目(258)・2 拍裏(361)・4 拍目(602) → 1 拍目と 4 拍目を採る。
    //   小節24 は 8 分のフィルで 1 拍裏(655) が最大 → 1 拍裏と 4 拍目(405) を採る。
    //   区間②④と同じ「1 回 2 枚」なので密度は同じ（4 回 × 2 枚）。
    // ----------------------------------------------------------------------
    //   v17: 指示書のタイル①〜④（36.875〜39.172s）と重なる 3 発
    //   （36.667 / 37.917 / 38.542s）は削除した。タイルが出るそばから爆破していては
    //   指示書の「4 回のタイル出現」が見えないため。マーカー⑧（39.172s）より後の
    //   39.583s の 1 発だけを残し、40.0s 以降の区間⑪〜⑯は v13b のまま。
    blastPhase({
      tiles: bandC,
      shots: [
        { beat: S10_BEAT + 7 },      // 39.583s 小節24 4拍目
      ],
    });

    // ======================================================================
    // ★ v19  40.008〜50.833s — 指示書のマーカー 9〜17
    //   鎖攻撃 2 回目 → タイル①② → 同時 4 枚爆破 → 鎖攻撃 3 回目 → タイル攻撃 2 回目。
    //   採用時刻とその根拠はファイル冒頭の v19 の表。
    //   ここにあった v13b 由来の仮区間は、40.0〜51.9s が丸ごと重なるので削除した:
    //     ⑪ 40.000 / 42.500s の横断シャベル 2 本（鎖 2 回目と重なる）
    //     ⑫ 43.333 / 45.000 / 46.458s の落下シャベル 5 本（タイル①②・4 枚爆破・鎖 3 回目と重なる）
    //     ⑬ 46.667〜49.583s のタイル表示④ 8 拍（鎖 3 回目・タイル攻撃 2 回目と重なる）
    //     ⑭ 50.625 / 51.250 / 51.875s の爆破④ 3 回（指示書の「その後は静止」と噛み合わない）
    //   50.833s より後の仮区間⑮（53.333s〜）⑯（56.667s〜）はそのまま残し、
    //   対象タイルの供給源だけ新しい帯（bandC / bandD / bandE）へ差し替えている。
    // ======================================================================

    // 鎖攻撃 1 回分をまとめて出すヘルパ。1 回目（33.4〜36.4s・SNAKE_LANES）と同じ構造で、
    //   予告①（薄い縦帯）→ 予告②（同じ帯を濃く）→ 鎖 3 本（16 段 × 0.09375s = 1.500s で
    //   下から上へ縦断）→ 掃かれた残留タイルの破壊 → 砕けたタイルからの放射弾
    // を、中心列（lanes）と時刻だけ変えて出す。戻り値は砕けたタイルの一覧。
    // v27 (1)(4)(6)(8): 鎖の予告を 2 組に分けて 8 分ずらして出す。
    //   組 A = 外側の 2 本（lanes[0], lanes[2]）／組 B = 中央の 1 本（lanes[1]）。
    //   どちらの組も「薄い STONE_PATH → 8 分後に濃い STONE_WARN」で、濃い予告は
    //   攻撃の瞬間まで出しっぱなし。攻撃（鎖の出現）は 1 回にまとめる。
    function emitSplitWarn(lanes, tA, tB, tAttack) {
      const half = beats(0.5);
      const groupA = lanes.filter(function (_, i) { return i !== 1; });
      const groupB = lanes.filter(function (_, i) { return i === 1; });
      [[groupA, tA], [groupB, tB]].forEach(function (g) {
        if (g[0].length === 0) return;
        s.at(g[1], snakeWarn(g[0], STONE_PATH, half, 'snakewarn1'));
        s.at(g[1] + half, snakeWarn(g[0], STONE_WARN, tAttack - (g[1] + half), 'snakewarn2'));
      });
    }

    function chainAttack(warnA, warnB, t0, lanes, tiles) {
      emitSplitWarn(lanes, warnA, warnB, t0);
      lanes.forEach(function (lane) {
        for (let k = 0; k < SNAKE_STEPS; k++) {
          const at = snakeRowWindow(t0, k)[0];
          s.at(at, snakeTile(t0, k, lane));
          s.at(at, snakePop(t0, k, lane));
        }
      });
      const broken = [];
      tiles.forEach(function (t) {
        if (t.claimed) return;
        const hit = snakeBreakTime(t.col, t.row, t0, lanes);
        if (hit === null) return;   // 掃かれなかったタイルはそのまま残す
        t.claimed = true;
        t.end = hit;
        t.lead = BLAST_LEAD_OUT;
        broken.push(t);
      });
      // 放射弾は全部には付けない（弾が溢れる）。列でばらけるよう等間隔に間引いて
      // 最大 SNAKE_BURSTS 枚だけ、弾数も通常の爆破の半分にする（1 回目と同じ扱い）。
      const sorted = broken.slice().sort(function (a, b) {
        return a.col - b.col || a.row - b.row;
      });
      if (sorted.length > 0) {
        const step = Math.max(1, Math.ceil(sorted.length / SNAKE_BURSTS));
        for (let i = 0, k = 0; i < sorted.length; i += step, k++) {
          const t = sorted[i];
          s.at(t.end, burst(cellCenter(t.col, t.row), k, 0.5));
        }
      }
      return broken;
    }

    // ----------------------------------------------------------------------
    // マーカー 9-11: 鎖攻撃 2 回目（予告① 40.008 / 予告② 40.417 / 攻撃 41.262s）
    //   中心列は 4 / 9 / 14。1 回目（2 / 7 / 12）から 2 列ずらしてあるので、
    //   1 回目を生き延びて残っている上下の帯（bandC）のセルにも破壊が起きる。
    //   掃かれなかったタイルはそのまま画面に残り、マーカー 15 の爆破対象になる。
    // ----------------------------------------------------------------------
    // v27 (4): 予告 40.1995 / 40.4078（手打ち 40.249）。攻撃は 41.2386 のまま。
    //   対象には bandC に加えて「鎖 1 を生き延びて残っているタイル」も渡す
    //   （消える時刻は emitBandTiles(bandB) の前に同じ式で確定済み）。
    chainAttack(V27_C2_WARN_A, V27_C2_WARN_B, MK11_CHAIN, SNAKE_LANES2, bandC.concat(bandBHeld));

    // ----------------------------------------------------------------------
    // マーカー 12-14: 予告表示（42.510s）→ タイル①（43.346s）→ タイル②（43.967s）
    //   マーカー 4-8 と同じ出現ポップ。積む先は **左右の帯**（列 0-1 / 14-15）にして、
    //   上下（bandC の残り）と合わせて外周の 4 辺が揃うようにする（マーカー 15 の前提）。
    //   予告は「前のイベントから実体化まで出しっぱなし」＝ TILE2_LEADS。
    //   上下の帯は既に画面にあるので preBlocked に渡し、連結判定（自機が閉じ込められない）
    //   を上下＋左右の合計で行う。中央（12x5）にも一時タイルが出て次のタイルで消える。
    // ----------------------------------------------------------------------
    const aliveC = new Set(bandC.filter((t) => !t.claimed).map((t) => key(t.col, t.row)));
    // v27 (2): マーカー 13/14 の時点でまだ残っている bandB のタイルも避ける
    bandBHeld.forEach(function (t) { if (t.end > MK13_TILE1) aliveC.add(key(t.col, t.row)); });
    const bandD = tilePhase({
      times: TILE2_TIMES,
      leads: TILE2_LEADS,
      centerRate: CENTER_RATE,
      bandTarget: EXT_BAND_TARGET,
      bandCells: BAND_CELLS_LR,
      preBlocked: aliveC,
      bandEnd: B(EXT_END_BEAT),
      pinStartGap: false,
    });

    // ----------------------------------------------------------------------
    // マーカー 15: タイル爆破 x4（45.006s に 4 枚同時）
    //   blastPhase の 4 辺めぐり（左 → 上 → 右 → 下）で 1 枚ずつ選ぶので、
    //   4 枚は必ず帯の左右上下に散る。在庫は上下＝bandC・左右＝bandD。
    //   1 拍前から対象が点滅（blinkWarn）、半拍前に薄い予告とリング予告、
    //   45.006s ちょうどでタイルの life が尽き、同時に放射弾が 4 箇所から出る。
    // ----------------------------------------------------------------------
    // v27 (5): 手打ち「拍に合わせて 4 回、ずらして爆破（4 回目が 46.3 付近）」に合わせ、
    //   同時 4 枚 → 1 拍ごとに 1 枚ずつ 4 回（44.9887 / 45.4054 / 45.8220 / 46.2387）。
    blastPhase({
      tiles: bandC.concat(bandD),
      shots: V27_BLAST4_TIMES.map(function (t) { return { time: t, n: 1 }; }),
    });

    // ----------------------------------------------------------------------
    // マーカー 16: 鎖攻撃 3 回目（予告① 47.299 / 予告② 47.508 / 攻撃 48.344s）
    //   中心列は 1 / 6 / 11。1 回目・2 回目のどちらとも重ならない位置で、
    //   左端の列 0-1（bandD の左の帯）も掃く。対象は上下＋左右の残り全部。
    // ----------------------------------------------------------------------
    // v27 (6): 予告 46.8056 / 47.0139（手打ち 46.889）。攻撃 48.1176 は据え置き。
    const brokenD = chainAttack(
      V27_C3_WARN_A, V27_C3_WARN_B, MK16_CHAIN, SNAKE_LANES3, bandC.concat(bandD)
    );

    // ----------------------------------------------------------------------
    // マーカー 17: タイル攻撃 2 回目（予告開始 49.375 → ① 50.208 → ② 50.833s）
    //   マーカー 5-8 の補充と同じ作りで、3 回目の鎖で砕けたセルとその 4 近傍を
    //   優先して外周へ積み直す。積む先は外周ぐるり（BAND_CELLS）。
    //   50.833s から仮区間⑮（53.333s）までは新規の弾を出さない＝静止。
    // ----------------------------------------------------------------------
    const refill3Priority = new Set();
    brokenD.forEach(function (t) {
      refill3Priority.add(key(t.col, t.row));
      for (let d = 0; d < 4; d++) {
        const nc = t.col + NEIGHBOR_DC[d];
        const nr = t.row + NEIGHBOR_DR[d];
        if (nc < 0 || nc >= COLS || nr < 0 || nr >= ROWS) continue;
        refill3Priority.add(key(nc, nr));
      }
    });
    const aliveCD = new Set(
      bandC.concat(bandD).filter((t) => !t.claimed).map((t) => key(t.col, t.row))
    );
    const bandE = tilePhase({
      times: TILE3_TIMES,
      leads: TILE3_LEADS,
      centerRate: CENTER_RATE,
      bandTarget: EXT_BAND_TARGET,
      bandCells: BAND_CELLS,
      preBlocked: aliveCD,
      priority: refill3Priority,
      bandEnd: B(EXT_END_BEAT),
      pinStartGap: false,
    });

    // ----------------------------------------------------------------------
    // ★ v27 (7) 51.5483 / 51.9314s — 指示書「タイル爆破 x4」「ここにもタイル攻撃」
    //   「ここで 4 つくらいタイル爆破」
    //   v19 では マーカー 17（50.6137s）から仮区間⑮（53.333s）まで新規の弾が無かった。
    //   そこへ 2 回の爆破と 1 回のタイル攻撃を足す。
    //     51.5483s … 在庫（bandC/D/E の残り）から 4 枚同時に爆破し、**同じ時刻に**
    //                外周へタイルを積み直す（＝爆破で空いた場所へ次のタイルが来る）。
    //     51.9314s … さらに 4 枚爆破（1 拍あと）。
    //   爆破は blastPhase の 4 辺めぐりなので 4 枚は必ず左右上下に散る。
    // ----------------------------------------------------------------------
    const bandCDE = bandC.concat(bandD).concat(bandE);
    blastPhase({ tiles: bandCDE, shots: [{ time: V27_BLAST_A, n: 4 }] });

    const aliveCDE = new Set(
      bandCDE.filter(function (t) { return !t.claimed; }).map(function (t) { return key(t.col, t.row); })
    );
    // v27 (C): 追加指示書の「51.265 タイル表示」に合わせて 51.5483 → 51.2348 へ前倒しし、
    //   この帯は 65.1s の鎖攻撃まで使うので寿命を V27C_BAND_END（66.0s）まで延ばす。
    //   埋まり方も外周ぐるりの本来の目標値（BAND_TARGET）に戻す。
    const bandH = tilePhase({
      times: [V27C_TILE_SHOW],
      leads: [beats(1)],
      centerRate: CENTER_RATE,
      bandTarget: BAND_TARGET,
      bandCells: BAND_CELLS,
      preBlocked: aliveCDE,
      bandEnd: V27C_BAND_END,
      pinStartGap: false,
    });

    // v27 (C): 「51.927 いくつか爆破」。v27(A) の 51.9314 を採用オンセット 51.8618 へ寄せた。
    blastPhase({ tiles: bandCDE.concat(bandH), shots: [{ time: V27C_BLAST2, n: 4 }] });

    // ======================================================================
    // ★ v27 (C)  53.22〜65.01s — 追加指示書 gap51-65（13 マーカー）
    //   ここは v19 まで「休符＋仮区間⑮⑯」で攻撃が薄かった。ユーザー指示に合わせて
    //   横から入るシャベル → 上から降って溜まるシャベル → 発射 → 上 2 列の落下 → 鎖 2 回
    //   という一続きの構成に置き換えた（⑮の横断シャベル往復・⑯の落下シャベル 5 本、
    //   および v27(A) の (8) 鎖 4 回目と 55.8266 のタイル攻撃は削除）。
    // ======================================================================

    // --- 53.22〜56.66s: 横から縦並びで入るシャベル -------------------------------
    //   (1) 画面外から ease out（等減速）で入り、右 2 列に被らない x で速度 0
    //   (2) すこし逆向き（右グループなら右）へ曲がる＝ため
    //   (3) 加速して反対の壁へ飛び、指定時刻ちょうどに着弾。タイルは壊さない
    function sideShovelSet(tIn, tBend, tDive, tHit, fromX, stopX, bendSign, hitX, angle) {
      const dA = tBend - tIn;
      const dB = tDive - tBend;
      const dC = tHit - tDive;
      const v0 = (2 * (stopX - fromX)) / dA;          // ease out の初速
      const aA = -v0 / dA;                             // 終端で速度 0 になる等減速
      const aB = (bendSign * 2 * V27C_SIDE_BEND_D) / (dB * dB);
      const xB = stopX + bendSign * V27C_SIDE_BEND_D;  // ため終わりの x
      const vB = aB * dB;
      const aC = (2 * (hitX - xB - vB * dC)) / (dC * dC);
      V27C_SIDE_YS.forEach(function (y) {
        s.at(tIn, shovelPath([fromX, y], [v0, 0], [
          { dur: dA, ax: aA, ay: 0 },
          { dur: dB, ax: aB, ay: 0 },
          { dur: dC, ax: aC, ay: 0 },
        ], angle, 'sideshovel'));
        // v29 (7): 指示 56.673「シャベルの着弾エフェクトは要らないです」→ 着弾リングを削除。
      });
    }

    // 右から入って左の壁へ（54.8513 に着弾）
    sideShovelSet(
      V27C_SIDE_IN, V27C_SIDE_BEND, V27C_SIDE_DIVE, V27C_SIDE_HIT_L,
      SHOVEL_RIGHT_X, V27C_SIDE_STOP_R, +1, SHOVEL_SCALE / 2, SHOVEL_ANGLE_LEFT
    );
    // 左から入って右の壁へ（56.6567 に着弾）。時刻の刻みは右のときと同じ比率で写す。
    sideShovelSet(
      V27C_SIDE_HIT_L,
      V27C_SIDE_HIT_L + (V27C_SIDE_BEND - V27C_SIDE_IN),
      V27C_SIDE_HIT_L + (V27C_SIDE_DIVE - V27C_SIDE_IN),
      V27C_SIDE_HIT_R,
      SHOVEL_LEFT_X, V27C_SIDE_STOP_L, -1, COLS * CELL - SHOVEL_SCALE / 2, SHOVEL_ANGLE_RIGHT
    );

    // --- 56.66〜58.74s: 上から降って上 2 列の下側に溜まる 6 本 ---------------------
    //   1 拍ずつずらして落ち、着地でバウンドし、そのあと小さく左右へ揺れて待つ。
    //   （「バウンドさせてゆらゆら」の解釈: 反発係数 0.25/0.30/0.45/0.50 の 4 回バウンド →
    //     周期 0.6 秒・振幅 0.45 ユニットの横揺れ。発射時刻ちょうどに揺れを止める）
    const V27C_FALL_A = (2 * (SHOVEL_SPAWN_Y - V27C_DROP_REST_Y)) / (V27C_DROP_FALL * V27C_DROP_FALL);
    V27C_DROP_TIMES.forEach(function (land, k) {
      const x = V27C_DROP_XS[k];
      const vLand = V27C_FALL_A * V27C_DROP_FALL;      // 着地時の落下速度
      const segs = [{ dur: V27C_DROP_FALL, ax: 0, ay: -V27C_FALL_A }];
      let up = vLand;
      let used = 0;
      V27C_BOUNCE.forEach(function (e) {
        up *= e;
        const d = (2 * up) / V27C_FALL_A;
        // 上向きの初速 up から重力で落ちて、同じ高さへ戻る 1 バウンド
        segs.push({ dur: d, ax: 0, ay: -V27C_FALL_A, vy: up });
        used += d;
      });
      // 残りの待ち時間を「ゆらゆら」に割る（半周期 V27C_SWAY_HALF ごとに向きが返る）
      const fireDur = V27C_FIRE_HIT - V27C_FIRE;
      const hold = V27C_FIRE - land - used;
      const nSway = Math.max(1, Math.round(hold / V27C_SWAY_HALF));
      const swayDur = hold / nSway;
      const swayV = V27C_SWAY_V * Math.min(1, swayDur / V27C_SWAY_HALF);
      for (let i = 0; i < nSway; i++) {
        // v29 (7): 揺れは縦方向（バウンドの流れをそのまま小さく続ける）
        const sg = { dur: swayDur, ax: 0, ay: (i % 2 === 0 ? -2 : 2) * swayV / swayDur };
        if (i === 0) { sg.vx = 0; sg.vy = swayV; }   // 揺れの入り口で横の速度を止める
        segs.push(sg);
      }
      // 発射（等速で真下へ。V27C_FIRE_HIT ちょうどに最下段へ着く）
      segs.push({
        dur: fireDur, ax: 0, ay: 0,
        vx: 0, vy: -(V27C_DROP_REST_Y - METEOR_DROP_Y) / fireDur,
      });
      s.at(land - V27C_DROP_FALL, shovelPath([x, SHOVEL_SPAWN_Y], [0, 0], segs, SHOVEL_ANGLE_DOWN, 'dropshovel'));
      // 着弾の放射弾（下側の列のタイル破壊と同時）
      s.at(V27C_FIRE_HIT, burst([x, METEOR_DROP_Y], k, 1.0));
      // v29 (7): 着弾エフェクト（リング）を削除。タイル破壊と同時の放射弾は残す。
    });

    // --- 59.9946: 下側の列（行 0-1）のタイルを破壊 --------------------------------
    const bandAll = bandCDE.concat(bandH);
    bandAll.forEach(function (t) {
      if (t.claimed) return;
      if (t.row >= BAND) return;
      t.claimed = true;
      t.end = V27C_FIRE_HIT;
      t.lead = BLAST_LEAD_OUT;
    });

    // --- 61.2368: 上 2 列（行 7-8）のタイルが点滅 ---------------------------------
    const topTiles = bandAll.filter(function (t) { return !t.claimed && t.row >= ROWS - BAND; });
    if (topTiles.length > 0) {
      s.at(V27C_BLINK, blinkWarn(topTiles.map(function (t) { return [t.col, t.row]; }), 'blastblink'));
    }

    // --- 63.3266: 上 2 列が重力で落下し、下の空いた行へ積み重なる -------------------
    //   「いい感じに積み重なる」の解釈: 列ごとに、下の行から順に空いているところへ落とす。
    //   59.9946 で行 0-1 を空けてあるので、行 7 のタイルが行 0、行 8 のタイルが行 1 へ入る。
    //   下に入るぶんを先に着地させたいので、上のタイルは 1 コマぶん遅らせて出す。
    const stackByCol = new Map();
    topTiles.slice().sort(function (a, b) { return a.col - b.col || a.row - b.row; })
      .forEach(function (t) {
        if (!stackByCol.has(t.col)) stackByCol.set(t.col, []);
        stackByCol.get(t.col).push(t);
      });
    const stacked = [];
    stackByCol.forEach(function (list, col) {
      list.forEach(function (t, i) {
        t.claimed = true;
        t.end = V27C_FALL;          // 実体タイルはここで終わり、落下する弾へバトンタッチ
        t.lead = 0;
        const from = cellCenter(t.col, t.row);
        const dstRow = i;            // 行 0 → 行 1 の順に積む
        const to = cellCenter(t.col, dstRow);
        const dist = from[1] - to[1];
        const dur = Math.sqrt((2 * dist) / V27C_STACK_ACCEL);
        const delay = i * 0.08;      // 下に入るぶんを先に着地させる
        stacked.push({ col: t.col, row: dstRow, land: V27C_FALL + delay + dur, from: from, to: to, dur: dur, delay: delay });
      });
    });

    // --- 63.8723: 左右の 2 列を鎖攻撃で破壊 ---------------------------------------
    const V27C_LANES_LR = [{ col: 1, phase: 0 }, { col: 14, phase: Math.PI }];
    chainAttackG(
      CHAIN_V_FAST, V27C_CHAIN_LR - 0.52, V27C_CHAIN_LR - 0.21, V27C_CHAIN_LR,
      V27C_LANES_LR, bandAll, true   // v29 (5): 指示 66.892「タイル破壊の弾はいらない」
    );

    // --- 65.0101: 下の列を鎖攻撃で破壊（ついでに上の列にも置く）----------------------
    const V27C_LANES_TB = [{ row: 1, phase: 0 }, { row: 7, phase: Math.PI }];
    chainAttackG(
      CHAIN_H, V27C_CHAIN_B - 0.40, V27C_CHAIN_B - 0.16, V27C_CHAIN_B,
      V27C_LANES_TB, bandAll, true   // v29 (5): 同上（65.0〜65.9s の放射弾）
    );

    // 落下して積み上がったタイルの実体。下の鎖が通った瞬間に砕ける（通らなければ 66.0s）。
    stacked.forEach(function (st, i) {
      const hit = chainBreakTime(CHAIN_H, st.col, st.row, V27C_CHAIN_B, V27C_LANES_TB);
      const end = hit === null ? V27C_BAND_END : hit;
      // (1) 落下（等加速。着地でぴたりと止まる）
      s.at(V27C_FALL + st.delay, {
        parts: [{
          offsetSec: 0,
          kind: 'stackfall',
          buffer: {
            bullets: [bulletDefaults({
              originPos: { x: normalizeNegativeZero(st.from[0]), y: normalizeNegativeZero(st.from[1]) },
              originVlc: { x: 0, y: 0 },
              gravity: { x: V27C_STACK_ACCEL, y: normalizeNegativeZero(-Math.PI / 2) },
              typeName: 'stone3_tile',
              scale: { x: TILE, y: TILE },
              color: { x: SPRITE_AS_IS[0], y: SPRITE_AS_IS[1], z: SPRITE_AS_IS[2], w: SPRITE_AS_IS[3] },
              life: st.dur + METEOR_LIFE_MARGIN,
              unCounterable: true,
            })],
            homing: false,
            isLaser: false,
          },
          spawner: NEUTRAL_SPAWNER(),
        }],
      });
      // (2) 着地後は静止したタイル
      if (end > st.land) {
        s.at(st.land, tileField([[st.col, st.row]], {
          type: 'stone3_tile',
          color: SPRITE_AS_IS,
          life: end - st.land,
          kind: 'stacktile',
        }));
        s.at(end, burst(cellCenter(st.col, st.row), i, 0.5));
      }
    });

    // ======================================================================
    // ★ v21  66.771〜103.346s — 指示書のマーカー 18〜42
    //   採用時刻はファイル上部の MK18_SLIDE1 以降の定数（根拠は .tmp_v21/onset_table.txt）。
    //
    //   60.000〜66.771s は曲のブレイク（Instructions/石工/gemini_song_analysis_20260903.md）。
    //   v20 の帯は 60.000s（EXT_END_BEAT）で消え切っているので、この 6.8 秒は弾ゼロの静止。
    //   53.333s / 56.667s の仮区間⑮⑯は 59.2s で終わり、新しい内容と重ならないので残した。
    //
    //   ブロックA（18〜28・66.8〜79.7s）… 右列タイルの左流し 4 回 → 隕石 5 連 ×2 → 隕石 8 連
    //   ブロックB（29〜36・80.0〜97.5s）… 左流し 4 回 → タイル攻撃 5 回 → 左流し 4 回
    //                                     → タイル表示 6 拍 → 爆破 2 枚 ×4
    //   ブロックC（37〜42・98.3〜103.3s）… 左右の列を縦の鎖で / 上下の列を横の鎖で消す
    //                                     → 中央の縦の鎖 2 本 → 落下隕石 3 発と放射
    // ======================================================================

    // --- 右列タイルの左流し 1 回分（マーカー 18〜21 / 29 / 31）-----------------
    //   行は毎回ばらす。直前の回で使った行は候補から外すので、前の波がまだ流れている
    //   あいだに次の波が出ても同じ行で重ならない（1 波は 1 拍静止 + 約 1.41s 飛行 ＝ 1.83s
    //   画面に居る。波の間隔は 0.74〜0.83s なので常に 2〜3 波が同時に見える）。
    let slidePrevRows = [];
    // v27 (11): 手打ち 83.112「このブロックで表示するタイルは、残さず消して」。
    //   1 波は 1 拍静止 + 約 1.42s の飛行で 1.84s 画面に居るので、ブロック A の最後の波
    //   （82.483s）は 84.3s まで＝次のブロックの頭（82.9167s）を越えて画面に残っていた。
    //   endBy を渡すと、その時刻で飛行区間を打ち切って（＝まだ画面内でも）タイルを消す。
    function slideWave(t, endBy) {
      const pool = shuffled(
        Array.from({ length: ROWS }, function (_, r) { return r; })
          .filter(function (r) { return slidePrevRows.indexOf(r) < 0; }),
        rng
      );
      const rows = pool.slice(0, SLIDE_TILES_PER_WAVE).sort(function (a, b) { return a - b; });
      slidePrevRows = rows;
      const cells = rows.map(function (r) { return [SLIDE_COL, r]; });
      // 予告 → 実体化ポップ（マーカー 4〜8 のタイル出現と同じ作り）
      s.at(t - SLIDE_WARN_LEAD, tileField(cells, {
        type: 'warn_box',
        color: STONE_WARN,
        appearTime: SLIDE_WARN_LEAD,
        appearDuration: SLIDE_WARN_LEAD,
        life: SLIDE_WARN_LEAD + SEAM_MARGIN,
        kind: 'tilewarn',
      }));
      s.at(t, tilePop(cells, 'tilepop'));
      // 実体は 1 拍静止してから左向きに等加速（画面外で消える）
      // v23 (B)4: gravitySeq(v2) は既定 useVelocityAngle:true で、加速中は速度角（180°）へ
      // 描画が回ってしまう。位置計算（gravitySeq の結果）はそのまま使い、返ってきた v2 弾の
      // useVelocityAngle だけ false に上書きして常に正立（initialAngle 既定 0）させる。
      rows.forEach(function (r) {
        const c = cellCenter(SLIDE_COL, r);
        let fly = Math.sqrt((2 * (c[0] - SLIDE_END_X)) / SLIDE_ACCEL);
        if (endBy !== undefined) fly = Math.min(fly, Math.max(1 / 60, endBy - t - SLIDE_HOLD));
        const clip = gravitySeq(
          { pos: c, vel: [0, 0], type: 'stone3_tile', scale: [TILE, TILE], color: SPRITE_AS_IS, unCounterable: true },
          [
            { until: SLIDE_HOLD, moveTo: c },
            { until: SLIDE_HOLD + fly, accel: [SLIDE_ACCEL, Math.PI] },
          ],
          'slide',
          { v2: true }
        );
        clip.parts[0].buffer.bullets[0].useVelocityAngle = false;
        s.at(t, clip);
      });
    }

    // --- 隕石 1 発（マーカー 22〜28）------------------------------------------
    //   通る行を 1 拍前から薄い帯で予告 → 隕石本体（右→左の直線）＋尾。
    //   通り道に残留タイルがあれば通過の瞬間に砕き、先頭 3 枚から放射弾を出す。
    let meteorIdx = 0;
    let meteorPrevRow = -1;
    function nextMeteorRow() {
      // 直前の隕石と 2 行以上離す（同じ高さが続かないように）
      const pool = METEOR_ROWS.filter(function (r) { return Math.abs(r - meteorPrevRow) >= 2; });
      const r = pool[Math.floor(rng() * pool.length)];
      meteorPrevRow = r;
      return r;
    }
    function meteorShot(t, row, tiles) {
      const y = cellCenter(0, row)[1];
      const speed = (METEOR_START_X - METEOR_END_X) / METEOR_FLIGHT;
      // v27 (9): 発射角と自転を 1 発ずつ乱数で振る（専用ストリームなので他の弾は不変）
      const jit = meteorJit();
      const mo = meteorMotion(y, jit);
      const drift = Math.abs(mo.vy) * METEOR_FLIGHT;   // 全行程で振れる y の幅
      s.at(t - METEOR_WARN_LEAD, meteorRowWarn(y, METEOR_WARN_LEAD, drift));
      // v24 (B)1: 画面右端で白く弾けてから本体が飛び出す。本体が右端(x=32)を通るのは
      //   発射の (34.5-32)/36.7 = 0.068 秒後なので、その時刻にフラッシュを合わせる。
      const enterRel = (METEOR_START_X - COLS * CELL) / speed;
      s.at(t, flashPop(
        [COLS * CELL, mo.y0 + mo.vy * enterRel], enterRel,
        METEOR_FLASH_S0, METEOR_FLASH_S1, METEOR_FLASH_DUR, 'meteorspawn'
      ));
      s.at(t, meteor(y, jit));
      s.at(t, meteorTrail(y, jit));
      const hits = [];
      tiles.forEach(function (tt) {
        if (tt.claimed) return;
        const c = cellCenter(tt.col, tt.row);
        const rel = (METEOR_START_X - c[0]) / speed;
        if (Math.abs(c[1] - (mo.y0 + mo.vy * rel)) > METEOR_BREAK_DY) return;
        const hit = t + rel;
        if (hit < tt.strike || hit > t + METEOR_FLIGHT) return;
        tt.claimed = true;
        tt.end = hit;
        tt.lead = BLAST_LEAD_OUT;
        hits.push({ t: hit, c: c });
      });
      // v24 (B)5: 通過中に残留タイルを砕いた瞬間、その場に小さいフラッシュを出す
      //   （放射弾が出るのは先頭 3 枚だけだが、フラッシュは砕けた全部に付ける）。
      hits.forEach(function (h) {
        s.at(h.t, flashPop(h.c, 0, METEOR_BREAK_S0, METEOR_BREAK_S1, METEOR_BREAK_DUR, 'meteorbreak'));
      });
      hits.sort(function (a, b) { return a.t - b.t; })
        .slice(0, 3)
        .forEach(function (h, k) { s.at(h.t, burst(h.c, meteorIdx + k, 0.5)); });
      meteorIdx++;
    }

    // --- 鎖攻撃 1 回分（向きを選べる版。マーカー 37〜39）-----------------------
    //   構造は v19 の chainAttack と同じ（予告①→予告②→鎖→掃かれたタイルの破壊→放射弾）で、
    //   進む向き・揺れる向き・速さを cfg で差し替えられるようにしただけ。
    function chainAttackG(cfg, warn1, warn2, t0, lanes, tiles, noBurst) {
      s.at(warn1, chainWarn(cfg, lanes, STONE_PATH, warn2 - warn1, 'snakewarn1'));
      s.at(warn2, chainWarn(cfg, lanes, STONE_WARN, t0 - warn2, 'snakewarn2'));
      lanes.forEach(function (lane) {
        for (let k = 0; k < cfg.steps; k++) {
          const at = chainWindow(cfg, t0, k)[0];
          s.at(at, chainTile(cfg, t0, k, lane));
          s.at(at, chainPop(cfg, t0, k, lane));
        }
      });
      const broken = [];
      tiles.forEach(function (t) {
        if (t.claimed) return;
        const hit = chainBreakTime(cfg, t.col, t.row, t0, lanes);
        if (hit === null) return;
        t.claimed = true;
        t.end = hit;
        t.lead = BLAST_LEAD_OUT;
        broken.push(t);
      });
      const sorted = broken.slice().sort(function (a, b) { return a.col - b.col || a.row - b.row; });
      // v29 (5): cfg.noBurst / 引数 noBurst で、掃かれたタイルからの放射弾を止める
      //   （指示 99.733「中央の隕石爆破の破裂弾以外はなくして」＝ 98.3〜99.6s の鎖の破壊弾）。
      if (sorted.length > 0 && !noBurst) {
        const step = Math.max(1, Math.ceil(sorted.length / SNAKE_BURSTS));
        for (let i = 0, k = 0; i < sorted.length; i += step, k++) {
          const t = sorted[i];
          s.at(t.end, burst(cellCenter(t.col, t.row), k, 0.5));
        }
      }
      return broken;
    }

    // ----------------------------------------------------------------------
    // ブロックA — マーカー 18〜28（66.771〜79.688s）
    // ----------------------------------------------------------------------
    // v27: 前半の変更で、ここへ来るまでの乱数の呼び出し数が
    //   easy 2698 / normal 2596 / lunatic 2563（v26）→ 2985 / 2911 / 2871（v27）に増えた。
    //   mulberry32 は 1 回の呼び出しで内部状態が 0x6d2b79f5 進むだけなので、
    //   種を (20260902 + n * 0x6d2b79f5) mod 2^32 にすると「元の種で n 回呼んだ直後」と
    //   まったく同じ続きになる。これで 66.8s 以降のランダム配置は v26 から 1 発も動かず、
    //   後半の差分を「指示 9〜19 で意図的に変えたぶんだけ」に閉じ込められる。
    reseedRng((20260902 + D(2698, 2596, 2563) * 0x6d2b79f5) % 4294967296);

    // マーカー 18-21: 右列タイルの左流し 4 回（66.771 / 67.512 / 68.348 / 69.178s）
    SLIDE_TIMES_A.forEach(function (t) { slideWave(t, MK30_TILE5); });   // v27 (11): ブロック A の終わりで消す

    // マーカー 22-26: 隕石 5 連（70.104 / 70.844 / 71.979 / 72.510 / 72.922s）
    // マーカー 27: 同じ相対間隔でもう 1 巡（73.346〜76.164s）
    // この時間帯に残留タイルは無い（v20 の帯は 60.000s で消え切っている）ので、
    // 破壊判定は空振りする。判定自体は 29 以降の帯と共通の作りにしてある。
    METEOR_TIMES_1.forEach(function (t) {
      meteorShot(t, nextMeteorRow(), []);
    });

    // v27 (10): 73.3228〜75.8228s は隕石ではなく右列の重力タイル（マーカー 18〜21 と同じ作り）。
    V27_SLIDE_TIMES_D.forEach(function (t) { slideWave(t, MK30_TILE5); });

    // マーカー 28: 隕石 8 連（76.771s から 1 拍間隔で 8 回 = 79.688s まで）
    METEOR_TIMES_8.forEach(function (t) { meteorShot(t, nextMeteorRow(), []); });

    // ----------------------------------------------------------------------
    // ブロックB — マーカー 29〜36（80.010〜97.512s）
    // ----------------------------------------------------------------------
    // マーカー 29: 右列タイルの左流し again（18〜21 の相対間隔を写す）
    SLIDE_TIMES_B.forEach(function (t) { slideWave(t, MK30_TILE5); });   // v27 (11): 82.9167s で残らず消える

    // マーカー 30: タイル攻撃 5 回（83.229s から 2 拍間隔）。区間①③と同じ出現ポップで
    //   外周ぐるりの帯へ積む。ここで積んだ帯がマーカー 33〜36 の爆破対象になる。
    const bandF = tilePhase({
      times: V29_TILE6_TIMES,
      leads: V29_TILE6_TIMES.map(function () { return beats(1); }),
      centerRate: CENTER_RATE,
      bandTarget: BAND_TARGET,
      bandCells: BAND_CELLS,
      bandEnd: V21_BAND_END,
      clearEachStrike: true,          // v29 (3): 出すごとに前の表示を消す
      finalEnd: MK31_SLIDE_AGAIN2,    // 6 回目もマーカー 31 の頭で消える（残さない）
      pinStartGap: false,
    });

    // マーカー 31: 右列タイルの左流し again 2 回目（86.875〜89.282s）
    //   v29 (3): マーカー 32 の表示に被らないよう、endBy にマーカー 32 の頭を渡して
    //   その時刻で流し終える（v27 (11) と同じ「残さず消す」扱い）。
    SLIDE_TIMES_C.forEach(function (t) { slideWave(t, MK32_TILE_SHOW); });

    // マーカー 32: タイル表示 again（90.012s から 1 拍間隔で 6 拍）。既に画面にある
    //   bandF の残りを preBlocked に渡し、自機の通路が塞がらないように積み足す。
    const aliveF = new Set(bandF.filter(function (t) { return !t.claimed; }).map(function (t) { return key(t.col, t.row); }));
    const bandG = tilePhase({
      times: TILE6_TIMES,
      leads: TILE6_TIMES.map(function () { return beats(0.75); }),
      centerRate: CENTER_RATE,
      bandTarget: EXT_BAND_TARGET,
      bandCells: BAND_CELLS,
      preBlocked: aliveF,
      bandEnd: V21_BAND_END,
      pinStartGap: false,
    });

    // マーカー 33-36: 残留タイルを 1 回 2 枚ずつ爆破（93.438 / 95.016 / 96.740 / 97.512s）。
    //   blastPhase の 4 辺めぐりなので 2 枚は必ず別の辺に散る。点滅予告は 1 拍前から。
    blastPhase({
      tiles: bandF.concat(bandG),
      shots: BLAST2_TIMES.map(function (t) { return { time: t, n: 2 }; }),
    });

    // ----------------------------------------------------------------------
    // ブロックC — マーカー 37〜42（98.342〜103.346s）
    // ----------------------------------------------------------------------
    // マーカー 37: 左右の列を縦の鎖で消す（98.342s）。中心列 1 と 14 に置くと、
    //   破壊半径 1.8 + 揺れ 0.95 で 帯の 列 0-1 / 14-15 をどちらも掃ける。
    //   予告①②はマーカー 36（97.512s）の直後に置いた。
    const CHAIN37_LANES = [{ col: 1, phase: 0 }, { col: 14, phase: Math.PI }];
    chainAttackG(
      CHAIN_V_FAST, MK37_CHAIN_LR - 0.52, MK37_CHAIN_LR - 0.21, MK37_CHAIN_LR,
      CHAIN37_LANES, bandF.concat(bandG), true   // v29 (5): 破壊の放射弾なし
    );

    // マーカー 38: 上下の列を横の鎖で消す（99.063s・左→右）。中心行 1 と 7 で
    //   帯の 行 0-1 / 7-8 を掃く。これで外周の 4 辺が全部消える。
    const CHAIN38_LANES = [{ row: 1, phase: 0 }, { row: 7, phase: Math.PI }];
    chainAttackG(
      CHAIN_H, MK38_CHAIN_TB - 0.40, MK38_CHAIN_TB - 0.16, MK38_CHAIN_TB,
      CHAIN38_LANES, bandF.concat(bandG), true   // v29 (5): 破壊の放射弾なし
    );

    // マーカー 39: 縦の鎖 2 本（99.590s）。右半分の中央（列 11）は上から下、
    //   左半分の中央（列 4）は下から上。残留タイルはもう無いので破壊は起きない。
    chainAttackG(
      CHAIN_V_FAST_DOWN, MK39_CHAIN_MID - 0.35, MK39_CHAIN_MID - 0.15, MK39_CHAIN_MID,
      [{ col: 11, phase: 0 }], bandF.concat(bandG), true
    );
    chainAttackG(
      CHAIN_V_FAST, MK39_CHAIN_MID - 0.35, MK39_CHAIN_MID - 0.15, MK39_CHAIN_MID,
      [{ col: 4, phase: Math.PI }], bandF.concat(bandG), true
    );

    // v29 (3): マーカー 30 のタイル表示を 5 回 → 6 回（指示の番号 1〜6）へ変え、さらに
    //   出すごとに消す（積み上げない）ようにしたので、ここまでに rng を呼ぶ回数が v28 と
    //   変わる。残留タイルが減ったぶん、マーカー 33〜39（爆破 2 枚 ×4・鎖 3 種）が壊す枚数も
    //   変わるため、乱数の位置合わせはこの 3 ブロックの**あと**でないと効かない。
    //   v27 と同じ手（mulberry32 は 1 回の呼び出しで内部状態が 0x6d2b79f5 進むだけ）で、
    //   マーカー 40 の直前に「v28 でここへ来たときの状態」へ戻す。v28 の呼び出し回数は
    //   3577 行の reseed 以降で easy 1224 / normal 1131 / lunatic 1089（実測）。
    //   これで 100.0s 以降のランダムな配置は v28 から 1 発も動かない。
    reseedRng((20260902 + D(2698 + 1224, 2596 + 1131, 2563 + 1089) * 0x6d2b79f5) % 4294967296);

    // マーカー 40-42: 落下隕石（中央 100.014s / 右 101.680s / 左 103.346s）。
    //   横断シャベル（区間⑤⑦）と同じく「着弾時刻」を先に決め、飛来時間ぶん手前で
    //   発射する。着弾点（最下段の中心）から放射弾を 1.6 倍の数で出す。
    const DROP_FLIGHT = Math.sqrt((2 * (METEOR_DROP_SPAWN_Y - METEOR_DROP_Y)) / METEOR_DROP_ACCEL);
    [
      [MK40_DROP_MID, (COLS * CELL) / 2],   // 中央（x = 16）
      [MK41_DROP_R, 24],                    // 右側（列 11-12 の境）
      [MK42_DROP_L, 8],                     // 左側（列 3-4 の境）
    ].forEach(function (d, k) {
      const impact = d[0];
      const x = d[1];
      const warnDur = DROP_FLIGHT + beats(1);
      // 本体が画面上端(y=18)へ入る時刻。26 - a t^2 / 2 = 18 → t = sqrt(16/a)
      const enter = Math.sqrt((2 * (METEOR_DROP_SPAWN_Y - ROWS * CELL)) / METEOR_DROP_ACCEL);
      s.at(impact - warnDur, meteorDropWarn(x, warnDur));
      // v27 (14): 出現位置（画面上端のその列）に 1 拍前から四角い予告を出す
      s.at(impact - DROP_FLIGHT - beats(1), warnClip([{
        pos: [x, ROWS * CELL - METEOR_SCALE / 2],
        scale: [METEOR_SCALE, METEOR_SCALE],
        color: STONE_WARN,
        appearTime: beats(1),
        appearDuration: beats(1),
        life: beats(1),
      }], 'meteorspawnwarn'));
      // v24 (B)1: 画面上端に出現フラッシュ → 本体が飛び出す
      s.at(impact - DROP_FLIGHT, flashPop(
        [x, ROWS * CELL], enter, METEOR_FLASH_S0, METEOR_FLASH_S1, METEOR_FLASH_DUR, 'meteorspawn'
      ));
      s.at(impact - DROP_FLIGHT, meteorDrop(x, DROP_FLIGHT));
      s.at(impact - DROP_FLIGHT, meteorDropTrail(x, DROP_FLIGHT));   // v24 (B)2: 落下にも尾を付けた
      // v27 (15): 大きい正方形 1 枚のフラッシュ → 円周上に並べたポップのリング 2 枚へ。
      s.at(impact, meteorBurstFx([x, METEOR_DROP_Y], 1.0, 'meteorhit'));   // v29b: 輪郭リング＋欠片
      s.at(impact, meteorSquash([x, METEOR_DROP_Y]));
      // v29 (5): 指示 99.733「弾がこの場面多すぎる。中央の隕石爆破の破裂弾以外はなくして」
      //   → 放射弾は中央（k=0・100.014s）の 1 発だけにする。右（101.680s）と左（103.346s）は
      //   落下・着弾の演出（リング・潰れ・尾）だけ残して弾を出さない。
      if (k === 0) s.at(impact, burst([x, METEOR_DROP_Y], k, 1.6));
    });

    // 残ったタイルの実体クリップを出す（消える時刻が全部確定したあと）。
    // 使い切らなかったタイルは bandEnd = B(144) = 60.000s＝次のセクションの頭で消える。
    emitBandTiles(bandC);
    emitBandTiles(bandD);
    emitBandTiles(bandE);
    emitBandTiles(bandH);   // v27 (7)(C): 51.2348s のタイル表示
    // v21: マーカー 30 / 32 で積んだ帯。使い切らなかったぶんは V21_BAND_END（100.60s）
    //   ＝ マーカー 38 の横の鎖が通り過ぎた直後に消える。
    emitBandTiles(bandF);
    emitBandTiles(bandG);

    // ======================================================================
    // v29 (5): マーカー 40〜42 の放射弾を中央 1 発だけにしたぶん rng の消費が 2 回減る。
    //   105.1s 以降のタイル配置を動かさないよう、ここで v29(4) と同じ状態へ戻す
    //   （マーカー 40 の reseed からの消費数は 3・実測）。
    reseedRng((20260902 + D(2698 + 1224 + 3, 2596 + 1131 + 3, 2563 + 1089 + 3)
      * 0x6d2b79f5) % 4294967296);

    // ★ v22  105.104〜110.938s — 指示書のマーカー 43〜51
    //   採用時刻はファイル上部の MK43_TILE6 以降の定数（根拠は .tmp_v22/onset_table.txt）。
    //
    //   43-44 … 拍に合わせてタイルを 6 回表示（端も中央も残す）。その裏で 5 回の爆破。
    //   45-47 … 48 の攻撃に使うタイル群を予告 → 実体化して表示したまま。
    //            43-44 の残りは 47 で一斉に消える（48 用のタイルだけが残る）。
    //   48    … 45/46 のタイルが回転しながら中央下の 1 点へ集まり、着いた瞬間に 2 重リングの大爆発。
    //   49-51 … 壁に隕石を当てて爆破。1 発目は上側を左→右、2 発目は下側を右→左。
    // ======================================================================

    // --- マーカー 43: タイル表示 x6（105.104s から 1 拍間隔）---------------------
    //   「端っこも中央も残し、このあとまとめて消す」ので、中央セルも帯と同じ扱い
    //   （＝拍末で消えない残留タイル）にする。tilePhase の bandCells に全 144 セルを渡し、
    //   centerRate を 0 にすると、この振る舞いになる。連結判定は積むたびに走るので、
    //   6 拍ぶん積んでも自機の通り道は必ず残る。消える時刻はマーカー 47。
    const band43 = tilePhase({
      times: TILE43_TIMES,
      leads: TILE43_TIMES.map(function () { return beats(0.75); }),
      centerRate: 0,
      bandTarget: D(0.26, 0.32, 0.38),
      bandCells: ALL_CELLS,
      bandEnd: MK47_TILE_CLEAR,
      pinStartGap: false,
    });

    // --- マーカー 44: タイル攻撃 x5（105.424s から 1 拍間隔）---------------------
    //   43 で並んだタイルから 1 回 2 枚ずつ爆破する。43 の 6 回とは 0.32 秒ずれるので、
    //   「表示 → 爆破 → 表示 → 爆破」と交互に鳴る。
    //   blastPhase は「2 拍以上前に出たタイル」しか選ばない（BLAST_MIN_AGE）ため、
    //   置いた直後を狙うこの区間には使えない。同じ見た目の部品（半拍の予告 + リング予告 +
    //   放射弾）を並べた専用版にした。点滅予告（1 拍リード）は対象タイルが生まれる前に
    //   始まってしまうので、ここでは使わない。
    let blast44Idx = 0;
    function blastAt(time, pool, n) {
      const usable = pool.filter(function (t) {
        return !t.claimed && t.strike <= time - beats(0.7);
      });
      const cand = shuffled(usable, rng);
      const picks = [];
      for (let pass = 0; pass < 2 && picks.length < n; pass++) {
        for (let i = 0; i < cand.length && picks.length < n; i++) {
          const c = cand[i];
          if (picks.indexOf(c) >= 0) continue;
          // 1 回の 2 枚は離れた場所に散らす（1 パス目だけ距離を要求し、足りなければ緩める）
          if (pass === 0 && picks.some(function (q) {
            return Math.abs(q.col - c.col) + Math.abs(q.row - c.row) < 5;
          })) continue;
          picks.push(c);
        }
      }
      if (picks.length === 0) return;
      picks.forEach(function (t) {
        t.claimed = true;
        t.end = time;
        t.lead = BLAST_LEAD_OUT;
      });
      const cells = picks.map(function (t) { return [t.col, t.row]; });
      s.at(time - beats(0.5), tileField(cells, {
        type: 'warn_box',
        color: STONE_MID,
        appearTime: beats(0.5),
        appearDuration: beats(0.5),
        life: beats(0.5),
        kind: 'blastwarn',
      }));
      // v29 (5): 指示 107.476「ここはタイル破裂弾不要」→ 爆破したタイルから出していた
      //   放射弾を削除。予告とタイルが消える演出はそのまま。
      blast44Idx++;
    }
    // v27 (16): 手打ち 105.582「ここは爆破不要」→ 窓内のオンセット 105.4070（1 発目）を削除。
    //   残り 4 回（105.8237 / 106.2403 / 106.6570 / 107.0737）はそのまま。
    BLAST44_TIMES.slice(1).forEach(function (t) { blastAt(t, band43, 2); });

    // --- マーカー 45/46: 48 の攻撃に使うタイルを予告 → 表示したまま --------------
    //   45 と 46 は 4ms しか離れていない（＝同じ音）ので、予告を 0.75 拍手前から出し、
    //   107.508s ちょうどで実体化させて「表示完了・表示したまま」にする。
    //   場所は画面の上半分〜中央（行 3 以上）に散らす。43 のタイルが生きているセルは避ける。
    const alive43 = new Set(
      band43.filter(function (t) { return t.end > MK46_TILE_SET + 0.01; })
        .map(function (t) { return key(t.col, t.row); })
    );
    const gatherWant = D(8, 10, 12);
    const gatherCand = shuffled(
      ALL_CELLS.filter(function (c) { return c[1] >= 3 && !alive43.has(key(c[0], c[1])); }),
      rng
    );
    const gatherCells = [];
    for (let pass = 0; pass < 2 && gatherCells.length < gatherWant; pass++) {
      for (let i = 0; i < gatherCand.length && gatherCells.length < gatherWant; i++) {
        const c = gatherCand[i];
        if (gatherCells.indexOf(c) >= 0) continue;
        if (pass === 0 && gatherCells.some(function (q) {
          return Math.abs(q[0] - c[0]) + Math.abs(q[1] - c[1]) < 3;
        })) continue;
        gatherCells.push(c);
      }
    }
    // v27 (17): 手打ち 108.082「ここで下にあつめるタイルは他と同じような表示は不要で、
    //   単に画面外から飛んでくるようにして」。参考 bePI-wq_lNk 1:02 でも 4 個の弾は
    //   予告もポップも無く画面の外に現れてそのまま飛び込んでくる。
    //   → タイル予告（tilewarn）・実体化ポップ（tilepop）・静止する実体（tile）を全廃し、
    //     GATHER_ENTER から画面外の点を出発する 3 段モーション（gatherFly）に置き換えた。
    // 45 の「次の攻撃の予告」= タイルが集まってくる 1 点だけは、爆発の瞬間まで薄く残す。
    // v29 (5): 上の「タイル破裂弾」削除で rng の消費が減るので、集合〜壁隕石（108.3s 以降）を
    //   動かさないようここでも v29(4) と同じ状態へ戻す（マーカー 40 の reseed からの消費数は
    //   easy 1152 / normal 1138 / lunatic 1125・実測）。
    reseedRng((20260902 + D(2698 + 1224 + 1152, 2596 + 1131 + 1138, 2563 + 1089 + 1125)
      * 0x6d2b79f5) % 4294967296);

    s.at(GATHER_ENTER, warnClip([{
      pos: GATHER_POINT,
      scale: [CELL * 1.6, CELL * 1.6],
      color: STONE_PATH,
      appearTime: GATHER_IMPACT - GATHER_ENTER,
      appearDuration: GATHER_IMPACT - GATHER_ENTER,
      life: GATHER_IMPACT - GATHER_ENTER,
    }], 'gatherwarn'));

    // --- マーカー 47: 43〜44 の残タイルを消す ------------------------------------
    //   band43 の bandEnd = MK47_TILE_CLEAR なので、爆破されなかったタイルは
    //   ここで一斉に寿命が尽きる（実体クリップは末尾の emitBandTiles で出す）。

    // --- マーカー 48: 下に集めて爆破（108.344s → 着弾 109.167s）------------------
    //   参考の「下に弾を集めて爆破する攻撃」を、45/46 で出したタイルでやる。
    //   v24 (A): 集合点を画面下端の中央 (16, 1.2) へ下げ、動きを等速から
    //   「静止 → 等加速（s(u)=u^2）で 1 点へ吸い込まれる」へ変えた（gatherTile 参照）。
    //   タイルは回転しながら 2 拍かけて集まり、次の強拍（拍 262 = 109.167s）ちょうどで
    //   全枚数が同時に 1 点へ重なって消え、同時に 2 重リングの放射弾が出る。
    //   弾数は通常の爆破（D(10,12,14)）の 4 倍。内側は遅く外側は速いので、広がるにつれて
    //   リングが 2 枚に分かれて見える。集合点が下端なので下向きの弾はすぐ画面外へ抜け、
    //   実質は上向きの扇になる（＝参考どおり、下端沿いに左右へ逃げ場が残る）。
    const GATHER_FLIGHT = GATHER_IMPACT - GATHER_ENTER;   // 0.8359s（飛び込み〜爆発）
    gatherCells.forEach(function (c, i) {
      gatherFly(
        gatherEntry(c), cellCenter(c[0], c[1]), GATHER_POINT,
        GATHER_SPIN * (i % 2 === 0 ? 1 : -1)
      ).forEach(function (seg) { s.at(seg[0], seg[1]); });
    });
    // v25: v24 は GATHER_IMPACT の瞬間に flashPop（大→小に縮む閃光。開始 POP_COLOR_START
    //   →終了 STONE_MID）を 1 発出すだけだった。BulletIndirectURP.shader の通常弾パスは
    //   color.a を透明度ではなく「着色の有無」の 0/1 スイッチとして扱う（a>0 なら不透明に
    //   フルカラー塗り）ため、animDuration が終わったあとは colorEnd＝STONE_MID（暗い紫）の
    //   まま不透明な板が残り、実フレーム（Captures/stone_v24_f4_gather_ease_t108.59_108.89.png,
    //   f5_gather_burst_t109.30.png）では自機の足元の「暗い矩形」として写った。
    //   （なお f4 の時点はまだ GATHER_IMPACT 前なので、そこに写っていたのは本来 45 の
    //   「次の攻撃予告」warnClip(STONE_PATH, kind:'gatherwarn') で、これは意図どおりの
    //   薄い予告表示。今回問題なのは f5＝GATHER_IMPACT 直後に STONE_MID の不透明な板が
    //   居座って見える方。）
    //   修正: 「爆発直後に縮む閃光」をやめ、「集合の 2 拍（MK48_GATHER→GATHER_IMPACT＝
    //   GATHER_FLIGHT）のあいだに小さく暗い点から大きく白い点へ徐々に育ち、爆発の瞬間
    //   ちょうどに最大の白さへ達してから disappearDuration(0.1s) で消える」動きに変える。
    //   色の終端を STONE_MID ではなく POP_COLOR_START（明るい白）にすることで、
    //   「白く明るく」なる瞬間が短い閃光ではなく explosion の直前まで持続する見た目になる。
    const GATHER_BLOOM_S0 = TILE * 0.4;          // 集合開始時はごく小さい点
    const GATHER_BLOOM_S1 = TILE * 3.5;          // 爆発の瞬間に最大まで広がる
    const GATHER_BLOOM_C0 = STONE_MID;           // 開始色: 暗め（タイルの影色と揃える）
    const GATHER_BLOOM_C1 = POP_COLOR_START;     // 終了色: 白く明るい
    // v27 (18): 爆発が 109.1602 → 108.3269 へ前倒しになったので、ブルームは
    //   「所定位置に着いた瞬間（108.0424）から爆発まで（0.2845s）で白く育つ」形にする。
    const GATHER_BLOOM_DUR = GATHER_IMPACT - GATHER_SETTLE;
    s.at(GATHER_SETTLE, warnClip([{
      type: BLINK_TYPE,
      pos: GATHER_POINT,
      scale: [GATHER_BLOOM_S0, GATHER_BLOOM_S0],
      color: GATHER_BLOOM_C0,
      scaleEnd: [GATHER_BLOOM_S1, GATHER_BLOOM_S1],
      colorEnd: GATHER_BLOOM_C1,
      animDuration: GATHER_BLOOM_DUR,
      appearTime: 0,
      appearDuration: 0,
      life: GATHER_BLOOM_DUR + FADE_OUT_SEC,
    }], 'gatherbloom'));
    const GATHER_RING_N = Math.round(D(10, 12, 14) * 2);
    s.at(GATHER_IMPACT, spinBurst({
      pos: GATHER_POINT,
      count: GATHER_RING_N,
      speed: D(7, 9, 11),
      type: 'stone3_bullet',
      life: 0,
      scale: [BULLET_SCALE, BULLET_SCALE],
      color: SPRITE_AS_IS,
      angleOffset: rng() * 2 * Math.PI,
      spin: SPIN_RATE,
      kind: 'blast',
      unCounterable: true,
    }));
    s.at(GATHER_IMPACT, spinBurst({
      pos: GATHER_POINT,
      count: GATHER_RING_N,
      speed: D(11, 14, 17),
      type: 'stone3_bullet',
      life: 0,
      scale: [BULLET_SCALE, BULLET_SCALE],
      color: SPRITE_AS_IS,
      angleOffset: rng() * 2 * Math.PI + Math.PI / GATHER_RING_N,
      spin: -SPIN_RATE,
      kind: 'blast',
      unCounterable: true,
    }));

    // --- マーカー 49〜51: 壁に隕石を当てて爆破 -----------------------------------
    //   1 発目は画面上側（行 6・y=13）を左→右、2 発目は下側（行 1・y=3）を右→左。
    //   発射から着弾までは 1 マーカーぶん（0.833s ＝ 2 拍）。着弾点は隕石の半径ぶん
    //   壁の内側（右 30.4 / 左 1.6）で、そこから v21 の落下隕石と同じ 1.6 倍の放射弾を出す。
    const WALL_M1_Y = 13;
    const WALL_M2_Y = 3;
    [
      // [発射時刻, 着弾時刻, 始点 x, 着弾 x, y]
      [MK49_WALL1, MK50_WALL2, WALL_LEFT_X, WALL_HIT_RIGHT, WALL_M1_Y],
      [MK50_WALL2, MK51_WALL2_HIT, WALL_RIGHT_X, WALL_HIT_LEFT, WALL_M2_Y],
    ].forEach(function (w, k) {
      const fire = w[0], hit = w[1], x0 = w[2], x1 = w[3], y = w[4];
      const flight = hit - fire;
      // 本体が画面（x 0〜32）へ入る位置と、そこを通る時刻
      const edgeX = x0 < x1 ? 0 : COLS * CELL;
      const enter = ((edgeX - x0) / (x1 - x0)) * flight;
      s.at(fire - METEOR_WARN_LEAD, meteorRowWarn(y, METEOR_WARN_LEAD));
      // v24 (B)1: 画面端の出現フラッシュ
      s.at(fire, flashPop(
        [edgeX, y], enter, METEOR_FLASH_S0, METEOR_FLASH_S1, METEOR_FLASH_DUR, 'meteorspawn'
      ));
      s.at(fire, meteorLine(x0, x1, y, flight));
      s.at(fire, meteorLineTrail(x0, x1, y, flight));
      // v27 (19): 参考 1:10 に合わせ、同心リング 3 枚（時間差で外へ広がる衝撃波）＋
      //   個々に飛び散る破片 2 段（速い外側 20 発・遅い内側 12 発）にした。
      //   隕石本体の軌道・時刻・当たり判定は据え置き（指示「隕石はそのままでいい」）。
      s.at(hit, meteorBurstFx([x1, y], 1.2, 'meteorhit'));   // v29b: 輪郭リング＋欠片（小さい四角の破片は廃止）
      s.at(hit, burst([x1, y], k, 1.6));
    });

    // v22: マーカー 43 のタイル。爆破されなかったぶんはマーカー 47（108.066s）で消える。
    //   v22 の区間をここ（既存の emitBandTiles のあと）に置いてあるのは、クリップの連番が
    //   s.at() の呼び出し順で決まるため。こうすると v21 までのクリップ名が 1 つも動かない。
    emitBandTiles(band43);

    // ======================================================================
    // v29 (5): 上の「タイル破裂弾」削除で v22 ブロックの rng 消費数が変わる。111.9s 以降を
    //   動かさないため、マーカー 40 の reseed からの消費数（実測 easy 1156 / normal 1142 /
    //   lunatic 1129）を足した状態へ戻す。
    reseedRng((20260902 + D(2698 + 1224 + 1156, 2596 + 1131 + 1142, 2563 + 1089 + 1129)
      * 0x6d2b79f5) % 4294967296);

    // ★ v28  111.875〜141.653s — 指示書 v28_ending の 111.878 以降 22 マーカー
    //   ステージ末尾を 113.6 → 142.5 へ延ばし、そこへ末尾の一続きを足した区間。
    //   この区間の s.at() は既存クリップの**あと**にだけ並ぶので、もともと出ていた弾は
    //   1 発も動かない（クリップ名の連番も末尾に足されるだけ）。乱数も同様に、既存の
    //   消費のあとから使う（burst()/spinBurst() の angleOffset のみ）。
    //
    //   1〜5  … 打ち上げ隕石＋横から来るシャベルの衝突を、中心について点対称に 2 回。
    //           そのあと中央に落下隕石。ブロックごと 114.991 からもう一度繰り返し、
    //           2 回目の着弾を lightspeed 風（白く育つブルーム＋2 重リング）にする。
    //   6〜7  … 落ちてきて下側で止まる隕石 3 発を、左から来る 1 本のシャベルが順に割る。
    //   8〜9  … 右から縦一列（ずらし）／上からずらして落とすシャベル。
    //   10    … 6〜7 と同じ攻撃を上下反転して上側で。
    //   11〜12… 一列に揃えたシャベルの壁を右→左へ。1 レーンだけ空けて抜け穴を作る。
    //           2 回目は前の抜け穴が埋まり、別のレーンが空く。
    //   13〜15… 静かな区間。爆破も放射弾も無い隕石だけ（左→右→上下すれ違い）。
    //   16〜17… 中央上から中央へ減速して寄り、少し戻してから床へ落として最後の大爆破。
    // ======================================================================

    // 画面（x 0〜32 / y 0〜18）へ最初に入る瞬間を探して出現フラッシュを置く。
    function v28EntryFlash(t0, posAt, dur, kind) {
      const step = 1 / 120;
      for (let u = 0; u <= dur + 1e-9; u += step) {
        const q = posAt(Math.min(u, dur));
        if (q[0] >= 0 && q[0] <= COLS * CELL && q[1] >= 0 && q[1] <= ROWS * CELL) {
          s.at(t0, flashPop(
            [normalizeNegativeZero(q[0]), normalizeNegativeZero(q[1])],
            Math.min(u, dur), METEOR_FLASH_S0, METEOR_FLASH_S1, METEOR_FLASH_DUR, kind
          ));
          return;
        }
      }
    }

    // 隕石の爆破一式（v27 (15) と同じ円形リング＋破片＋放射弾）。
    function v28MeteorBlast(t, pos, idx) {
      s.at(t, meteorBurstFx(pos, 1.0, 'meteorhit'));   // v29b: 輪郭リング＋欠片
      s.at(t, burst(pos, idx, 1.2));
    }

    // v29 (8): 指示 117.795「ここら辺全体的に隕石爆破が早すぎるので遅くして」。
    //   爆破の時刻はマーカー＝曲のオンセットなので動かせない。そこで「発射から爆破までの
    //   飛行時間」を 1.4 倍に伸ばし、そのぶん発射を前へ出す（＝隕石がゆっくり長く見える）。
    //   衝突するシャベルの飛行時間も同じだけ伸びる。
    const V29_METEOR_SLOW = 1.4;

    // --- 1〜5: 打ち上げ隕石とシャベルの衝突（点対称に 2 回）→ 中央へ落下隕石 --------
    //   lightspeed = true のとき、最後の着弾をマーカー 48 の集合爆破と同じ部品
    //   （白く育つブルーム＋2 重リングの放射弾）に差し替える。
    function v28BlockA(tA1, tA2, tA3, tA4, idx, lightspeed) {
      // (a) 左下の画面外から上向きに打ち上がり、下向き重力で減速して tA2 に頂点で静止
      const dL = (tA2 - tA1) * V29_METEOR_SLOW;   // v29 (8): 飛行を 1.4 倍に伸ばす
      const tL0 = tA2 - dL;                       //          そのぶん発射を前へ出す
      const vyL = (2 * (V28_UP_APEX[1] - V28_UP_FROM[1])) / dL;
      const velL = [(V28_UP_APEX[0] - V28_UP_FROM[0]) / dL, vyL];
      const segL = [{ dur: dL, ax: 0, ay: -vyL / dL }];
      s.at(tL0, meteorPath(V28_UP_FROM, velL, segL, 'meteorup'));
      s.at(tL0, meteorPathTrail(V28_UP_FROM, velL, segL, dL, 'meteoruptrail'));
      v28EntryFlash(tL0, meteorPathPos(V28_UP_FROM, velL, segL), dL, 'meteorspawn');
      // 同時に右から 1 本シャベルが飛んできて、頂点でちょうどぶつかる
      s.at(tL0, shovel({
        pos: [SHOVEL_RIGHT_X, V28_UP_APEX[1]],
        vel: [(V28_UP_APEX[0] - SHOVEL_RIGHT_X) / dL, 0],
        angle: SHOVEL_ANGLE_LEFT,
        life: dL,
      }));
      v28MeteorBlast(tA2, V28_UP_APEX, idx);

      // (b) 中心 (16,9) について点対称の右側。右上から下向きに出て上向き重力で減速し、
      //     左から来るシャベルと tA3 でぶつかる。
      const symFrom = [2 * V28_CENTER[0] - V28_UP_FROM[0], 2 * V28_CENTER[1] - V28_UP_FROM[1]];
      const symApex = [2 * V28_CENTER[0] - V28_UP_APEX[0], 2 * V28_CENTER[1] - V28_UP_APEX[1]];
      const dR = (tA3 - tA2) * V29_METEOR_SLOW;   // v29 (8)
      const tR0 = tA3 - dR;
      const vyR = (2 * (symApex[1] - symFrom[1])) / dR;
      const velR = [(symApex[0] - symFrom[0]) / dR, vyR];
      const segR = [{ dur: dR, ax: 0, ay: -vyR / dR }];
      s.at(tR0, meteorPath(symFrom, velR, segR, 'meteorup'));
      s.at(tR0, meteorPathTrail(symFrom, velR, segR, dR, 'meteoruptrail'));
      v28EntryFlash(tR0, meteorPathPos(symFrom, velR, segR), dR, 'meteorspawn');
      s.at(tR0, shovel({
        pos: [SHOVEL_LEFT_X, symApex[1]],
        vel: [(symApex[0] - SHOVEL_LEFT_X) / dR, 0],
        angle: SHOVEL_ANGLE_RIGHT,
        life: dR,
      }));
      v28MeteorBlast(tA3, symApex, idx + 1);

      // (c) tA3 から中央に旧来の（等加速で落ちる）隕石。tA4 に床へ着く。
      //     落下加速度は v27 (14) で決めた METEOR_DROP_ACCEL のまま。指定時刻に着くよう
      //     初速だけを逆算する（速度感は既存の落下隕石と同じになる）。
      const dM = (tA4 - tA3) * V29_METEOR_SLOW;   // v29 (8)
      const tM0 = tA4 - dM;
      const dyM = V28_MID_SPAWN_Y - METEOR_DROP_Y;
      const vyM = (0.5 * METEOR_DROP_ACCEL * dM * dM - dyM) / dM;
      const midFrom = [V28_CENTER[0], V28_MID_SPAWN_Y];
      const segM = [{ dur: dM, ax: 0, ay: -METEOR_DROP_ACCEL }];
      s.at(tM0 - beats(1), meteorDropWarn(V28_CENTER[0], beats(1)));
      s.at(tM0, meteorPath(midFrom, [0, vyM], segM, 'meteordrop'));
      s.at(tM0, meteorPathTrail(midFrom, [0, vyM], segM, dM, 'meteordroptrail'));
      const impact = [V28_CENTER[0], METEOR_DROP_Y];
      s.at(tA4, meteorSquash(impact));
      if (!lightspeed) {
        v28MeteorBlast(tA4, impact, idx + 2);
      } else {
        // 集合爆破（マーカー 48）と同じ「白く育つブルーム → 2 重リング」。
        s.at(tM0, warnClip([{
          type: BLINK_TYPE,
          pos: impact,
          scale: [GATHER_BLOOM_S0, GATHER_BLOOM_S0],
          color: GATHER_BLOOM_C0,
          scaleEnd: [GATHER_BLOOM_S1, GATHER_BLOOM_S1],
          colorEnd: GATHER_BLOOM_C1,
          animDuration: dM,
          appearTime: 0,
          appearDuration: 0,
          life: dM + FADE_OUT_SEC,
        }], 'gatherbloom'));
        s.at(tA4, meteorBurstFx(impact, 1.2, 'meteorhit'));   // v29b: 輪郭リング＋欠片
        const ringN = Math.round(D(10, 12, 14) * 2);
        s.at(tA4, spinBurst({
          pos: impact, count: ringN, speed: D(7, 9, 11), type: 'stone3_bullet', life: 0,
          scale: [BULLET_SCALE, BULLET_SCALE], color: SPRITE_AS_IS,
          angleOffset: rng() * 2 * Math.PI, spin: SPIN_RATE, kind: 'blast', unCounterable: true,
        }));
        s.at(tA4, spinBurst({
          pos: impact, count: ringN, speed: D(11, 14, 17), type: 'stone3_bullet', life: 0,
          scale: [BULLET_SCALE, BULLET_SCALE], color: SPRITE_AS_IS,
          angleOffset: rng() * 2 * Math.PI + Math.PI / ringN, spin: -SPIN_RATE,
          kind: 'blast', unCounterable: true,
        }));
      }
    }

    v28BlockA(V28_A1, V28_A2, V28_A3, V28_A4, 0, false);
    // 5: 同じブロックをもう一度。相対間隔はそのまま写す（マーカーは頭の 1 点しかない）。
    v28BlockA(
      V28_A5,
      V28_A5 + (V28_A2 - V28_A1),
      V28_A5 + (V28_A3 - V28_A1),
      V28_A5 + (V28_A4 - V28_A1),
      3, true
    );

    // --- 6〜7 / 10: 落ちてきて（上がってきて）止まる隕石 3 発＋順に割るシャベル ------
    //   「重力付き」= 初速を持って入り、逆向きの一定加速度で減速して静止する。
    //   静止したあとはシャベルが来るまでその場で自転しながら待つ。
    function v28RestBlock(tAppear, tHit, restY, fromY, idx) {
      const dv = (2 * (restY - fromY)) / V28_REST_FALL;   // 入ってくるときの初速
      const acc = -dv / V28_REST_FALL;                    // 静止するための逆向き加速度
      V28_REST_XS.forEach(function (x, k) {
        const from = [x, fromY];
        const segs = [
          { dur: V28_REST_FALL, ax: 0, ay: acc },
          { dur: tHit[k] - tAppear[k] - V28_REST_FALL, ax: 0, ay: 0, vx: 0, vy: 0 },
        ];
        s.at(tAppear[k], meteorPath(from, [0, dv], segs, 'meteorrest'));
        s.at(tAppear[k], meteorPathTrail(from, [0, dv], segs, V28_REST_FALL, 'meteorresttrail'));
        v28EntryFlash(tAppear[k], meteorPathPos(from, [0, dv], segs), V28_REST_FALL, 'meteorspawn');
        v28MeteorBlast(tHit[k], [x, restY], idx + k);
      });
      // 3 発を順に割る 1 本のシャベル。①と③の時刻で決めた等速で左から入る
      //   （②の通過は設計上 +2.9 ms ずれる。3 発が等間隔・時刻もほぼ等間隔なので実害なし）。
      const sp = (V28_REST_XS[2] - V28_REST_XS[0]) / (tHit[2] - tHit[0]);
      s.at(tHit[0] - (V28_REST_XS[0] - SHOVEL_LEFT_X) / sp, shovel({
        pos: [SHOVEL_LEFT_X, restY],
        vel: [sp, 0],
        angle: SHOVEL_ANGLE_RIGHT,
        life: (SHOVEL_RIGHT_X - SHOVEL_LEFT_X) / sp,
      }));
    }

    v28RestBlock(
      [V28_B1, V28_B2, V28_B3], [V28_C1, V28_C2, V28_C3],
      V28_REST_LOW_Y, V28_REST_FROM_Y, 6
    );
    // 10: 同じ攻撃を上下反転して上側で。頭（V28_E_TOP）以外のマーカーが無いので、
    //     6〜7 の相対間隔をそのまま写す。
    const V28_E_SHIFT = V28_E_TOP - V28_B1;
    v28RestBlock(
      [V28_B1 + V28_E_SHIFT, V28_B2 + V28_E_SHIFT, V28_B3 + V28_E_SHIFT],
      [V28_C1 + V28_E_SHIFT, V28_C2 + V28_E_SHIFT, V28_C3 + V28_E_SHIFT],
      V28_REST_HIGH_Y, V28_REST_UP_Y, 9
    );

    // --- 8: 右側から縦一列のシャベルを、上から順に半拍ずつずらして発射 --------------
    const V28_SIDE_LIFE = (SHOVEL_RIGHT_X - SHOVEL_LEFT_X) / SHOVEL_SIDE_SPEED;
    V28_SIDE_YS.forEach(function (y, k) {
      s.at(V28_D_SIDE + k * V28_SIDE_STAGGER, shovel({
        pos: [SHOVEL_RIGHT_X, y],
        vel: [-SHOVEL_SIDE_SPEED, 0],
        angle: SHOVEL_ANGLE_LEFT,
        life: V28_SIDE_LIFE,
      }));
    });

    // --- 9: 上側から、左から順に 1/3 拍ずつずらしてシャベルを落とす -----------------
    const V28_TOP_LIFE = (SHOVEL_SPAWN_Y - V28_TOP_FALL_END_Y) / SHOVEL_FALL_SPEED;
    V28_TOP_XS.forEach(function (x, k) {
      s.at(V28_D_TOP + k * V28_TOP_STAGGER, shovel({
        pos: [x, SHOVEL_SPAWN_Y],
        vel: [0, -SHOVEL_FALL_SPEED],
        angle: SHOVEL_ANGLE_DOWN,
        life: V28_TOP_LIFE,
      }));
    });

    // --- 11〜12: 一列に揃えたシャベルの壁を右から左へ。1 レーンだけ空けて抜け穴にする -
    [[V28_F1, V28_WALL_GAP1], [V28_F2, V28_WALL_GAP2]].forEach(function (w) {
      V28_WALL_YS.forEach(function (y, k) {
        if (w[1].indexOf(k) >= 0) return;   // ここが抜け穴
        s.at(w[0], shovel({
          pos: [SHOVEL_RIGHT_X, y],
          vel: [-SHOVEL_SIDE_SPEED, 0],
          angle: SHOVEL_ANGLE_LEFT,
          life: V28_SIDE_LIFE,
        }));
      });
    });

    // --- 13〜14: 静かな区間の隕石。上から下へ落ちるだけで、爆破も放射弾も出さない ----
    [[V28_G_L, V28_QUIET_XS[0]], [V28_G_R, V28_QUIET_XS[1]]].forEach(function (q) {
      const x = q[1];
      const v = (V28_QUIET_END_Y - V28_QUIET_SPAWN_Y) / V28_QUIET_FLIGHT;
      const from = [x, V28_QUIET_SPAWN_Y];
      const segs = [{ dur: V28_QUIET_FLIGHT, ax: 0, ay: 0 }];
      s.at(q[0] - beats(1), meteorDropWarn(x, beats(1)));
      s.at(q[0], meteorPath(from, [0, v], segs, 'meteorquiet'));
      s.at(q[0], meteorPathTrail(from, [0, v], segs, V28_QUIET_FLIGHT, 'meteorquiettrail'));
      v28EntryFlash(q[0], meteorPathPos(from, [0, v], segs), V28_QUIET_FLIGHT, 'meteorspawn');
    });

    // --- 15: 上側を右→左、下側を左→右へすれ違う 2 発。爆破なし・「ゆっくりめ」 ------
    [
      [METEOR_START_X, METEOR_END_X, V28_CROSS_TOP_Y],
      [-2.5, 36.0, V28_CROSS_BOT_Y],
    ].forEach(function (c) {
      const x0 = c[0], x1 = c[1], y = c[2];
      s.at(V28_H - beats(1), meteorRowWarn(y, beats(1)));
      const edgeX = x0 < x1 ? 0 : COLS * CELL;
      s.at(V28_H, flashPop(
        [edgeX, y], ((edgeX - x0) / (x1 - x0)) * V28_CROSS_FLIGHT,
        METEOR_FLASH_S0, METEOR_FLASH_S1, METEOR_FLASH_DUR, 'meteorspawn'
      ));
      s.at(V28_H, meteorLine(x0, x1, y, V28_CROSS_FLIGHT));
      s.at(V28_H, meteorLineTrail(x0, x1, y, V28_CROSS_FLIGHT));
    });

    // --- 16〜17: 最後の 1 発と大爆破 ---------------------------------------------
    //   中央上から中央へ 2 拍かけて減速して寄り（イージング）、0.75 拍で 1.2 ユニット
    //   上へ戻し（ため）、残り 1.25 拍で加速して床へ。V28_END_BLAST ちょうどに着く。
    //   「戻り → 加速で指定時刻ちょうどに着弾」の式は集合爆破・v27(C) の横シャベルと同じ。
    const V28_FIN_DIVE = (V28_END_BLAST - V28_I) - V28_FIN_EASE - V28_FIN_BACK;
    const finVA = (2 * (V28_FIN_HOLD_Y - V28_FIN_FROM_Y)) / V28_FIN_EASE;
    const finAB = (2 * V28_FIN_BACK_D) / (V28_FIN_BACK * V28_FIN_BACK);
    const finYB = V28_FIN_HOLD_Y + V28_FIN_BACK_D;
    const finVB = finAB * V28_FIN_BACK;
    const finAC = (2 * (METEOR_DROP_Y - finYB - finVB * V28_FIN_DIVE))
      / (V28_FIN_DIVE * V28_FIN_DIVE);
    const finFrom = [V28_CENTER[0], V28_FIN_FROM_Y];
    const finSegs = [
      { dur: V28_FIN_EASE, ax: 0, ay: -finVA / V28_FIN_EASE },
      { dur: V28_FIN_BACK, ax: 0, ay: finAB, vx: 0, vy: 0 },
      { dur: V28_FIN_DIVE, ax: 0, ay: finAC },
    ];
    const finTotal = V28_FIN_EASE + V28_FIN_BACK + V28_FIN_DIVE;
    const finPos = [V28_CENTER[0], METEOR_DROP_Y];
    s.at(V28_I - beats(1), meteorDropWarn(V28_CENTER[0], beats(1)));
    s.at(V28_I, meteorPath(finFrom, [0, finVA], finSegs, 'meteorfinal'));
    s.at(V28_I, meteorPathTrail(finFrom, [0, finVA], finSegs, finTotal, 'meteorfinaltrail'));
    v28EntryFlash(V28_I, meteorPathPos(finFrom, [0, finVA], finSegs), V28_FIN_EASE, 'meteorspawn');
    // 着弾点が「ため」の頭から白く育つ（集合爆破のブルームと同じ作り）
    const finBloomDur = V28_FIN_BACK + V28_FIN_DIVE;
    s.at(V28_I + V28_FIN_EASE, warnClip([{
      type: BLINK_TYPE,
      pos: finPos,
      scale: [GATHER_BLOOM_S0, GATHER_BLOOM_S0],
      color: GATHER_BLOOM_C0,
      scaleEnd: [GATHER_BLOOM_S1 * 1.4, GATHER_BLOOM_S1 * 1.4],
      colorEnd: GATHER_BLOOM_C1,
      animDuration: finBloomDur,
      appearTime: 0,
      appearDuration: 0,
      life: finBloomDur + FADE_OUT_SEC,
    }], 'gatherbloom'));
    // 大爆破: 円形リング 5 枚＋破片 3 段＋放射弾 3 重リング（この曲でいちばん派手なもの）
    s.at(V28_END_BLAST, meteorSquash(finPos));
    s.at(V28_END_BLAST, roundBlastFx(finPos, FINAL_RING_SPEC, 'meteorhit'));
    s.at(V28_END_BLAST, debrisRing(finPos, 28, 11.0, 0.65, TILE * 0.48, 6.0, 0));
    s.at(V28_END_BLAST, debrisRing(finPos, 20, 7.0, 0.85, TILE * 0.34, -4.5, Math.PI / 20));
    s.at(V28_END_BLAST, debrisRing(finPos, 14, 4.0, 1.05, TILE * 0.24, 3.0, Math.PI / 14));
    const finRingN = Math.round(D(10, 12, 14) * 2.5);
    [
      [D(6, 8, 10), SPIN_RATE, 0],
      [D(10, 13, 16), -SPIN_RATE, Math.PI / finRingN],
      [D(15, 19, 23), SPIN_RATE, Math.PI / (2 * finRingN)],
    ].forEach(function (r) {
      s.at(V28_END_BLAST, spinBurst({
        pos: finPos,
        count: finRingN,
        speed: r[0],
        type: 'stone3_bullet',
        life: 0,
        scale: [BULLET_SCALE, BULLET_SCALE],
        color: SPRITE_AS_IS,
        angleOffset: rng() * 2 * Math.PI + r[2],
        spin: r[1],
        kind: 'blast',
        unCounterable: true,
      }));
    });
  }
);
